const SLUG_ALIASES = {};
const TRICKS = [{"name":"Barrel Roll","difficulty":"Beginner","category":"Open Air","howto":"A roll flown as a corkscrew rather than on the axis, the quad spiraling around its line of travel. Settle onto a line, corkscrew through the barrel, and catch level on the same track. The wider, looping path is what separates it from a tight axial roll.","mastery":["Corkscrew through a barrel roll and recover.","Smooth, round barrel roll holding the line.","Clean barrel roll at any size, both directions."],"steps":["Settle onto a line","Corkscrew through a barrel roll","Catch level on the same track"],"prereqs":["A clean axial roll","Coordinated roll and pitch"],"practice":"Open air. Fly the roll as a wide corkscrew, coordinating a little pitch with the roll so the path loops out and back, and catch level on your track. Both directions.","mistakes":["Rolling on the axis instead of corkscrewing","An uneven, wobbly barrel","Drifting off the line"],"variations":[{"name":"Roll","note":"A tight axial roll.","slug":"roll"},{"name":"Double Roll","note":"Two rolls in a row.","slug":"double-roll"}],"related":[{"name":"Roll","note":"The axial version.","slug":"roll"},{"name":"Power Drill","note":"A vertical corkscrew.","slug":"power-drill"}],"sources":["Rotor Riot"],"page":7,"pdfPage":9,"slug":"barrel-roll","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Building Dive","difficulty":"Beginner","category":"Wall Tricks","howto":"A committed descent down the face of a tall structure. Cross the roofline with your speed under control, then drop the nose and track straight down the face, staying close but never clipping it. As the ground rushes up, flare the nose back to level and feed in throttle so you pull out smoothly along the base.","mastery":["Dive the face and pull out level before the ground.","Tight, controlled descent close to the face with a smooth flare.","Fast committed dive hugging the building, flared level at the base."],"steps":["Cross the roofline with your speed in check","Commit the nose down and track the face","Flare the nose up and feed throttle to level out"],"prereqs":["Confident fast descents with a clean pull-out","Good speed judgement near a surface"],"practice":"Start on a modest drop with plenty of run-out at the bottom before trying anything tall. Scout the base for obstacles, you need clean air to flare into. Keep some throttle in reserve for the pull-out.","mistakes":["Diving too fast to arrest before the ground","Drifting into the face on the way down","Flaring too late, so you pancake at the base"],"variations":[{"name":"Roof gap dive","note":"Drop through a gap in the roofline before the face."},{"name":"Spiral dive","note":"Add rotation on the way down."}],"related":[{"name":"Wall Ride","note":"Tracking a vertical surface, but alongside it.","slug":"wall-ride"},{"name":"Split S","note":"Another way to trade altitude fast.","slug":"split-s"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":8,"pdfPage":10,"slug":"building-dive","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/building-dive/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=xCgcLMnap1g"}]},{"name":"Cinnamon Roll","difficulty":"Beginner","category":"Jump Ropes","howto":"A jump rope with a roll baked in. Swing up toward the top of an object as you would a jump rope, but roll the quad as you arc over, then drop back down the same side. The roll adds a twist of style to the up-and-over rhythm.","mastery":["Add a roll to the jump-rope swing.","Smooth roll folded into an even swing.","Rhythmic swings with a clean roll, over and back."],"steps":["Swing up toward the top","Roll as you arc over","Drop back down the same side"],"prereqs":["A solid jump rope","A controllable roll"],"practice":"Get the jump-rope rhythm down first, then add the roll as you go over the top. Keep it smooth and even so the roll flows with the swing.","mistakes":["Rolling too fast, breaking the rhythm","A lopsided swing","Losing the object as you roll"],"variations":[{"name":"Jump Rope","note":"Without the roll.","slug":"jump-rope"},{"name":"Burrito Roll","note":"Roll the other way and go under.","slug":"burrito-roll"}],"related":[{"name":"Jump Rope","note":"The base swing.","slug":"jump-rope"},{"name":"Burrito Roll","note":"A jump-rope roll that finishes under.","slug":"burrito-roll"}],"sources":["Pro Whooper"],"page":9,"pdfPage":11,"slug":"cinnamon-roll","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"originator":"Shauny D","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/cinnamon-roll/"}]},{"name":"Cradle","difficulty":"Beginner","category":"Orbitals","howto":"A tracking pass that ends flying backward. Fly past an object, then pitch backward to track it and keep it in view. As you pick up backward momentum, level out by pitching forward again and continue flying backward until you have completely cleared the object. It is mostly pitch, leaning the quad back then forward, with just enough roll or yaw to shift smoothly around the object, and you keep it in view the whole time.","mastery":["Fly past the object and back up, keeping it in view.","Smooth pitch-back and level backward pass, object framed.","Seamless forward-to-backward pass, object locked in view."],"steps":["Fly forward past the object","Pitch back to track it and pick up backward momentum","Pitch forward to level, drift backward until cleared"],"prereqs":["Confident backward flight","Tracking an object while maneuvering"],"practice":"Pick an isolated post or object. Fly past it, then pitch back to slow and reverse while keeping it framed, and drift backward until you have cleared it. It is all in smooth pitch control, with only a little roll or yaw to shift around the object.","mistakes":["Losing the object out of frame","Pitching back too hard and climbing away","Too much roll or yaw, swinging off the track"],"variations":[{"name":"Inverted Cradle","note":"Carry the pitch-back all the way to inverted."},{"name":"Cradle Rewind","note":"Pitch forward again and rewind past the object."}],"related":[{"name":"Orbits","note":"Another object-tracking maneuver.","slug":"orbits"},{"name":"Side-Lock Rewind","note":"A tracking rewind past an object.","slug":"side-lock-rewind"},{"name":"Trippy Spin","note":"Builds on the cradle, taken inverted.","slug":"trippy-spin"}],"sources":["Pro Whooper"],"page":10,"pdfPage":12,"slug":"cradle","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":true},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/cradle/"}]},{"name":"Dive","difficulty":"Beginner","category":"Open Air","howto":"The basic descent: drop the nose and dive, then pull out. From level flight cross into the dive with your speed in check, commit the nose down to track the line down, and flare to level as the ground comes up. It is the foundation for building dives and every steep descent.","mastery":["Dive the line and pull out before the ground.","Controlled dive with a smooth level pull-out.","Fast, committed dive flared clean at the bottom."],"steps":["Cross with speed in check","Drop the nose and dive","Flare and pull out low"],"prereqs":["Confident forward flight","A feel for pulling out of a descent"],"practice":"Start with shallow dives and plenty of run-out, steepening as your pull-out gets clean. Keep some throttle in reserve to flare. Watch your altitude.","mistakes":["Diving too steep to arrest in time","Pulling out too late","Ballooning instead of tracking the line down"],"variations":[{"name":"Building Dive","note":"A dive down a structure's face.","slug":"building-dive"},{"name":"Backwards Dive","note":"The same dive flown tail-first.","slug":"backwards-dive"}],"related":[{"name":"Building Dive","note":"A committed dive down a face.","slug":"building-dive"},{"name":"Split S","note":"Another way to trade altitude.","slug":"split-s"}],"sources":["Rotor Riot"],"page":11,"pdfPage":13,"slug":"dive","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Double Flip","difficulty":"Beginner","category":"Open Air","howto":"Two flips in a row. From level flight punch full forward pitch and let the quad rotate through two complete loops on the pitch axis in one motion, keeping the throttle low so you hold your height, then catch level and carry on. Pace it so you do not over-rotate the second flip.","mastery":["Two flips and recover to level.","Even flips with no altitude gain, clean catch.","Two tight, on-axis flips holding the line, both directions."],"steps":["Cruise level with room above","Two flips back to back","Catch level and continue"],"prereqs":["A clean single flip","Enough altitude for two rotations"],"practice":"High over open grass. Link the two flips without a pause and keep throttle low so you do not climb. Catch level the moment the second flip comes around.","mistakes":["Ballooning up through the flips","Pausing between rotations","Catching late on the second flip"],"variations":[{"name":"Triple Flip","note":"Three loops linked in one motion."},{"name":"Double Roll","note":"The doubled idea on the roll axis.","slug":"double-roll"}],"related":[{"name":"Flip","note":"The single version.","slug":"flip"},{"name":"Double Roll","note":"Two rolls instead of flips.","slug":"double-roll"}],"sources":["Pro Whooper"],"page":12,"pdfPage":14,"slug":"double-flip","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/double-flip/"}]},{"name":"Double Roll","difficulty":"Beginner","category":"Open Air","howto":"Two back-to-back rolls. Hold a straight, level line and roll the quad through two full rotations in one smooth, continuous motion, keeping the throttle steady so the line stays flat, then catch level on the same track. It is the single roll doubled, so pace the rate that the second rotation is as clean as the first.","mastery":["Two full rolls and recover on the same line.","Smooth, even rolls with no heading drift.","Two crisp rolls at any rate, both directions, dead on line."],"steps":["Settle onto a straight, level line","Two full rolls in a row","Catch level on the same track"],"prereqs":["A clean single roll","Steady throttle through rotation"],"practice":"Plenty of height. Link two rolls in one motion rather than pausing between them, and keep the rate even so both come out clean.","mistakes":["Pausing between the two rolls","Throttle sag on the second rotation","Drifting off the line"],"variations":[{"name":"Juicy Double Roll","note":"The double roll flown out of a juicy flick.","slug":"juicy-double-roll"},{"name":"Triple Roll","note":"Three rotations linked in one pass."},{"name":"Vanny Roll","note":"A roll carried through a turn around an obstacle.","slug":"vanny-roll"}],"related":[{"name":"Roll","note":"The single-rotation version.","slug":"roll"},{"name":"Double Flip","note":"The same idea on the pitch axis.","slug":"double-flip"}],"sources":["Pro Whooper"],"page":13,"pdfPage":15,"slug":"double-roll","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/double-roll/"}]},{"name":"Face Punch","difficulty":"Beginner","category":"Miscellaneous","howto":"A hard vertical punch-out. From a level line, slam full throttle to rocket straight up, riding the acceleration as high as you dare before you level off. It is the simplest show of power in the book, all about a clean, committed, dead-vertical line.","mastery":["Punch out into a fast vertical climb.","Clean, straight punch with a controlled top.","Explosive, dead-vertical punch, held straight all the way up."],"steps":["Line up level with speed","Punch full throttle straight up","Ride the climb out"],"prereqs":["Confident, aggressive throttle","A feel for when to level off"],"practice":"Open air with plenty of ceiling. Punch straight up and hold the vertical, then level off with room to spare. Watch your battery, a hard punch draws a lot of current.","mistakes":["Drifting off vertical under power","Punching so hard you lose orientation","Leaving no room to level off"],"variations":[{"name":"Power Flip","note":"Add a flip on the way up.","slug":"power-flip"},{"name":"Power Roll","note":"Add a roll on the way up.","slug":"power-roll"}],"related":[{"name":"Power Flip","note":"A punch with a flip in it.","slug":"power-flip"},{"name":"Powerloop","note":"Another power-throttle move.","slug":"powerloop"}],"sources":["Pro Whooper"],"page":14,"pdfPage":16,"slug":"face-punch","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/face-punch/"}]},{"name":"Flip","difficulty":"Beginner","category":"Open Air","howto":"The building-block rotation. From level flight, feed in a touch of throttle for a cushion of altitude, then punch full forward pitch and let the quad whip all the way around the pitch axis. Keep the throttle low through the rotation so you climb as little as possible, and catch the stick back to level the instant the horizon comes back around. Feed throttle in again on the exit and carry the same line.","mastery":["Complete the rotation and recover to level without hitting the ground.","Consistent height and a clean level catch, both directions.","Tight, on-axis flip that holds its line with no altitude gain."],"steps":["Cruise level, blip a little altitude","Punch full forward pitch, let it rotate a full 360","Catch level as the horizon returns, feed throttle back"],"prereqs":["Stable hover and level cruise in acro (rate) mode","Enough altitude that a late catch still recovers"],"practice":"Do them high over open grass first. A flip only needs airspace, no obstacle, which is why it is usually the very first trick. Drop the entry height as your catch gets consistent.","mistakes":["Not enough altitude, so a slightly late catch ends in the ground","Carrying too much throttle and ballooning up through the rotation","Catching late and over-rotating past level"],"variations":[{"name":"Double Flip","note":"Two full pitch rotations back to back before catching level.","slug":"double-flip"},{"name":"Flip Rewind","note":"Flip, then reverse back along the entry line out of a stall."}],"related":[{"name":"Roll","note":"The same idea on the roll axis instead of pitch.","slug":"roll"},{"name":"Powerloop","note":"A flip translated up and over an obstacle with throttle.","slug":"powerloop"},{"name":"Matty Flip","note":"A partial flip over a gap while tracking a subject.","slug":"matty-flip"}],"sources":["Pro Whooper"],"page":15,"pdfPage":17,"slug":"flip","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/flip/"}]},{"name":"Gaps","difficulty":"Beginner","category":"Gaps","howto":"Threading a gap is about commitment and a clean line, not a rotation. Pick the opening early and line the quad up pointed through it well before you arrive, then hold that line all the way through, do not grab for corrections in the gap itself. Look through the opening to where you want to exit, not at the frame of the gap. Speed is your friend once the line is set.","mastery":["Clear the gap cleanly on a committed line.","Smooth line with no last-second corrections, repeatable.","Fast, tight gaps taken on any chosen line without hesitation."],"steps":["Spot the opening and line up early","Commit and thread the gap on a fixed line","Hold the line out the far side"],"prereqs":["Confident, stable forward flight","Good depth perception through the goggles"],"practice":"Start with wide, forgiving gaps, a soccer goal, a wide doorway, the space between two trees, and shrink them as your line gets repeatable. Always scout the gap and its approach before committing.","mistakes":["Staring at the frame of the gap instead of through it","Making late stick corrections inside the opening","Approaching at an angle instead of squared up"],"variations":[{"name":"Low gap","note":"An opening threaded fast and close to the ground."},{"name":"Angled gap","note":"A gap taken on a banked, non-level line."}],"related":[{"name":"Wall Ride","note":"Proximity flying along a surface rather than through it.","slug":"wall-ride"},{"name":"Powerloop","note":"Often set up by threading a gap first.","slug":"powerloop"}],"sources":["Pro Whooper","Rotor Riot"],"page":16,"pdfPage":18,"slug":"gaps","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/gaps-2/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Knife Edge","difficulty":"Beginner","category":"Gaps","howto":"Threading a slot too narrow to fly through flat. Line up the opening early, then roll the quad up onto its side, knife-edge, so its narrow profile fits the gap, hold that bank through the opening, and roll level again on the far side. Commit to the line before the gap and look through it, not at it.","mastery":["Fit through the narrow gap on the roll axis.","Clean knife-edge with a level exit.","Tight gaps taken knife-edge on a committed line."],"steps":["Pick a comfortable gap","Roll 90° onto the drone's side","Fly through sideways, watching exit momentum"],"prereqs":["Confident, stable forward flight","A controllable 90 degree roll and hold"],"practice":"Start with taller, wider slots, a doorway or a gap between close trees, and narrow them as your knife-edge holds steady. Set the bank before the gap, not in it.","mistakes":["Rolling in the gap instead of before it","Not enough bank to clear the sides","Grabbing corrections mid-gap"],"variations":[{"name":"Reverse Knife Edge","note":"Knife-edge banked the other way.","slug":"reverse-knife-edge"},{"name":"Ninja Star","note":"A knife-edge gap taken as part of a combo.","slug":"ninja-star"}],"related":[{"name":"Gaps","note":"Threading an opening on a flat line.","slug":"gaps"},{"name":"Roll","note":"The roll that sets the knife-edge.","slug":"roll"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":17,"pdfPage":19,"slug":"knife-edge","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/knife-edge/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=FamqCNGrq2M"}]},{"name":"Land","difficulty":"Beginner","category":"Miscellaneous","howto":"The clean way to end a flight. Line up your descent, ease the throttle down to sink toward the ground, and feather it to a soft touch. A controlled landing protects your quad and looks a lot better than a fall out of the sky.","mastery":["Bring it down and land without a bounce.","Smooth, controlled descent to a soft touch.","Precise landing on a chosen spot, feather-soft."],"steps":["Line up your descent","Ease down toward the ground","Touch down softly"],"prereqs":["Smooth throttle control near the ground","Patience on the descent"],"practice":"Practise slow, controlled descents to a soft touch on a flat, clear spot. The last few inches are all throttle finesse, so take them slow.","mistakes":["Descending too fast and thumping down","Cutting throttle too high and dropping","Landing on uneven ground or debris"],"variations":[{"name":"Slide Disarm","note":"Slide to a stop instead.","slug":"slide-disarm"},{"name":"Perch","note":"Land on top of an object.","slug":"perch"}],"related":[{"name":"Slide Disarm","note":"A sliding finish.","slug":"slide-disarm"},{"name":"Perch","note":"Landing on top of an object.","slug":"perch"}],"sources":["Mazta FPV tutorial"],"page":18,"pdfPage":20,"slug":"land","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=FoThnMhbew0"}]},{"name":"Loop","difficulty":"Beginner","category":"Open Air","howto":"The loop, or flip: a full 360 rotation on the pitch axis, the drone tumbling nose-over-tail through a vertical circle. Carry a level line, pull a full loop, and catch level on the same line. It is one of the first big tricks every pilot learns, and the root of half the tricks in this book.","mastery":["Carry a full loop and recover.","Round, even loop that holds the line.","Clean loops at any size, both directions."],"steps":["Carry a level line","Pull a full loop","Catch level on the line"],"prereqs":["Confident throttle and pitch","Enough altitude for a loop"],"practice":"Give yourself height, carry some speed, and pull a full loop, catching level as it comes back round. Keep it round and even, and try both forward and back.","mistakes":["Not enough speed or height to carry the loop","An egg-shaped, uneven loop","Dropping altitude through the top"],"variations":[{"name":"Double Flip","note":"Two loops in a row.","slug":"double-flip"},{"name":"Laser Flip","note":"A tight, fast loop that holds the line.","slug":"laser-flip"}],"related":[{"name":"Flip","note":"A tight version of the same rotation.","slug":"flip"},{"name":"Powerloop","note":"A loop flown around an object.","slug":"powerloop"}],"sources":["Rotor Riot"],"page":19,"pdfPage":21,"slug":"loop","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Maverick Loop","difficulty":"Beginner","category":"Maverick Loops","howto":"A powerloop you never invert for: instead of pitching forward through inverted, you pitch back and carry the loop around the object, staying forward-facing the whole time. Approach under the object, pitch back and climb above it, hold the back-pitch over the top moving backwards, then drop throttle to return and pass under again. The quad stays upright throughout, which is what sets it apart from a powerloop.","mastery":["Loop around the object without inverting.","Round loop, forward-facing the whole way.","Tight, committed loop, upright and dead on line."],"steps":["Approach under the obstacle","Pitch back and climb above the object","Over the top, then drop throttle to return","Pass back under the object"],"prereqs":["A confident powerloop","Comfortable carrying a hard back-pitch"],"practice":"Find a horizontal object with clear air around it, a beam, branch, or bar. Approach under it, pitch back to climb above, carry the loop over the top moving backwards, then drop throttle to return under. Keep the quad upright the whole way, never letting it pitch through inverted.","mistakes":["Letting it pitch through inverted like a powerloop","Not enough height to clear the top","Ballooning into the object on the way over"],"variations":[{"name":"Half Mavvy","note":"Only the bottom half of the loop.","slug":"half-mavvy"},{"name":"Mavvelmann","note":"A Maverick loop into an Immelmann exit.","slug":"mavvelmann"}],"related":[{"name":"Powerloop","note":"The inverted, forward-pitching cousin.","slug":"powerloop"},{"name":"Immelmann","note":"Shares the looping mechanic.","slug":"immelmann"}],"sources":["Pro Whooper"],"page":20,"pdfPage":22,"slug":"maverick-loop","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/maverick-loop/"}]},{"name":"Orbits","difficulty":"Beginner","category":"Orbitals","howto":"Approach the object head-on but slightly to the side. Add roll toward the object plus a bit of yaw the same way and a tiny amount of pitch: the roll tilts the drone, the mixed yaw counterbalances the tilt to keep it level, and the pitch supplies forward momentum around the object. Keep the object slightly off-center to hold your orbit distance and speed.","mastery":["Fly a full circle around the subject keeping it in frame.","Round, constant-radius orbit with the subject held centered.","Smooth cinematic orbits at any radius, both directions, subject locked."],"steps":["Approach with the subject off one side","Bank and yaw together, camera locked on the center","Release on a tangent when you have the shot"],"prereqs":["Coordinated turns, banking and yawing together","Keeping a subject framed while moving"],"practice":"Pick an isolated subject with room around it, a lone tree, a cone, a friend, and fly complete circles at a fixed radius. Both directions. Holding the radius and height constant is the whole skill.","mistakes":["Yaw and roll out of sync, so the circle turns egg-shaped","Letting the nose drift off the subject","Changing radius or height mid-orbit"],"variations":[{"name":"Trippy Spin","note":"An inverted orbit around the top of a pole.","slug":"trippy-spin"},{"name":"Cinematic orbit","note":"A slow, wide orbit flown for smooth video."}],"related":[{"name":"Yaw Spin","note":"Spinning in place instead of circling a subject.","slug":"yaw-spin"},{"name":"Trippy Spin","note":"The inverted, elevated cousin.","slug":"trippy-spin"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":21,"pdfPage":23,"slug":"orbits","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/orbits/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=XJDBezfCwyY"}]},{"name":"Roll","difficulty":"Beginner","category":"Open Air","howto":"The roll is the flip's sideways twin. Hold a straight, level line and roll the quad a full 360 around its roll axis in one smooth motion. Because a roll does not pull the quad off its line the way a flip does, you barely need to touch throttle, just keep it steady and let the roll carry through. Start slow and floaty; speed and style come later.","mastery":["Full 360 roll and recover upright on the same line.","Smooth, steady roll with no throttle sag or heading drift.","Slow, controlled roll you can stop on any point, both directions."],"steps":["Settle onto a straight, level line","Full 360 on the roll axis in one motion","Catch level on the same track"],"prereqs":["Stable level cruise","A horizon or ground reference to catch level against"],"practice":"Open airspace, plenty of height. Pick a direction (most pilots start rolling to their dominant side) and keep the throttle dead steady so you learn the roll in isolation.","mistakes":["Chopping or pumping throttle mid-roll and dropping out","Stopping short of a full rotation and exiting off-axis","Mixing in accidental pitch, so the line bends"],"variations":[{"name":"Double Roll","note":"Two full roll rotations before catching level.","slug":"double-roll"},{"name":"Vanny Roll","note":"A slow, floaty roll carried through a turn.","slug":"vanny-roll"}],"related":[{"name":"Flip","note":"The same rotation on the pitch axis.","slug":"flip"},{"name":"Split S","note":"A half roll to inverted, then a descending half loop.","slug":"split-s"},{"name":"Vanny Roll","note":"The stylish slow-roll variation.","slug":"vanny-roll"}],"sources":["Pro Whooper"],"page":22,"pdfPage":24,"slug":"roll","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/roll/"}]},{"name":"Segmented Flips/Rolls","difficulty":"Beginner","category":"Open Air","howto":"A flip or roll broken into stop-and-go segments instead of one smooth rotation. Rotate a quarter turn and stop, hold, then step to the next, working around in clean stages until you are level again. It trains precise rotational control, the ability to stop the rotation exactly where you want.","mastery":["Take a flip or roll around in clean segments.","Even, controlled stops at each quarter.","Crisp segmented rotation, any number of stops."],"steps":["Rotate a quarter and stop","Step through the halfway point","Finish the rotation to level"],"prereqs":["A clean flip and roll","Precise control of the rotation rate"],"practice":"Start with quarter-turn stops on the pitch axis, holding each cleanly, then try the roll axis. The skill is stopping the rotation dead at each stage, so keep the inputs small and deliberate.","mistakes":["Rotation drifting past each stop","Uneven segments","Losing altitude through the stops"],"variations":[{"name":"Segmented Roll","note":"Stop-and-go on the roll axis."},{"name":"Double Flip","note":"The same rotation, done smoothly.","slug":"double-flip"}],"related":[{"name":"Flip","note":"The smooth version.","slug":"flip"},{"name":"Roll","note":"The roll-axis version.","slug":"roll"}],"sources":["Pro Whooper"],"page":23,"pdfPage":25,"slug":"segmented-flips-rolls","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/segmented-flips-rolls/"}]},{"name":"Side-Lock Rewind","difficulty":"Beginner","category":"Orbitals","howto":"Fly past an object, then roll 90° toward it while pitching back to keep it in view. Hold the pitch back until you reach a stall point, then blip throttle to rewind back the way you came. Finally roll away from the object to level out.","mastery":["Rewind back the way you came past the object.","Clean stall and a smooth rewind holding the object in view.","Crisp stall, tidy rewind, and a level roll-away."],"steps":["Fly past the object and roll toward it","Pitch back to a stall, keeping it in view","Blip to rewind back, then roll away level"],"prereqs":["Comfortable reaching and holding a stall","Tracking an object while maneuvering"],"practice":"Pick an isolated pole or post. Fly past it and work the roll-and-pitch to keep it framed as you climb to the stall, then blip back down the same line. Rolling away cleanly at the end is the finishing touch.","mistakes":["Rolling away before the stall, so the rewind never sets up","Losing the object out of frame at the stall point","A harsh blip that throws the rewind off its line"],"variations":[{"name":"Side-Lock Rewind (both sides)","note":"Mirror it on the opposite side of the object."},{"name":"Stall Rewind","note":"The same rewind without the object to track.","slug":"stall-rewind"}],"related":[{"name":"Orbits","note":"Another object-locked maneuver.","slug":"orbits"},{"name":"Snapback","note":"A quicker stop-and-reverse.","slug":"snapback"},{"name":"Wall Ride","note":"More object-and-surface proximity work.","slug":"wall-ride"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":24,"pdfPage":26,"slug":"side-lock-rewind","inputs":[{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":true},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/side-lock-rewind/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Pp1Yowe2M-g"}]},{"name":"Split S","difficulty":"Beginner","category":"Split-S","howto":"A fast way to reverse direction and shed altitude. From level flight, roll a half turn to inverted, then pull back-pitch through a descending half loop. You come out flying the opposite direction and lower than you started, essentially the bottom half of a loop entered upside down. Keep the pull smooth so the exit is level, not a dive.","mastery":["Roll inverted, pull through, and exit the opposite direction upright.","Level exit with no dive and controlled altitude loss.","Tight, symmetric half-loop that exits exactly on the reciprocal line."],"steps":["Approach object and roll inverted","Dive down","Catch and continue"],"prereqs":["A clean half roll to inverted","Comfortable applying pitch while inverted"],"practice":"Give yourself altitude to spend, since the whole trick descends. A split-S is the standard way to turn around and drop into a lower line, so practice it as a transition, not just in isolation.","mistakes":["Pulling too hard and diving out instead of leveling","Not fully inverting before you pull, so the exit corkscrews","Running out of altitude, since the trick always loses height"],"variations":[{"name":"Power Split","note":"Enter from the top of a powerloop instead of level flight.","slug":"power-split"},{"name":"Barani","note":"A split-S with a half twist that exits facing forward.","slug":"barani"}],"related":[{"name":"Immelmann","note":"The reverse: a climbing half loop that gains altitude.","slug":"immelmann"},{"name":"Roll","note":"The half roll that starts the trick.","slug":"roll"},{"name":"Powerloop","note":"Shares the loop mechanic, entered over an obstacle.","slug":"powerloop"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":25,"pdfPage":27,"slug":"split-s","inputs":[{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/split-s-2/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=gepPp2OyXUQ"}]},{"name":"Stall","difficulty":"Beginner","category":"Open Air","howto":"Letting the quad run out of lift and hang, then catching it. Climb until you bleed off speed, chop the throttle so the quad stalls and drops, then feed throttle back in to recover before the ground. The stall is the pause that sets up rewinds and drops.","mastery":["Stall the quad and recover cleanly.","Controlled stall with a smooth drop-out.","Deliberate stall held on the spot, tidy recovery."],"steps":["Climb and bleed off speed","Chop throttle to a stall","Drop, then feed throttle to recover"],"prereqs":["Smooth throttle control","A feel for the point of stall"],"practice":"Climb, chop, and catch, high up with room below. Learn where the stall point is and how much throttle it takes to recover. It is the building block of every stall trick.","mistakes":["Chopping too late, no room to recover","Feeding throttle too hard on recovery","Drifting off the spot in the stall"],"variations":[{"name":"Stall Rewind","note":"Rewind out of the stall.","slug":"stall-rewind"},{"name":"Front Swing","note":"A stall flown off the side of an object.","slug":"front-swing"}],"related":[{"name":"Stall Rewind","note":"A stall into a rewind.","slug":"stall-rewind"},{"name":"Front Swing","note":"A side-on stall.","slug":"front-swing"}],"sources":["Rotor Riot","Mazta FPV tutorial"],"page":26,"pdfPage":28,"slug":"stall","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=_6sEh0KIC_o"}]},{"name":"Stall Rewind","difficulty":"Beginner","category":"Rewinds","howto":"A vertical stall and reverse. Climb straight up until the quad runs out of speed and stalls at the top, hang there for a beat, then blip the throttle to kick it into a rewind straight back down the line it climbed. The cleaner the vertical, the tidier the rewind.","mastery":["Climb to a stall and rewind back down.","Clean vertical stall with a smooth rewind.","Crisp stall and a tight rewind back down the same line."],"steps":["Climb vertically to a stall","Hang at the top for a beat","Blip and rewind back down"],"prereqs":["Comfortable with a vertical climb and stall","A feel for the blip that starts a rewind"],"practice":"Open air with height. Climb dead vertical, let it stall, and practise the little blip that sends it back down the same line. Keep the climb straight so the rewind tracks true.","mistakes":["Drifting off vertical, so the rewind wanders","Blipping too hard and overshooting","Not letting it stall before the rewind"],"variations":[{"name":"Stall Flip Rewind","note":"Add a flip at the stall before rewinding.","slug":"stall-flip-rewind"},{"name":"Stall 360 Rewind","note":"Add a yaw 360 at the stall.","slug":"stall-360-rewind"}],"related":[{"name":"Snapback","note":"A horizontal stop-and-reverse.","slug":"snapback"},{"name":"Side-Lock Rewind","note":"A rewind flown beside an object.","slug":"side-lock-rewind"}],"sources":["Pro Whooper"],"page":27,"pdfPage":29,"slug":"stall-rewind","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-rewind/"}]},{"name":"Wall Ride","difficulty":"Beginner","category":"Wall Tricks","howto":"Fly towards a wall. A few inches away, perform a 90° roll away from it and immediately cut throttle to glide smoothly alongside the wall.","mastery":["Track alongside the wall for a beat without clipping it.","Hold a steady gap and glide the length of the wall smoothly.","Long, close, controlled ride with a clean peel-away at the end."],"steps":["Approach the wall on a shallow line","Roll ~90 onto the wall, ease off throttle to glide","Roll back level and peel away at the end"],"prereqs":["Confident proximity flying near a surface","Smooth throttle control at low margins"],"practice":"Find a clean, tall wall with nothing to snag, a barn, a bando, a big retaining wall. Start with a wide gap off the face and creep closer as your control improves. Never ride a wall you have not inspected.","mistakes":["Rolling too late and climbing away from the wall","Carrying too much throttle, so you drift off the face","Fixating on the wall instead of looking down its length"],"variations":[{"name":"Reverse Wall Ride","note":"Ride the wall flying backward.","slug":"reverse-wall-ride"},{"name":"Wall Kiss","note":"A quick tap and peel instead of a full ride."}],"related":[{"name":"Gaps","note":"Line-and-commit proximity flying through, not along.","slug":"gaps"},{"name":"Building Dive","note":"Tracking a vertical surface downward.","slug":"building-dive"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":28,"pdfPage":30,"slug":"wall-ride","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/wall-ride/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=JJ9W8wpwsxA"}]},{"name":"Wall Tap","difficulty":"Beginner","category":"Wall Tricks","howto":"The basic wall touch. Approach a flat wall on a shallow line, ease up to tap the face lightly, and peel away smoothly. It is all about control and a soft touch, the foundation for the tap tricks that add rotations.","mastery":["Tap the wall and fly away under control.","Clean, light tap with a smooth peel-away.","Precise taps on a chosen spot, no bounce."],"steps":["Approach the wall on a shallow line","Tap the flat face","Peel away from the wall"],"prereqs":["Confident proximity flying near a surface","A soft, controlled touch"],"practice":"Find a clean, flat wall and start with the gentlest taps, building confidence before you add speed. Scout the face for anything that could snag.","mistakes":["Coming in too steep or too fast","Tapping too hard and bouncing off","Drifting into the wall after the tap"],"variations":[{"name":"Loop Tap","note":"Add a roll and pitch into the tap.","slug":"loop-tap"},{"name":"Ceiling Tap","note":"Tap an overhang instead of a wall.","slug":"ceiling-tap"}],"related":[{"name":"Loop Tap","note":"The tap with a rotation added.","slug":"loop-tap"},{"name":"Wall Ride","note":"Riding along the wall instead of tapping.","slug":"wall-ride"}],"sources":["Pro Whooper"],"page":29,"pdfPage":31,"slug":"wall-tap","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/wall-tap/"}]},{"name":"Whiplash","difficulty":"Beginner","category":"Orbitals","howto":"Fly at an object, then pitch back and yaw around it so you swing around the back with the nose locked on it, and pitch forward to level out. Fly towards the object, pitch back to keep the top of it in view while yawing around it, then pitch forward until you level out. The object never leaves the frame, and the whip comes from the yaw carrying you around the back of it.","mastery":["Swing around the object keeping it in view.","Smooth swing around the back, object held framed.","Tight, controlled swing, object locked in view the whole way."],"steps":["Fly towards the object","Pitch back and yaw around it, object in view","Pitch forward to level out, object in view"],"prereqs":["Coordinated yaw and pitch","Keeping a subject framed while maneuvering"],"practice":"Pick an object with clear room around it. Fly at it, then pitch back and yaw to swing around the back, keeping it centred in frame, and pitch forward to level out. Work both directions and keep it framed the whole way.","mistakes":["Losing the object out of frame through the swing","Not enough pitch-back to carry around the back","A jerky level-out that drops the frame"],"variations":[{"name":"Pole Dance","note":"Wrap the swing into a spiral around a pole.","slug":"pole-dance"},{"name":"Orbits","note":"A full circle around the subject.","slug":"orbits"}],"related":[{"name":"Orbits","note":"Circling a subject at a fixed radius.","slug":"orbits"},{"name":"Pole Dance","note":"Spiralling around a pole.","slug":"pole-dance"}],"sources":["Pro Whooper"],"page":30,"pdfPage":32,"slug":"whiplash","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/whiplash/"}]},{"name":"Yaw Spin","difficulty":"Beginner","category":"Open Air","howto":"A flat 360 spin. Carry a little momentum into your spot, then spin the quad a full turn on the yaw axis while holding altitude, like a top spinning in place. Keep the throttle steady through the rotation so the quad neither climbs nor drops, and roll out on the heading you came in on. It is the foundation for every spin trick that follows.","mastery":["Complete a full flat 360 and end roughly on your heading.","Pinned on the spot at one height, exit on the entry heading.","Crisp, centered spin at any speed, both directions, dead on heading."],"steps":["Carry momentum into the spot","Full flat 360 on yaw, throttle held steady","Roll out on the original heading"],"prereqs":["Comfortable holding a stable hover and heading","Smooth throttle control to hold altitude while yawing"],"practice":"Over open grass at a comfortable height. Practice both directions. Watch that the quad stays on the spot and at one height through the whole turn.","mistakes":["Letting throttle sag, so the quad drops through the spin","Drifting off the spot instead of pinning it","Coming out on a different heading than you entered"],"variations":[{"name":"Inverted Yaw Spin","note":"The same flat spin held while inverted.","slug":"inverted-yaw-spin"},{"name":"Trippy Spin","note":"An inverted yaw orbit around the top of a pole.","slug":"trippy-spin"}],"related":[{"name":"Orbits","note":"Circling a subject rather than spinning in place.","slug":"orbits"},{"name":"Inverted Yaw Spin","note":"The inverted, advanced counterpart.","slug":"inverted-yaw-spin"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":31,"pdfPage":33,"slug":"yaw-spin","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/yaw-spin/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=xB8kZMV1HGY"}]},{"name":"540 Split S","difficulty":"Novice","category":"Split-S","howto":"A 540 roll flowing into a Split-S. Roll one and a half turns on the entry so you finish inverted, then pull through the descending half loop of a Split-S, exiting the opposite direction and lower. The roll count is what makes it read clean.","mastery":["Land the 540 roll and split-S out.","Clean 1.5 rolls into a smooth Split-S.","Precise 540 straight into a tidy Split-S exit."],"steps":["540 roll on the entry","Pull the descending half loop","Exit the opposite direction, lower"],"prereqs":["A precise, countable 540 roll","A solid Split-S"],"practice":"Nail the 540 roll so you can stop it exactly inverted, then chain it into the Split-S descent. Precision on the roll is the whole trick.","mistakes":["Over or under rotating the 540","A gap between the roll and the split","Diving out instead of leveling"],"variations":[{"name":"Split S","note":"Without the leading 540.","slug":"split-s"},{"name":"540 Half Matty","note":"A 540 into a Half Matty instead.","slug":"540-half-matty"}],"related":[{"name":"Split S","note":"The reversal it finishes with.","slug":"split-s"},{"name":"Double Roll","note":"Shares the multi-rotation roll.","slug":"double-roll"}],"sources":["Pro Whooper"],"page":32,"pdfPage":34,"slug":"540-split-s","inputs":[{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":true},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/540-split-s/"}]},{"name":"Anti Matty","difficulty":"Novice","category":"Matty Flips","howto":"The Matty flipped the other way, a full backflip instead of a half front-flip. Fly over the object, then cut throttle and pull a full backflip, over-rotating 15 to 30 degrees to line yourself up, dropping down behind the object flying backward. Fly backward under the object, feeding in throttle and pitching forward to level out as you pass beneath it. Because the flip is a full rotation, you come out upright rather than inverted.","mastery":["Backflip over the object and fly back under it.","Clean full backflip, tidy backward pass underneath.","Crisp backflip, aligned exit, smooth level-out under the object."],"steps":["Fly over the object","Cut throttle, full backflip, over-flip to align","Fly backward under, throttle up and level out"],"prereqs":["A confident full backflip","Comfortable flying backward and keeping an object framed"],"practice":"Find an object with clear air above and below. Fly over it, cut throttle and commit to a full backflip, over-rotating a touch to line up, then fly backward under it and feed in throttle to level out. Give yourself height: the backflip drops you as you go.","mistakes":["Under-rotating the backflip, so you cannot line up","Not enough height, so you drop too low","Losing the object out of frame"],"variations":[{"name":"Anti Matty Rewind","note":"Rewind back under out of the exit."},{"name":"Power Anti Matty","note":"Carry it over a taller object with more throttle."}],"related":[{"name":"Matty Flip","note":"The front-flip version, over then under.","slug":"matty-flip"},{"name":"Loop","note":"The full rotation at its core.","slug":"loop"}],"sources":["Pro Whooper"],"page":33,"pdfPage":35,"slug":"anti-matty","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/anti-matty/"}]},{"name":"Backward Flying","difficulty":"Novice","category":"Open Air","howto":"The essential skill of flying in reverse. Pitch back to get the quad moving tail-first, then hold a steady backward line, keeping it tracking true. Backward flight underpins every reversal and rewind, so it is worth drilling until it feels natural.","mastery":["Fly a straight line backward under control.","Smooth, steady backward flight, no wander.","Confident backward flight on any line, both directions."],"steps":["Get the quad moving backward","Hold a steady backward line","Keep it tracking true"],"prereqs":["Stable forward flight","Comfortable reading a backward line"],"practice":"Open ground. Get the quad moving backward and hold a straight line, resisting the urge to over-correct. Practise until backward feels as natural as forward.","mistakes":["Over-correcting and weaving","Drifting off the line","Losing orientation flying tail-first"],"variations":[{"name":"Backwards Dive","note":"A dive flown backward.","slug":"backwards-dive"},{"name":"Beginner Switch","note":"Snap around to backward.","slug":"beginner-switch"}],"related":[{"name":"Beginner Switch","note":"Snapping around to backward.","slug":"beginner-switch"},{"name":"Cradle","note":"A backward tracking pass.","slug":"cradle"}],"sources":["Mazta FPV tutorial"],"page":34,"pdfPage":36,"slug":"backward-flying","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=esueDHARopM"}]},{"name":"Beginner Matty","difficulty":"Novice","category":"Matty Flips","howto":"The Matty in its gentlest form, over a low, forgiving object. Fly over it with the camera tracking, throw a small flip at the far edge, and drop back under. Low and slow, it is the place to learn the Matty motion before you take it to bigger obstacles.","mastery":["Clear the low object and pass back under it.","Smooth, small Matty with a clean under-pass.","Tidy, controlled Matty over a low obstacle, both ways."],"steps":["Fly over the low object","Small flip at the far edge","Drop back under it"],"prereqs":["A clean flip","Comfortable flying under and over an object"],"practice":"Pick a low bar or rail with clear air below. Keep it small and slow, focusing on the timing of the flip and keeping the object framed, then build up to taller obstacles.","mistakes":["Flipping too early","Losing the object out of frame","Dropping onto the object underneath"],"variations":[{"name":"Matty Flip","note":"The full-height version.","slug":"matty-flip"},{"name":"Power Matty","note":"Over a much taller obstacle.","slug":"power-matty"}],"related":[{"name":"Matty Flip","note":"The standard version.","slug":"matty-flip"},{"name":"Flip","note":"The rotation at its core.","slug":"flip"}],"sources":["Pro Whooper"],"page":35,"pdfPage":37,"slug":"beginner-matty","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/beginner-matty/"}]},{"name":"Beginner Switch","difficulty":"Novice","category":"Powerloops","howto":"The building block of every switch trick: a quick 180 yaw that turns you around. Fly forward on your line, snap a half yaw so the nose whips around, and continue flying backward. Master the clean switch here before you fold it into loops and taps.","mastery":["Switch 180 and fly out backward.","Clean, quick switch with a steady backward exit.","Snappy 180 switch, smooth into controlled backward flight."],"steps":["Fly forward on your line","Snap a 180 yaw to switch","Fly out backward"],"prereqs":["A stable forward line","Comfortable flying backward"],"practice":"Open air. Fly a straight line, snap the 180 yaw, and hold a clean backward line out. Both directions. Keep the switch quick and the exit steady.","mistakes":["A slow switch that drifts","Over-rotating past 180","Wobbling into the backward flight"],"variations":[{"name":"Power Switch","note":"Fold the switch into a powerloop.","slug":"power-switch"},{"name":"Whiplash","note":"A fast yaw whip around an object.","slug":"whiplash"}],"related":[{"name":"Whiplash","note":"A fast yaw whip.","slug":"whiplash"},{"name":"Yaw Spin","note":"A full flat 360.","slug":"yaw-spin"}],"sources":["Pro Whooper"],"page":36,"pdfPage":38,"slug":"beginner-switch","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/beginner-switch/"}]},{"name":"Boomerang","difficulty":"Novice","category":"Open Air","howto":"An out-and-back curve wrapped around an object like a pole, the flight path of a thrown boomerang. Approach the obstacle, then pitch back and roll slightly right while yawing a touch left to carry the turn around it, and feed in throttle and pitch forward to exit. The object sits at the heart of the turn: you sweep around it and back out the way you came.","mastery":["Curve out around the object and back.","Smooth, rounded turn around the object.","Tight, controlled boomerang around the object, both directions."],"steps":["Approach the obstacle","Pitch back, roll right, yaw left around it","Throttle and pitch forward to exit"],"prereqs":["Coordinated pitch, roll, and yaw","A feel for a rounded turn"],"practice":"Pick a pole or post with room around it. Approach it, then pitch back and coordinate a little roll and yaw to carry the turn around it and back out. Keep it smooth and rounded, both directions.","mistakes":["A flat, skidding turn instead of a rounded one","Clipping the object on the turn","Not coordinating the roll and yaw"],"variations":[{"name":"Orbits","note":"A full circle around the object.","slug":"orbits"},{"name":"Pendulum","note":"An out-and-back swing.","slug":"pendulum"}],"related":[{"name":"Orbits","note":"A full circle around a subject.","slug":"orbits"},{"name":"Whiplash","note":"A tighter swing around an object.","slug":"whiplash"}],"sources":["Mazta FPV tutorial"],"page":37,"pdfPage":39,"slug":"boomerang","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=cEqJj62f8iY"}]},{"name":"Burrito Roll","difficulty":"Novice","category":"Jump Ropes","howto":"A full roll flown under an object while facing sideways the whole time. Yaw 90 degrees to face sideways and enter beneath the object, throttle up and roll a full 360 staying sideways, then roll back under the object to the point you entered, the way you came in. It wraps a full roll into an under-and-back pass, keeping the quad sideways throughout.","mastery":["Roll under the object and back to the entry.","Smooth 360 roll, clean back-under to where you started.","Tight, sideways burrito roll, dead on the entry line, both directions."],"steps":["90° flat yaw spin, enter under the object sideways","Facing sideways, throttle up and roll a full 360","Facing sideways, roll left back under, the way you came"],"prereqs":["A clean 360 roll","Comfortable flying sideways (yawed 90°) under an object"],"practice":"Find a horizontal object like the jump-rope bar. Yaw sideways, drop under it, throttle up and roll a full 360 staying sideways, then roll back under to where you entered. Keep it low and on the same line.","mistakes":["Losing the sideways heading through the roll","Drifting off the entry line","Clipping the object on the way under"],"variations":[{"name":"Jump Rope","note":"The loop-around-the-object version.","slug":"jump-rope"},{"name":"Double Burrito","note":"Two burrito rolls linked."}],"related":[{"name":"Jump Rope","note":"The loop-around cousin, also flown sideways.","slug":"jump-rope"},{"name":"Barrel Roll","note":"The 360 roll on its own.","slug":"barrel-roll"}],"sources":["Pro Whooper"],"page":38,"pdfPage":40,"slug":"burrito-roll","inputs":[{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/burrito-roll/"}]},{"name":"Eject Roll","difficulty":"Novice","category":"Miscellaneous","howto":"A vertical gap pass with a roll pinned at the top. Throttle-punch up through a horizontal gap and pitch forward so you are facing straight down, pin a stationary 360 roll while looking down at the opening, then stop the roll and drop back down through the gap and out. It is a gap flown up-and-down instead of side-to-side, with a roll on top.","mastery":["Punch up through the gap, roll, and drop back through.","Clean up-and-through, tidy 360 roll, smooth drop back down.","Crisp eject roll, pinned 360, dead through the gap both ways."],"steps":["Punch up through the gap, pitch to face down","Facing the gap from above, pin a 360 roll","Stop the roll, drop back down through and out"],"prereqs":["A clean 360 roll","Confident vertical punch-outs and gap flying"],"practice":"Find a horizontal gap, a doorway laid flat or the space between two beams. Punch up through it, pitch to face down, pin a full roll, then drop back through and out. Give yourself height above the gap for the roll.","mistakes":["Not enough punch to clear the gap for the roll","Drifting off the gap during the roll","Clipping the edge on the way back down"],"variations":[{"name":"Juicy Eject","note":"A floatier eject.","slug":"juicy-eject"},{"name":"Stellar Eject Roll","note":"An eject roll taken further.","slug":"stellar-eject-roll"}],"related":[{"name":"Gaps","note":"The gap pass, flown side-to-side instead.","slug":"gaps"},{"name":"Barrel Roll","note":"The 360 roll on its own.","slug":"barrel-roll"}],"sources":["Pro Whooper"],"page":39,"pdfPage":41,"slug":"eject-roll","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/eject-roll/"}]},{"name":"Front Swing","difficulty":"Novice","category":"Orbitals","howto":"Approach an object from the side, slip just past it, pitch up into a stall, and come backwards out the way you came. Approach the side of the object, and as you pass it slightly, pitch up to stall the quad, then blip the throttle and pitch back to slide backwards out along your approach line. It is a controlled stall-and-reverse played out beside an object.","mastery":["Approach, stall past the object, and reverse out.","Clean approach into a tidy stall and a smooth reverse.","Crisp stall just past the object, dead-straight reverse out."],"steps":["Approach the side of the object","Just past it, pitch up to a stall","Blip and pitch back, backwards out the way you came"],"prereqs":["A confident stall","Comfortable flying backward on a line"],"practice":"Pick an object with room around it. Approach from the side, slip just past it, pitch up to a clean stall, then blip and slide backwards out the way you came. Keep the reverse straight on your approach line.","mistakes":["Stalling too early, before passing the object","Drifting off the approach line on the reverse","A harsh blip that overshoots"],"variations":[{"name":"Pendulum","note":"A swinging out-and-back.","slug":"pendulum"},{"name":"Boomerang","note":"An out-and-back around an object.","slug":"boomerang"}],"related":[{"name":"Stall Rewind","note":"A stall reversed, flown vertically.","slug":"stall-rewind"},{"name":"Boomerang","note":"An out-and-back around an object.","slug":"boomerang"}],"sources":["Mazta FPV tutorial"],"page":40,"pdfPage":42,"slug":"front-swing","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=7k_hbcJxwIg"}]},{"name":"Immelmann","difficulty":"Novice","category":"Powerloops","howto":"Begin a Powerloop, but at the peak of the loop execute a rapid 180° roll to level out and complete the trick.","mastery":["Complete the half loop and roll out upright the opposite direction.","Smooth loop and a clean level roll-out with altitude gained.","Round loop, crisp 180 roll right at the peak, dead-level exit."],"steps":["Pull up into a half loop with throttle","Half roll upright at the top of the loop","Exit level the opposite way, higher"],"prereqs":["Comfortable looping on the pitch axis (powerloop)","A reliable half roll to level"],"practice":"Give yourself altitude and open space. Practice it as the mirror of a Split-S: where the Split-S drops and reverses, the Immelmann climbs and reverses. Enter with enough speed to carry the loop.","mistakes":["Rolling before you reach the top, so the exit corkscrews","Running out of speed halfway up the loop","Exiting off-heading instead of a clean reciprocal"],"variations":[{"name":"Immelloop","note":"A powerloop with a 180 roll at the apex.","slug":"immelloop"},{"name":"Immelmatt","note":"Blend an Immelmann into a Matty line.","slug":"immelmatt"}],"related":[{"name":"Split S","note":"The descending mirror image.","slug":"split-s"},{"name":"Powerloop","note":"Shares the loop; the Immelmann is a half loop plus a roll.","slug":"powerloop"},{"name":"Matty Flip","note":"Another over-the-top reversal, done over a gap.","slug":"matty-flip"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":41,"pdfPage":43,"slug":"immelmann","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/immelmann/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=NIRiyWI668E"}]},{"name":"Inverted Rewind","difficulty":"Novice","category":"Open Air","howto":"A stall rewind flown through inverted. Blip the throttle to float up to a stall point, then roll a full 180 to the right so you pass through inverted at the top, and immediately roll 180 back to the left to flatten out, rewinding the roll. Blip the throttle again to catch the drop, coming back down at the same rate you climbed.","mastery":["Blip up, double-roll through inverted, and catch the drop.","Smooth stall with a clean roll and rewind at the top.","Crisp stall, tight through inverted, floated back down on the line."],"steps":["Blip throttle to a stall out point","180 roll to the right","180 roll to the left to flatten out","Blip throttle to catch the drop"],"prereqs":["A confident stall out","A crisp, controllable roll"],"practice":"Get the stall timing dialed first, then add the double roll at the top. Everything feels reversed as you pass through inverted, so start high and take it slow. Keep the line straight so the rewind tracks true.","mistakes":["Stalling the roll halfway and dropping inverted","Drifting off the line through the peak","A harsh blip that throws the drop"],"variations":[{"name":"Stall Rewind","note":"The same, flown upright.","slug":"stall-rewind"},{"name":"Inverted Yaw Spin","note":"Another inverted hold-and-move.","slug":"inverted-yaw-spin"}],"related":[{"name":"Stall Rewind","note":"The upright version.","slug":"stall-rewind"},{"name":"Inverted Yaw Spin","note":"Another inverted maneuver.","slug":"inverted-yaw-spin"}],"sources":["Pro Whooper"],"page":42,"pdfPage":44,"slug":"inverted-rewind","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/inverted-rewind/"}]},{"name":"Juicy Eject","difficulty":"Novice","category":"Miscellaneous","howto":"A floaty, stylish way to bail off a line. Blip the throttle to unload the quad, then let it drift into a soft, slow roll away and down, floating out clear of the line rather than diving off it. It is the eject roll made juicy, all about float and finesse.","mastery":["Unload and float a roll away off the line.","Smooth, floaty roll into a soft descent.","Effortless, juicy eject that drifts out clean."],"steps":["Slightly roll left","Blip throttle for eject and soft roll away","Float out clear of the line"],"prereqs":["A clean roll","A feel for unloading with throttle"],"practice":"Practise the blip-and-drift, keeping the roll slow and floaty rather than snappy. It doubles as a graceful bail-out. Film it back to check it reads smooth.","mistakes":["Rolling too fast, losing the float","Diving instead of drifting","Not unloading enough"],"variations":[{"name":"Eject Roll","note":"A snappier eject.","slug":"eject-roll"},{"name":"Juicy Flick","note":"A juicy pop to inverted.","slug":"juicy-flick"}],"related":[{"name":"Eject Roll","note":"A snappier bail.","slug":"eject-roll"},{"name":"Juicy Flick","note":"Another juicy, floaty move.","slug":"juicy-flick"}],"sources":["Mazta FPV tutorial"],"page":43,"pdfPage":45,"slug":"juicy-eject","inputs":[{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=qvVVhV-37-A"}]},{"name":"Juicy Flick","difficulty":"Novice","category":"Open Air","howto":"From a cruising line, blip the throttle to unload the quad and snap a 180 pitch to flick it up to inverted, hang there floaty for a beat, then roll out slowly and smoothly to recover forward on the same line. It is small and floaty by design, more style than power, which is exactly what makes it read as juicy.","mastery":["Pop to inverted and roll out upright on the same line.","Floaty, unhurried flick with a smooth slow roll-out.","Effortless, stylish flick that stays perfectly on line, both ways."],"steps":["Blip the throttle and snap a 180 pitch to inverted","Hang inverted, floaty, for a beat","Slow roll out and recover forward"],"prereqs":["A clean flip and confident inverted recovery","A feel for unloading the quad with throttle"],"practice":"Plenty of height at first. The trick is in the timing of the blip and the patience of the roll-out, so keep it slow and floaty rather than forcing it. Film it back to check it reads as smooth.","mistakes":["Rolling out too fast, killing the floaty look","Not unloading enough, so the flick is stiff","Losing the line, so you recover off-track"],"variations":[{"name":"Juicy Double Roll","note":"Finished with a quick double (540) roll.","slug":"juicy-double-roll"},{"name":"Double Juicy","note":"Two flicks linked before recovering."},{"name":"Juicy Flick Rewind","note":"Flick, then reverse back along the line.","slug":"juicy-flick-rewind"}],"related":[{"name":"Juicy Double Roll","note":"The same flick, double-rolled out.","slug":"juicy-double-roll"},{"name":"Flip","note":"The full rotation the flick is a stylised piece of.","slug":"flip"},{"name":"Roll","note":"The slow roll-out that finishes it.","slug":"roll"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":44,"pdfPage":46,"slug":"juicy-flick","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"originator":"Johnny Scars","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/juicy-flick/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=XTbEZPqFzBU"}]},{"name":"Loop Tap","difficulty":"Novice","category":"Wall Tricks","howto":"Fly towards an object at 45° or less. Apply a bit of throttle and simultaneously perform a 90° roll and a 45° pitch back to execute a wall tap while facing backward. Immediately follow with a 180° pitch back and roll away from the wall to finish.","mastery":["Tap the wall and peel away under control.","Clean tap facing backward with a smooth roll-away.","Precise tap and an immediate, tidy reverse off the wall."],"steps":["Approach the wall on a shallow line","Roll and pitch back to tap the face, facing backward","Pitch back and roll away from the wall"],"prereqs":["Confident proximity flying near a surface","Comfortable tapping a wall and reversing"],"practice":"Find a clean, tall wall and start with gentle taps, building up the roll-and-pitch as your confidence grows. Scout the face first, you want a flat, snag-free surface to tap.","mistakes":["Coming in too steep instead of a shallow line","Tapping too hard and knocking yourself off line","Slow to reverse away, so you drift into the wall"],"variations":[{"name":"Loop Tap Rewind","note":"Rewind straight back off the tap."},{"name":"Double Tap","note":"Two taps linked along the same wall."}],"related":[{"name":"Wall Ride","note":"Riding along the wall rather than tapping it.","slug":"wall-ride"},{"name":"Building Dive","note":"Another committed wall maneuver.","slug":"building-dive"},{"name":"Snapback","note":"Shares the tap-and-reverse feel.","slug":"snapback"}],"sources":["Pro Whooper"],"page":45,"pdfPage":47,"slug":"loop-tap","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[-0.7,-0.7]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/loop-tap/"}]},{"name":"Matty Flip","difficulty":"Novice","category":"Matty Flips","howto":"Fly over an object and execute a partial front flip over it while keeping the object in view as you descend. Gradually increase throttle and adjust pitch to level out and fly backwards beneath the object.","mastery":["Pass over the object, flip, and return under it in any form.","Keep the object framed through the flip with a smooth, controlled return. Good form.","Object stays centered the entire time with a seamless over then under line. Perfect form."],"steps":["Fly over the object, camera tracking it (light forward pitch)","Partial front flip over the far edge (forward pitch)","Gradually increase throttle to arrest and level inverted","Adjust pitch to fly backward beneath the object"],"prereqs":["Solid Forward Flip with clean level exits","Comfortable flying backward and tracking a subject","Basic Gap/proximity confidence"],"practice":"Needs a gap or elevated obstacle you can pass over and then back under, a railing, low wall, fallen log, or playground structure. Pick a subject to track (a tree, a friend, a car) so you can practice keeping it framed through the flip.","mistakes":["Losing the subject during the flip, rushing the rotation","Drifting off the line so the return doesn't clear the gap","Flipping too early before fully clearing the far edge","Not enough separation, so the exit clips the obstacle"],"variations":[{"name":"Half Matty","note":"Stop at inverted, a reverse Split-S that reverses direction with altitude.","slug":"half-matty"},{"name":"540 Half Matty","note":"Add a full flip for 540° of total pitch rotation.","slug":"540-half-matty"},{"name":"Matty Twister","note":"Add a yaw twist during the flip.","slug":"matty-twister"},{"name":"Power Matty","note":"Fly it with powerloop throttle to carry it over a taller obstacle.","slug":"power-matty"}],"related":[{"name":"Anti Matty","note":"Forward-flip variant toward the direction of travel.","slug":"anti-matty"},{"name":"Matty 360","note":"Matty with an added 360° element.","slug":"matty-360"},{"name":"Snapback","note":"Half-flip reversal without the gap pass-under.","slug":"snapback"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":46,"pdfPage":48,"slug":"matty-flip","inputs":[{"L":[[0,0.3]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":true},{"L":[[0,0.4]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,0.3]],"R":[[0,-1]],"Lh":false,"Rh":true}],"originator":"Matty Stuttard","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/matty-flip/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=mZVjPSQHm9Y"}]},{"name":"Mavvelmann","difficulty":"Novice","category":"Maverick Loops","howto":"Pass forward under the object, then pitch up into a half loop to almost inverted. Once above the object, rock back and pitch the drone down, then level out with a 180 roll over the object, coming back the way you started. It stacks a half loop and a rolling reversal, adding both roll and pitch on the pass back over the top.","mastery":["Loop up over the object and roll out backward.","Clean half-loop up into a tidy roll back over.","Seamless Mavvelmann, roll and pitch out over the object, dead on line."],"steps":["Pass under, pitch up to almost inverted","Once above it, rock back and pitch down","180 roll to level, back over toward start"],"prereqs":["A confident half loop","A clean 180 roll to level"],"practice":"Pass under the object and pitch up hard to almost inverted, then as you come above it, rock back and roll 180 to level out heading back the way you came. Give yourself vertical room.","mistakes":["Not enough pitch to reach inverted above the object","Rolling before you are above the object","Losing the line on the reversal"],"variations":[{"name":"Immelmann","note":"A half-loop and roll in the open.","slug":"immelmann"},{"name":"Maverick Loop","note":"A loop under the object.","slug":"maverick-loop"}],"related":[{"name":"Immelmann","note":"The half-loop-and-roll it echoes.","slug":"immelmann"},{"name":"Maverick Loop","note":"A loop under the object.","slug":"maverick-loop"}],"sources":["Pro Whooper"],"page":47,"pdfPage":49,"slug":"mavvelmann","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/mavvelmann/"}]},{"name":"Mavvy Roll","difficulty":"Novice","category":"Maverick Loops","howto":"A powerloop with a full 360 roll pinned at the top of the loop. Pass under the object and punch vertical into the loop, and at the peak roll a full 360, then level the roll and carry the loop back down and under the object. It caps the powerloop with a roll right at the top.","mastery":["Powerloop with a 360 roll at the top.","Clean powerloop, tidy roll pinned at the peak.","Seamless powerloop and roll, dead on line both ways."],"steps":["Pass under the object, punch vertical","At the peak, pin a 360 roll","Level the roll, complete the loop back under"],"prereqs":["A confident powerloop","A controllable 360 roll"],"practice":"Get the powerloop solid, then add the roll at the very top of the loop where you hang inverted. Give yourself height and commit to the loop before the roll.","mistakes":["Rolling before you reach the peak","Not enough speed to carry the loop","Losing the loop line on the roll"],"variations":[{"name":"Powerloop","note":"Without the roll at the top.","slug":"powerloop"},{"name":"Inverted 360 Powerloop","note":"A yaw 360 at the top instead of a roll.","slug":"inverted-360-powerloop"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Barrel Roll","note":"The 360 roll on its own.","slug":"barrel-roll"}],"sources":["Pro Whooper"],"page":48,"pdfPage":50,"slug":"mavvy-roll","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/mavvy-roll/"}]},{"name":"Pendulum","difficulty":"Novice","category":"Orbitals","howto":"A swinging arc like a pendulum on a string. Swing down from one side, carry your speed through the bottom, and let it swing up the other side, matching the height on each swing. It is a rhythm move that trades altitude for speed and back again.","mastery":["Swing down through and up the other side.","Smooth, even swing like a pendulum.","Rhythmic swings, matched on both sides."],"steps":["Swing down from one side","Carry speed through the bottom","Swing up the other side"],"prereqs":["Smooth pitch and throttle","A feel for trading height for speed"],"practice":"Find an open arc and swing down and up, keeping both sides even. Let momentum do the work through the bottom. Build the rhythm so it flows like a real pendulum.","mistakes":["Uneven swings, higher on one side","Throttling through instead of coasting","Losing the rhythm"],"variations":[{"name":"Jump Rope","note":"An up-and-over swing over an object.","slug":"jump-rope"},{"name":"Boomerang","note":"An out-and-back curve.","slug":"boomerang"}],"related":[{"name":"Jump Rope","note":"An over-an-object swing.","slug":"jump-rope"},{"name":"Orbits","note":"Another arcing maneuver.","slug":"orbits"}],"sources":["Mazta FPV tutorial"],"page":49,"pdfPage":51,"slug":"pendulum","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=l7F1a68G9r8"}]},{"name":"Perch","difficulty":"Novice","category":"Miscellaneous","howto":"Landing on top of an object instead of the ground. Approach over a ledge, wall, or box, flare to bleed off your speed, and settle gently onto the top surface, holding it there. It is a precision landing that turns a piece of the scenery into a perch.","mastery":["Set down on top of the object and hold.","Smooth approach and a controlled settle.","Precise, gentle perch on a chosen spot, no bounce."],"steps":["Approach over the ledge","Flare to bleed off speed","Settle onto the top"],"prereqs":["Precise low-speed control","A gentle touch on the throttle"],"practice":"Start with a wide, flat top, a low wall or a table, and practise settling on it softly. Approach slow, flare, and set down light. Tighten your target as your control improves.","mistakes":["Coming in too fast and overshooting the top","Not flaring, so you clip the edge","Setting down hard and bouncing off"],"variations":[{"name":"Slide to Perch","note":"Slide across the top before stopping."},{"name":"Wall Ride","note":"Track a vertical face instead of the top.","slug":"wall-ride"}],"related":[{"name":"Slide Disarm","note":"A ground-level settle-and-stop.","slug":"slide-disarm"},{"name":"Wall Tap","note":"Touching a surface rather than resting on it.","slug":"wall-tap"}],"sources":["Pro Whooper","Rotor Riot"],"page":50,"pdfPage":52,"slug":"perch","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/perch/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Powerloop","difficulty":"Novice","category":"Powerloops","howto":"Fly under and past the obstacle with speed, then apply throttle and gradually pitch back to arc up into the loop until you're fully inverted directly over or slightly behind it. Carry throttle across the top, then relax pitch as gravity brings the nose down, increasing throttle again as you approach the ground so you exit level on your entry line.","mastery":["Fly under the obstacle, around the top, and back through in any form.","Keep a smooth flight path with no jerking through the whole trick. Good form.","Smooth, with consistent distance maintained through the whole path. Perfect form."],"steps":["Approach under object, pitching drone up","At the peak of the loop, float through","Catch at the bottom of the loop"],"prereqs":["Comfortable with basic Flip and inverted recovery","Consistent throttle control through a full rotation"],"practice":"Needs a horizontal obstacle to loop over, a tree branch, gap, banner bar, or doorway. Start with a high, forgiving obstacle and plenty of vertical space; drop the height as it gets consistent.","mistakes":["Too little throttle over the top, the quad drops out inverted","Flipping in place instead of translating up and over the obstacle","Chopping throttle early, killing the exit and dropping the nose"],"variations":[{"name":"Sideways Powerloop","note":"Flown on the roll axis, loop the obstacle knife-edge style.","slug":"sideways-powerloop"},{"name":"Power Split","note":"Finish the top with a Split-S roll-out instead of continuing the loop.","slug":"power-split"},{"name":"Immelloop","note":"A 180 roll at the loop's apex, out backwards.","slug":"immelloop"}],"related":[{"name":"Immelmann","note":"Half-loop-and-roll that reverses direction with altitude.","slug":"immelmann"},{"name":"Maverick Loop","note":"The inside-out inverse, dive in and loop underneath.","slug":"maverick-loop"},{"name":"Split S","note":"The downward half-loop counterpart.","slug":"split-s"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":51,"pdfPage":53,"slug":"powerloop","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/powerloop/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Ip7JBqRNDzg"}]},{"name":"Roll Tap","difficulty":"Novice","category":"Wall Tricks","howto":"A wall tap with a roll baked in. Approach a flat wall on a shallow line, roll the quad as you reach out to tap the face, then peel away. The roll turns a plain tap into a stylish one, a step up from the basic wall tap.","mastery":["Roll into a wall tap and peel away.","Clean roll into a light tap and smooth exit.","Crisp roll-tap on a chosen spot, no bounce."],"steps":["Approach the wall on a shallow line","Roll into the tap","Peel away from the wall"],"prereqs":["A confident wall tap","A controllable roll near a surface"],"practice":"Get the basic wall tap solid first, then add the roll as you touch. Start gentle and build up. Scout the wall for anything that could snag.","mistakes":["Rolling too early, missing the tap","Tapping too hard and bouncing","Losing your line on the roll"],"variations":[{"name":"Wall Tap","note":"Without the roll.","slug":"wall-tap"},{"name":"Loop Tap","note":"A roll and pitch into the tap.","slug":"loop-tap"}],"related":[{"name":"Wall Tap","note":"The plain tap.","slug":"wall-tap"},{"name":"Loop Tap","note":"A tap with roll and pitch.","slug":"loop-tap"}],"sources":["Pro Whooper"],"page":52,"pdfPage":54,"slug":"roll-tap","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/roll-tap/"}]},{"name":"Side Loop","difficulty":"Novice","category":"Jump Ropes","howto":"The same as a jump rope, a loop around a horizontal object entered facing sideways, but instead of staying level you go inverted over the top. Yaw 90 degrees to face sideways and enter beneath the object, throttle up to carry the loop around it, and pass over the top inverted before dropping back down and out. Unlike the jump rope, there is no roll to keep it level, so you invert at the peak.","mastery":["Loop around the object, inverted over the top.","Smooth sideways loop, clean inversion at the peak.","Tight side loop, dead sideways, crisp inverted top."],"steps":["90° flat yaw spin, enter under the object sideways","Throttle up to loop around","Pass over the top inverted, cut throttle"],"prereqs":["A confident jump rope or powerloop","Comfortable flying sideways (yawed 90°)"],"practice":"Find a horizontal object like the jump-rope bar. Yaw sideways, drop under it, and throttle up to carry the loop around, going inverted over the top rather than rolling to stay level. Build the loop up slowly.","mistakes":["Rolling to stay level like a jump rope","Drifting off the sideways heading","Not enough throttle to clear the top inverted"],"variations":[{"name":"Jump Rope","note":"The level version, rolling to stay upright.","slug":"jump-rope"},{"name":"Burrito Roll","note":"A sideways roll under the object.","slug":"burrito-roll"}],"related":[{"name":"Jump Rope","note":"The level, non-inverted version.","slug":"jump-rope"},{"name":"Powerloop","note":"A loop around an object, forward-facing.","slug":"powerloop"}],"sources":["Pro Whooper"],"page":53,"pdfPage":55,"slug":"side-loop","inputs":[{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/side-loop/"}]},{"name":"Slide Disarm","difficulty":"Novice","category":"Miscellaneous","howto":"A stylish way to end a line. Bring the quad down onto a shallow landing line, let it touch and slide along the ground carrying its momentum, and cut the motors mid-slide so it coasts to a stop. It reads as a deliberate finish rather than a landing, the slide disarm every freestyle line wants to end on.","mastery":["Set it down and slide to a stop without tumbling.","Smooth approach and a controlled slide.","Low, fast slide onto a chosen spot, clean disarm."],"steps":["Descend onto your landing line","Let it touch and slide along the ground","Cut the motors mid-slide to a stop"],"prereqs":["Smooth throttle control near the ground","A feel for your quad's momentum"],"practice":"A flat, smooth surface with room to slide. Come in shallow and low, let it touch, and practise timing the disarm so it coasts to rest. Bind your disarm to a switch you can hit cleanly.","mistakes":["Coming in too steep and tumbling","Disarming too early, dropping it short","Sliding into something you did not scout"],"variations":[{"name":"Slide to Perch","note":"Slide up onto a low ledge and stop."},{"name":"Power Slide","note":"Carry more speed into a longer slide."}],"related":[{"name":"Perch","note":"Setting down on top of an object.","slug":"perch"},{"name":"Gaps","note":"Another committed, line-based move.","slug":"gaps"}],"sources":["Pro Whooper"],"page":54,"pdfPage":56,"slug":"slide-disarm","inputs":[{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/slide-disarm/"}]},{"name":"Slingshot","difficulty":"Novice","category":"Open Air","howto":"Load up and fire forward, like drawing and releasing a slingshot. Pull back and up to load, coiling your energy, then release it all into a fast forward line and ride the acceleration out. The bigger the load, the harder the launch.","mastery":["Load and release into a fast forward line.","Smooth load into a snappy release.","Explosive slingshot, all the load turned to speed."],"steps":["Load by pulling back and up","Release into a fast forward line","Ride the acceleration out"],"prereqs":["Confident pitch and throttle","A feel for coiling and releasing energy"],"practice":"Practise the load, a smooth pull back and up, then release cleanly into a forward punch. Build the load gradually. It is about turning stored energy into a clean launch.","mistakes":["A messy load that wastes energy","Releasing off-line","Not committing to the launch"],"variations":[{"name":"Face Punch","note":"A pure vertical punch-out.","slug":"face-punch"},{"name":"Power Flip","note":"A flip with a power exit.","slug":"power-flip"}],"related":[{"name":"Face Punch","note":"A vertical punch-out.","slug":"face-punch"},{"name":"Power Flip","note":"A flip with a power climb.","slug":"power-flip"}],"sources":["Mazta FPV tutorial"],"page":55,"pdfPage":57,"slug":"slingshot","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Z5cfPV4aPvM"}]},{"name":"Snapback","difficulty":"Novice","category":"Open Air","howto":"A quick turn-around that reverses your direction. Carry speed into a straight line, snap a 180 pitch, a half flip up and over, so you pitch back on yourself and end up inverted flying the other way, then immediately roll 180 to come upright, now tracking back the way you came. The pitch reverses you and the roll sets you level.","mastery":["Reverse with a half flip and roll upright, flying back.","Crisp pitch-and-roll turn-around with a clean exit.","Sharp 180 pitch into a snappy 180 roll, dead on the line back."],"steps":["Commit to a straight line with speed","Snap a 180 pitch, a half flip over the top","Roll 180 to come upright, flying back"],"prereqs":["A confident half flip and a clean half roll","Comfort chaining a pitch straight into a roll"],"practice":"Open airspace with height to spare. Commit to the line, then snap the 180 pitch and roll upright in one motion. Practise the pitch and the roll separately first, then blend them so there is no pause between.","mistakes":["Rolling before the pitch flip has fully reversed you","A half-hearted pitch, so you do not turn all the way around","A sloppy roll that leaves you off-level or off the line"],"variations":[{"name":"Snapback Rewind","note":"Continue the reverse into a full rewind."},{"name":"Power Snap","note":"Add throttle to snap over a taller line."}],"related":[{"name":"Matty Flip","note":"A half-flip reversal, done over a gap.","slug":"matty-flip"},{"name":"Flip","note":"The rotation a snapback stops halfway.","slug":"flip"},{"name":"Split S","note":"Another quick reversal, with a roll entry.","slug":"split-s"}],"sources":["Pro Whooper"],"page":56,"pdfPage":58,"slug":"snapback","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/snapback/"}]},{"name":"Stall 360 Rewind","difficulty":"Novice","category":"Rewinds","howto":"A stall rewind with a flat spin at the top, flown facing up. Climb straight up and pitch to a stall facing up, then roll a full 360 while you hang there nose-up, and blip the throttle to rewind back down the line you climbed. Because you are facing straight up, the 360 is a roll rather than a yaw, and it reads as a flat spin from the ground.","mastery":["Stall facing up, roll a 360, and rewind down.","Clean nose-up stall into a flat 360 roll and rewind.","Crisp vertical stall, pinned 360 roll, tight rewind."],"steps":["Climb vertically to a stall facing up","Spin a flat 360 roll at the top","Blip and rewind back down"],"prereqs":["A solid stall rewind","A flat 360 roll while facing up"],"practice":"Get the vertical stall and rewind dialed, then add the 360 roll at the top while you hang facing up. Keep it pinned on the spot and the climb straight so the rewind tracks true.","mistakes":["Drifting off the spot during the roll","Not fully stalling before the 360","A harsh blip that throws the rewind"],"variations":[{"name":"Stall Rewind","note":"Without the 360.","slug":"stall-rewind"},{"name":"Stall Flip Rewind","note":"A flip at the stall instead.","slug":"stall-flip-rewind"}],"related":[{"name":"Stall Rewind","note":"The base stall-and-rewind.","slug":"stall-rewind"},{"name":"Barrel Roll","note":"The 360 roll at the top.","slug":"barrel-roll"}],"sources":["Pro Whooper"],"page":57,"pdfPage":59,"slug":"stall-360-rewind","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-360-rewind/"}]},{"name":"Stall Flip Rewind","difficulty":"Novice","category":"Rewinds","howto":"A stall rewind with a flip at the top. Climb straight up to a stall, throw a quick flip as you hang at the peak, then blip the throttle to rewind back down the line you climbed. The flip adds a flourish to the reversal.","mastery":["Stall, flip, and rewind back down.","Clean stall into a tidy flip and rewind.","Crisp vertical stall, sharp flip, tight rewind."],"steps":["Climb vertically to a stall","Throw a flip at the top","Blip and rewind back down"],"prereqs":["A solid stall rewind","A quick flip at low speed"],"practice":"Get the vertical stall and rewind dialed, then add the flip at the top once you are comfortable hanging there. Keep the climb straight so the rewind tracks.","mistakes":["Flipping before you reach the stall","Drifting off vertical","A harsh blip that throws the rewind"],"variations":[{"name":"Stall Rewind","note":"Without the flip.","slug":"stall-rewind"},{"name":"Stall 360 Rewind","note":"A yaw 360 at the stall instead.","slug":"stall-360-rewind"}],"related":[{"name":"Stall Rewind","note":"The base stall-and-rewind.","slug":"stall-rewind"},{"name":"Flip","note":"The rotation at the top.","slug":"flip"}],"sources":["Pro Whooper"],"page":58,"pdfPage":60,"slug":"stall-flip-rewind","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-flip-rewind/"}]},{"name":"Throwback","difficulty":"Novice","category":"Rewinds","howto":"A throwback: throw the quad out and away, then snap it back on a rewind, as if it were on a bungee. Come in level near the ground and pitch back so it climbs out, and once you are facing the sky blip the throttle, then quickly drop it and pitch down to look back at where you punched out of. Float back with the momentum. The illusion is in the sudden reversal at the far end.","mastery":["Throw it out and snap it back.","Clean throw to the far point, tidy rewind back.","Big throw, crisp snap-back, dead on line."],"steps":["Approach level, then pitch the drone back","Facing the sky, blip throttle, then drop it and pitch down to look back","Float backwards with momentum"],"prereqs":["A confident stall","A feel for the stall-and-rewind"],"practice":"Come in level and low, pitch back to climb out, and time the blip so it reads as a sudden reversal at the top. Keep the line straight so it floats back the way it came.","mistakes":["A soft reversal that reads as a turn, not a snap","Drifting off the throw line","Blipping too early, before the far point"],"variations":[{"name":"Stall Rewind","note":"A vertical rewind.","slug":"stall-rewind"},{"name":"Sideways Rewind","note":"A rewind thrown to the side.","slug":"sideways-rewind"}],"related":[{"name":"Stall Rewind","note":"The core rewind.","slug":"stall-rewind"},{"name":"Boomerang","note":"Another out-and-back.","slug":"boomerang"}],"sources":["Rotor Riot"],"page":59,"pdfPage":61,"slug":"throwback","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Wall Bonk","difficulty":"Novice","category":"Wall Tricks","howto":"A deliberate, harder tap, bonking the wall head-on and bouncing straight back off it. Line up square with the face, commit into the bonk, and ride the bounce back the way you came. It is a bolder cousin of the wall tap, more contact and more commitment.","mastery":["Bonk the wall and bounce back under control.","Clean, controlled bonk with a steady bounce-back.","Confident bonk on a chosen spot, tidy recovery."],"steps":["Line up head-on with the wall","Bonk the face","Bounce straight back off"],"prereqs":["A confident wall tap","Nerve to commit into a surface"],"practice":"Start with light bonks on a clean, flat wall and build up the contact as your control improves. Square up before you commit, and be ready to catch the bounce.","mistakes":["Coming in at an angle and glancing off","Bonking too hard and tumbling","Not catching the bounce-back"],"variations":[{"name":"Wall Tap","note":"A lighter touch and peel.","slug":"wall-tap"},{"name":"Downtown Tap","note":"A roll-and-pitch tap with a flip out.","slug":"downtown-tap"}],"related":[{"name":"Wall Tap","note":"The lighter tap.","slug":"wall-tap"},{"name":"Wall Ride","note":"Riding the face instead.","slug":"wall-ride"}],"sources":["Rotor Riot"],"page":60,"pdfPage":62,"slug":"wall-bonk","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Alley-Oop","difficulty":"Intermediate","category":"Open Air","howto":"A matty flip set up off the side of an object. Approach along the side and, just past it, yaw and roll the quad up until it is facing straight up. Settle it level, then start a matty, rolling as you flip up and over the top, and ride it out flying backwards down the far side. It flows a stall-style pop-up straight into a matty for a big, showy exit.","mastery":["Pop up beside the object and matty out backwards.","Clean pop-up to face up, smooth matty over the top.","Crisp pop-up and a tight matty, floated out backwards."],"steps":["Approach the side; just past it, yaw left and roll up","Once facing up, pop the sticks back","Once level, start a matty","Roll and continue the matty, then pitch level","Level out and fly backwards"],"prereqs":["A confident matty flip","A feel for popping up to face up"],"practice":"Dial the pop-up to facing up off the side of an object first, then add the matty over the top once it settles level. Give yourself height and room, and keep it out to the side so you never drift into the object.","mistakes":["Rushing the matty before the quad is level","Not popping up far enough to face straight up","Drifting into the object on the way up"],"variations":[{"name":"Front Swing","note":"The side pop-up without the matty.","slug":"front-swing"},{"name":"Matty Flip","note":"The matty on its own.","slug":"matty-flip"}],"related":[{"name":"Matty Flip","note":"The flip at the heart of it.","slug":"matty-flip"},{"name":"Front Swing","note":"The side pop-up it builds on.","slug":"front-swing"}],"sources":["Mazta FPV tutorial"],"page":61,"pdfPage":63,"slug":"alley-oop","inputs":[{"L":[[-1,0]],"R":[[0.7,-0.7]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0.7,0.7]],"R":[[0.7,-0.7]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=0GACKQ9ED4Y"}]},{"name":"Backwards Dive","difficulty":"Intermediate","category":"Open Air","howto":"A building dive flown tail-first. Approach the top of the building head-on and, as you reach the edge, cut all your speed and drop straight down the face, pitching up to look back up the structure so you fall tail-first. Catch the fall near the bottom and keep flying backwards, away from the building the way you came in.","mastery":["Drop the face tail-first and back away clean.","Controlled backward dive down the face, smooth catch.","Committed tail-first dive tight to the face, floated out backwards."],"steps":["Approach the top of the object to dive","Nearing the edge, cut all speed and drop facing up","Catch the fall and continue backwards, away from the object"],"prereqs":["A confident building dive","A feel for backward flight"],"practice":"Dial a forward building dive and backward flight on their own first, then join them: approach the top, cut all speed, and let it fall down the face while you keep it pointed up the structure. Start on a shorter building with plenty of room at the bottom to catch the fall.","mistakes":["Carrying speed into the drop instead of cutting it","Losing the face and drifting off the building","Catching the fall too late"],"variations":[{"name":"Building Dive","note":"The forward version down the face.","slug":"building-dive"},{"name":"Backward Flying","note":"The backward line you ride out on.","slug":"backward-flying"}],"related":[{"name":"Building Dive","note":"The forward version down a building.","slug":"building-dive"},{"name":"Backward Flying","note":"The backward flight it rides out on.","slug":"backward-flying"}],"sources":["Rotor Riot"],"page":62,"pdfPage":64,"slug":"backwards-dive","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Blind Loop","difficulty":"Intermediate","category":"Miscellaneous","howto":"A loop around an object that closes on itself, flown with a 180 yaw so you spend the loop facing backwards, blind to where you are going. Start low and climb toward the top, spinning a 180 to face back the way you came. Near the top, still backwards, throttle up and pitch up to carry the loop over and down to the bottom, coming out facing where you started. Ride the last of the line back to your start point, finishing exactly where you began.","mastery":["Loop the object backwards and finish where you started.","Smooth blind loop, closing on the start point.","Tight, controlled loop flown backwards, dead on the start."],"steps":["Start low, approach the top with a 180 yaw to face backwards","Near the top, throttle up and pitch up to complete the loop","Continue the path back to the start point"],"prereqs":["A confident powerloop","Comfort flying backwards, on feel"],"practice":"Get a powerloop dialed first, then add the 180 yaw so you carry the loop facing backwards. Fly it on feel and aim to finish right where you began. Give yourself room and a clear object to loop around.","mistakes":["Losing the yaw and drifting off the loop","Ballooning the loop and missing the start point","Panicking once you are facing backwards"],"variations":[{"name":"Powerloop","note":"A loop over an obstacle.","slug":"powerloop"},{"name":"Maverick Loop","note":"A loop under an obstacle.","slug":"maverick-loop"}],"related":[{"name":"Powerloop","note":"A loop over an obstacle.","slug":"powerloop"},{"name":"Flip","note":"The loop it is built on.","slug":"flip"}],"sources":["Pro Whooper"],"page":63,"pdfPage":65,"slug":"blind-loop","inputs":[{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/blind-loop/"}]},{"name":"Ceiling Tap","difficulty":"Intermediate","category":"Wall Tricks","howto":"Tapping an overhead surface from below. Approach up from one side to kiss the underside of a ceiling, overhang, or beam with a light touch, then cut throttle and return back down the way you came. Like a wall tap, it is all about a soft touch and a controlled exit, just pointed up instead of across.","mastery":["Tap the ceiling and drop away under control.","Light, clean tap with a smooth drop-down.","Precise taps on an overhead surface, no bounce."],"steps":["Approach up from the left to the object","Tap the underside","Return back down the way you came"],"prereqs":["Confident vertical control","A soft, controlled touch"],"practice":"Find a solid overhang or ceiling with clear air below. Start with the gentlest taps and a controlled drop, building up as your vertical control improves. Scout the surface first.","mistakes":["Punching up too hard and bouncing off","Drifting sideways into the surface","Dropping out of control after the tap"],"variations":[{"name":"Wall Tap","note":"Tap a vertical wall instead.","slug":"wall-tap"},{"name":"Downtown Tap","note":"A tap with a roll and a flip out.","slug":"downtown-tap"}],"related":[{"name":"Wall Tap","note":"The same touch on a vertical wall.","slug":"wall-tap"},{"name":"Loop Tap","note":"A tap with a rotation added.","slug":"loop-tap"}],"sources":["Pro Whooper"],"page":64,"pdfPage":66,"slug":"ceiling-tap","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/ceiling-tap/"}]},{"name":"Coin Drop","difficulty":"Intermediate","category":"Miscellaneous","howto":"A Vanny Roll flown out and then rewound, like winding a coin back up. Approach the obstacle yaw-tracking it through 180, blip the throttle and cross with a coordinated 360 roll, then rewind the roll and rewind the yaw to come back the way you came. It is a Vanny Roll and its mirror image, back to back.","mastery":["Track, roll across, and rewind back clean.","Smooth 360 roll and a tidy rewind of roll and yaw.","Coordinated track, roll, and full rewind, dead on line."],"steps":["Approach the obstacle, yaw-spin tracking it 180","Throttle blip and cross with a coordinated 360 roll","Rewind the roll","Rewind the yaw"],"prereqs":["A confident Vanny Roll","Coordinated roll and yaw"],"practice":"Get the Vanny Roll dialed first, then practise rewinding it: after the roll and cross, unroll and unyaw back to where you started. Keep the roll and yaw coordinated in both directions.","mistakes":["Losing coordination on the rewind","Not fully rewinding the roll or the yaw","Drifting off the line coming back"],"variations":[{"name":"Vanny Roll","note":"The one-way version without the rewind.","slug":"vanny-roll"},{"name":"Barrel Roll","note":"The coordinated roll on its own.","slug":"barrel-roll"}],"related":[{"name":"Vanny Roll","note":"The one-way version this rewinds.","slug":"vanny-roll"},{"name":"Barrel Roll","note":"The coordinated roll at its core.","slug":"barrel-roll"}],"sources":["Mazta FPV tutorial"],"page":65,"pdfPage":67,"slug":"coin-drop","inputs":[{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=fT2SgTkLFGI"}]},{"name":"Cubik's Rube","difficulty":"Intermediate","category":"Open Air","howto":"The Rubik's Cube run in reverse: roll first, then a flat yaw, then a flip to finish, turning the quad on every axis. Roll out, pin the yaw, and flip. It is the same puzzle as the Rubik's Cube with the pieces in a different order.","mastery":["Roll, yaw, and flip in one line.","Clean three-axis combo in reverse order.","Seamless Cubik's Rube, every axis crisp and on line."],"steps":["Roll out first","Pin a flat yaw","Flip to finish"],"prereqs":["Clean rolls, yaw spins, and flips","A feel for chaining axes"],"practice":"Have each axis solid, then chain them roll-yaw-flip on one line, keeping it straight through all three. Smooth the hand-offs between the turns.","mistakes":["Drifting off line between the turns","Rushing one axis into the next","An uneven turn on one of the axes"],"variations":[{"name":"Rubik's Cube","note":"The same axes flip-first.","slug":"rubik-s-cube"},{"name":"Rubik's Cube Pendulum","note":"The combo on a pendulum swing.","slug":"rubik-s-cube-pendulum"}],"related":[{"name":"Rubik's Cube","note":"The flip-first order.","slug":"rubik-s-cube"},{"name":"Rubik's Cube Pendulum","note":"On a pendulum.","slug":"rubik-s-cube-pendulum"}],"sources":["Pro Whooper"],"page":66,"pdfPage":68,"slug":"cubik-s-rube","inputs":[{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/cubiks-rube/"}]},{"name":"Double Dutch","difficulty":"Intermediate","category":"Jump Ropes","howto":"A jump rope with a reverse 360 roll thrown in at the top. Yaw sideways and enter beneath the object as for a jump rope, throttle up and, once at the top of the loop, snap a reverse 360 roll, then continue looping back down and under the object. It is a jump rope dressed up with a roll over the top.","mastery":["Loop the object and land a reverse 360 roll up top.","Smooth jump rope with a clean reverse roll over the top.","Tight loop and a crisp reverse 360, back down clean."],"steps":["90° flat yaw spin, enter under the object sideways","Throttle up and, at the top, perform a reverse 360 roll","Continue to loop back down and under the object"],"prereqs":["A solid jump rope","A quick, controllable roll"],"practice":"Get the jump rope dialed first, then add a reverse 360 roll right at the top of the loop, staying over the object. Keep the loop tight so the roll has room to complete before you come back down.","mistakes":["Rushing the roll before the top","Losing the loop line during the roll","Not completing the 360 before coming down"],"variations":[{"name":"Jump Rope","note":"The same loop without the roll.","slug":"jump-rope"},{"name":"Cinnamon Roll","note":"A roll folded into the swing instead.","slug":"cinnamon-roll"}],"related":[{"name":"Jump Rope","note":"The loop it builds on.","slug":"jump-rope"},{"name":"Cinnamon Roll","note":"A jump rope with a roll in the swing.","slug":"cinnamon-roll"}],"sources":["Pro Whooper"],"page":67,"pdfPage":69,"slug":"double-dutch","inputs":[{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/double-dutch/"}]},{"name":"Downtown Tap","difficulty":"Intermediate","category":"Wall Tricks","howto":"Tapping an object while flipped away from it. Fly at the object and, as you reach it, roll 180 and pitch back 90 at the same time so you end up looking down and away from it, and tap it in that orientation. Straight after the tap, roll into a smooth front flip, then fly swiftly away to finish.","mastery":["Roll-and-pitch into the tap, front flip, and away.","Clean reorientation, tidy tap, smooth front flip out.","Committed roll-pitch tap and a crisp front flip, gone."],"steps":["Fly toward the object","Roll 180 and pitch back 90 to face down and away, and tap","Perform a front flip","Swiftly fly away"],"prereqs":["Comfortable multi-axis rotations","A confident front flip"],"practice":"Break it down: practise the combined 180 roll and 90 pitch-back on its own first, then add a light tap, then the front flip out. Give yourself room off the object and build the pieces up slowly.","mistakes":["Not committing the roll and pitch together","Tapping too hard and knocking off line","Rushing the front flip before you are clear"],"variations":[{"name":"Wall Tap","note":"A plain tap, no reorientation.","slug":"wall-tap"},{"name":"Matty Flip","note":"The flip on its own.","slug":"matty-flip"}],"related":[{"name":"Wall Tap","note":"The basic tap this dresses up.","slug":"wall-tap"},{"name":"Flip","note":"The front flip in the exit.","slug":"flip"}],"sources":["Pro Whooper"],"page":68,"pdfPage":70,"slug":"downtown-tap","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0.7,-0.7]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/downtown-tap/"}]},{"name":"Flat Bounce Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"A roll and a loop stitched together low to the ground. Punch a roll and let it dish down toward the deck, correct the roll just before the ground, then punch a forward loop back up and, once you come around to upside down, roll out to finish. It drops to the deck and rewinds up and away.","mastery":["Roll to the deck, correct, loop up, and roll out.","Clean roll and correction, smooth loop and roll-out.","Tight roll to the deck and a crisp loop, rolled out inverted."],"steps":["Punch a roll","Correct it near the ground","Punch a forward loop","Once upside down, roll out"],"prereqs":["A confident roll and correction","A punchy forward loop"],"practice":"Break it into pieces: a roll that dishes toward the deck and corrects near the ground, then a punched forward loop with a roll-out once you hit inverted. Start high and bring the bounce point down as it cleans up.","mistakes":["Not correcting the roll before the ground","A weak loop punch that stalls out","Rolling out before you are fully upside down"],"variations":[{"name":"Stall Rewind","note":"A rewind off a stall instead of the ground.","slug":"stall-rewind"},{"name":"Barrel Roll","note":"The roll on its own.","slug":"barrel-roll"}],"related":[{"name":"Stall Rewind","note":"Another way to rewind.","slug":"stall-rewind"},{"name":"Flip","note":"The forward loop it punches.","slug":"flip"}],"sources":["Mazta FPV tutorial"],"page":69,"pdfPage":71,"slug":"flat-bounce-rewind","inputs":[{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=dFG_icTXtw8"}]},{"name":"Half Matty","difficulty":"Intermediate","category":"Matty Flips","howto":"A half matty flown through a gap. Approach the gap between two objects and start a cross-coordinated half roll to inverted. Once you come around upside down, pitch forward and feed in throttle to bring the quad back upright but now facing backwards, then keep going backwards through the gap and yaw out once you are past it. It flips your heading without turning around, and the line keeps going rather than doubling back.","mastery":["Half roll through the gap and out backwards.","Clean roll to inverted, smooth reorient, tidy yaw out.","Crisp cross-coordinated half roll, backwards through, dialed yaw out."],"steps":["Approach the gap and start a cross-coordinated half roll","Upside down, pitch forward and throttle up to face backwards","Continue backwards through the gap and yaw out past it"],"prereqs":["A clean, controllable half roll","Comfort inverted and flying backwards"],"practice":"Find a gap you can fly through. Get the cross-coordinated half roll to inverted smooth first, then the pitch-and-throttle reorient to upright-backwards, and finish with a clean yaw out once you are past the gap. Build it up slowly.","mistakes":["Rushing the half roll before the gap","Not reorienting fully before you reach the gap","Yawing out too early, before you are past it"],"variations":[{"name":"Stall Half Matty","note":"Hold a longer stall at the top before descending."},{"name":"Half Matty Rewind","note":"Rewind back over the top instead of passing under."}],"related":[{"name":"Matty Flip","note":"The full version with a forward flip over the top.","slug":"matty-flip"},{"name":"Split S","note":"The same reverse-and-descend, without the object.","slug":"split-s"},{"name":"Snapback","note":"Another half-rotation reversal.","slug":"snapback"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":70,"pdfPage":72,"slug":"half-matty","inputs":[{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/half-matty/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=yyvGYJBwvcA"}]},{"name":"Immelloop","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop with a 180 roll at the apex, so you come out of it flying backwards. Powerloop up and over the object as usual, but at the top, while inverted, add a 180 roll to bring the quad upright again, still pointed the way you started. Keep that backwards orientation and pitch back slightly to carry your momentum backwards down and through the bottom of the loop. The path is a powerloop; the difference is which way you are facing.","mastery":["Loop the object and roll upright at the top, out backwards.","Clean loop, crisp 180 at the apex, smooth backwards exit.","Seamless powerloop with a dialed apex roll, backwards through the bottom."],"steps":["Powerloop up and over the object","At the top upside down, 180 roll to upright, facing where you started","Keep backwards, pitch back slightly for momentum through the bottom"],"prereqs":["A confident powerloop","A clean 180 roll"],"practice":"Have the powerloop dialed, then add a 180 roll right at the inverted apex so you come upright but facing backwards. Keep the loop shape and let your momentum carry you backwards through the bottom. Give yourself room.","mistakes":["Rolling before you reach the inverted apex","Losing the loop shape during the roll","Not keeping the backwards momentum through the bottom"],"variations":[{"name":"Power Switch","note":"A yaw switch at the top instead of a roll.","slug":"power-switch"},{"name":"Powerloop","note":"The same loop without the apex roll.","slug":"powerloop"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Power Switch","note":"A powerloop that exits turned around, via yaw.","slug":"power-switch"},{"name":"Matty Flip","note":"Another over-the-top move.","slug":"matty-flip"}],"sources":["Pro Whooper"],"page":71,"pdfPage":73,"slug":"immelloop","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-0.5]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/immelloop/"}]},{"name":"Inverted Lookback","difficulty":"Intermediate","category":"Open Air","howto":"An inverted hang built from a front roll, with no yaw at all. Gain a little forward speed, then blip the throttle and pitch into a front roll to bring the quad inverted, and pause there to hang upside down, looking back the way you came. When you are ready, finish the roll to come back upright and carry on forward. It is a front roll with a hang stalled into the middle of it.","mastery":["Flip to inverted, hang, and roll out forward.","Smooth flip into a clean inverted hang, tidy exit.","Controlled front roll with a held inverted hang, dead level out."],"steps":["Gain forward momentum, then blip throttle and invert","Once upside down and looking back, hang for a bit","Finish the forward roll to continue moving forward"],"prereqs":["A controllable front roll","A feel for the inverted hang"],"practice":"Get a smooth front roll first, then learn to pause it at the inverted point and hold the hang before completing the rotation. Start high with plenty of room and build up the hang time as it gets steadier.","mistakes":["Rushing through the inverted point instead of hanging","Losing the forward line during the hang","Not completing the roll cleanly on the exit"],"variations":[{"name":"Juicy Flick","note":"A pop to inverted and a hang.","slug":"juicy-flick"},{"name":"Matty Flip","note":"The full front flip without the hang.","slug":"matty-flip"}],"related":[{"name":"Juicy Flick","note":"A blip to inverted with a brief hang.","slug":"juicy-flick"},{"name":"Matty Flip","note":"A full front flip.","slug":"matty-flip"}],"sources":["Mazta FPV tutorial"],"page":72,"pdfPage":74,"slug":"inverted-lookback","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=zsOiLwK0NCQ"}]},{"name":"Juicy Cartwheel","difficulty":"Intermediate","category":"Open Air","howto":"Yaw-spin around an object, then blip and roll out of it. Approach the object and yaw-spin all the way around it, and once you have come back around, blip the throttle and throw a roll. Balance the throttle through the roll so you complete it cleanly on the line. Marrying the yaw-spin into a coordinated roll is what gives it the juicy, flowing feel.","mastery":["Yaw-spin an object and roll out of it.","Smooth yaw-spin into a clean, floaty roll.","Dialed both directions, on line, object framed."],"steps":["Approach object and yaw spin around it","Once around the object, blip throttle and roll","Slowly balance speed to complete the roll"],"prereqs":["A clean yaw spin around an object","A clean, coordinated roll"],"practice":"Get the yaw-spin around an object dialed first, then practice blipping and rolling out of it. Coordinate a little throttle through the roll so it floats and finishes on the line rather than dropping. Both directions.","mistakes":["Losing the object out of frame through the yaw spin","Rushing the roll instead of balancing the throttle","Dropping altitude or drifting off the line"],"variations":[{"name":"Side Loop","note":"A sideways loop around an object.","slug":"side-loop"},{"name":"Barrel Roll","note":"A corkscrew roll along the line.","slug":"barrel-roll"}],"related":[{"name":"Coin Drop","note":"The same yaw-and-roll path, rewound.","slug":"coin-drop"},{"name":"Roll","note":"The axis it finishes on.","slug":"roll"}],"sources":["Mazta FPV tutorial"],"page":73,"pdfPage":75,"slug":"juicy-cartwheel","inputs":[{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0.7,0.7]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=uvIvAzPRXiU"}]},{"name":"Juicy Double Roll","difficulty":"Intermediate","category":"Open Air","howto":"A Juicy Flick finished with a quick double roll instead of a slow roll-out. From a cruising line, blip the throttle to unload the quad and snap a 180 pitch up to inverted, hang there floaty for a beat, then rip a quick 540 roll to recover forward on the same line. The contrast between the lazy hang and the snappy double roll is what sells it.","mastery":["Pop to inverted and double roll out on the same line.","Floaty flick into a crisp, even double roll.","Effortless flick and a snappy 540 that lands dead on line."],"steps":["Blip the throttle and snap a 180 pitch to inverted","Hang inverted, floaty, for a beat","Do a quick \"double\" (540) roll"],"prereqs":["A clean Juicy Flick","An even, controlled double roll"],"practice":"Have the flick and the double roll each solid on their own, then join them: keep the hang lazy and let the 540 be the snappy part. Give yourself height and check the exit stays on the original line.","mistakes":["Starting the roll before the hang has settled","An uneven 540 that stops off-axis","Losing the line, so you recover off-track"],"variations":[{"name":"Juicy Flick","note":"The same flick with a slow single roll-out.","slug":"juicy-flick"},{"name":"Double Roll","note":"The double roll on its own.","slug":"double-roll"}],"related":[{"name":"Juicy Flick","note":"The flick it is built on.","slug":"juicy-flick"},{"name":"Double Roll","note":"The 540 that finishes it.","slug":"double-roll"}],"sources":["BaconNinjaFPV"],"page":74,"pdfPage":76,"slug":"juicy-double-roll","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}]},{"name":"Juicy Tracking-Lookback","difficulty":"Intermediate","category":"Open Air","howto":"A tracking lookback with a flick through the middle. Approach the object yawing past it at an angle so it stays centered, and as you pass, flick-loop the sticks and carry the yaw through with the opposite angle. Then level out, still looking back at the object. Holding the frame through the flick and the yaw reversal is what gives it the juicy feel.","mastery":["Yaw-track past an object and look back.","Smooth angled track with a clean flick and lookback.","Buttery tracking lookback, object framed the whole way."],"steps":["Approach object, yawing past it at an angle, keeping it centered","Passing the object, flick loop clockwise, yaw the opposite angle","Level out looking back at the object"],"prereqs":["A smooth yaw-track around an object","A clean flick loop"],"practice":"Track an object with yaw as you pass at an angle, keeping it centered, then work the flick and the yaw reversal, leveling out with the object still framed behind you. Keep it floaty and give the object room.","mistakes":["Losing the object out of frame","A jerky flick that breaks the frame","Not carrying the yaw through the reversal"],"variations":[{"name":"Juicy Cartwheel","note":"The same path, rolled out.","slug":"juicy-cartwheel"},{"name":"Inverted Lookback","note":"A lookback flown inverted.","slug":"inverted-lookback"}],"related":[{"name":"Juicy Cartwheel","note":"The same yaw-spin path.","slug":"juicy-cartwheel"},{"name":"Inverted Lookback","note":"A lookback flown inverted.","slug":"inverted-lookback"}],"sources":["Mazta FPV tutorial"],"page":75,"pdfPage":77,"slug":"juicy-tracking-lookback","inputs":[{"L":[[-1,0]],"R":[[-0.94,-0.34]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[-0.94,0.34]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Ugy7drDWFbs"}]},{"name":"Jump Rope","difficulty":"Intermediate","category":"Jump Ropes","howto":"A loop around a horizontal object flown flat and sideways: the quad yaws 90 degrees to face sideways and rolls its way around, staying level the whole time instead of pitching inverted like a powerloop. Yaw and enter beneath the object facing sideways, throttle up and roll to carry it up and around, and cut throttle and correct the roll as you pass back over the top. Because it rolls rather than pitches, it never goes inverted.","mastery":["Loop around the object flat and sideways.","Smooth, level loop, sideways the whole way round.","Tight, level jump rope, dead sideways, clean over the top."],"steps":["90° flat yaw spin, enter under the obstacle sideways","Throttle up and roll right to loop around","Pass over the top, cut throttle and correct roll"],"prereqs":["Coordinated throttle and roll","Comfortable flying sideways (yawed 90°)"],"practice":"Find a horizontal object, a branch, bar, or gap edge. Yaw sideways, drop beneath it, and roll up and around it, keeping the quad level rather than letting it pitch inverted. Cut throttle as you clear the top. Build the loop up slowly.","mistakes":["Letting it pitch inverted like a powerloop","Drifting off the sideways heading","Carrying throttle over the top instead of cutting it"],"variations":[{"name":"Burrito Roll","note":"Add a roll and go under on the finish.","slug":"burrito-roll"},{"name":"Double Dutch","note":"A jump rope with a reverse 360 roll at the top.","slug":"double-dutch"}],"related":[{"name":"Powerloop","note":"The inverted, pitching cousin.","slug":"powerloop"},{"name":"Burrito Roll","note":"A jump rope with a roll and an under-pass.","slug":"burrito-roll"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":76,"pdfPage":78,"slug":"jump-rope","inputs":[{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/jump-rope/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=8gnH_YtaXak"}]},{"name":"Laser Flip","difficulty":"Intermediate","category":"Open Air","howto":"A knife-edge yaw spin over an object. Climb over the object gaining height, and as you reach the top, twist to point the nose straight down at it. On that knife edge, feed in a coordinated yaw and spin around the vertical, then roll away and descend out. Pointing dead at the object and holding the knife edge through the spin is what makes it hard.","mastery":["Spin on a knife edge over an object.","Clean knife-edge yaw spin, nose on the object.","Dialed laser flip, pinned on the object, smooth out."],"steps":["Approach object gaining height to pass over it","Approaching the top, twist into facing the object","Facing down at it, coordinated yaw spin on a knife edge","Completing the vertical yaw spin, roll away"],"prereqs":["A confident knife edge","A clean, coordinated yaw spin"],"practice":"Pick an object, climb over it, and practise twisting to point straight down at it. Feed in the yaw to spin around the vertical on the knife edge, keeping the nose on the object, then roll away. Start high and give yourself room.","mistakes":["Not getting the nose fully onto the object","Falling off the knife edge mid-spin","Losing too much height before you roll away"],"variations":[{"name":"Knife Edge","note":"Holding the vertical without the spin.","slug":"knife-edge"},{"name":"Inverted Yaw Spin","note":"A yaw spin flown inverted.","slug":"inverted-yaw-spin"}],"related":[{"name":"Knife Edge","note":"The vertical attitude it spins on.","slug":"knife-edge"},{"name":"Inverted Yaw Spin","note":"Spinning around the vertical.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":77,"pdfPage":79,"slug":"laser-flip","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=CyS0C_DJO9o"}]},{"name":"Lookback & Loop","difficulty":"Intermediate","category":"Open Air","howto":"A lookback that springs into a loop and rewinds. Carry some forward momentum into a 180 yaw so you are looking back the way you came, then punch the throttle and pitch up to spring to the top of a loop. Float through it upside down, around the back side, and at the bottom blip the throttle to carry back toward where you started. The abrupt spring into the loop is what sets it apart.","mastery":["Yaw back, spring into a loop, rewind out.","Clean 180 yaw sprung into a floaty back-side loop.","Seamless lookback, loop, and rewind back to start."],"steps":["Begin with forward momentum into a 180 yaw","Looking backwards, throttle punch and pitch up","Upside down, float through the loop","At the bottom, blip throttle back toward start"],"prereqs":["A confident 180 lookback yaw","A floaty loop"],"practice":"Carry momentum into a 180 yaw, then work the abrupt punch-and-pitch to spring up to the top of a loop. Float around the back side and blip back toward where you started. Keep the loop round and give yourself height.","mistakes":["A soft spring that never reaches the top of the loop","Losing the line through the 180 yaw","Not blipping to carry back toward the start"],"variations":[{"name":"Inverted Lookback","note":"A lookback flown inverted.","slug":"inverted-lookback"},{"name":"Lookback + Roll + Inverted Yaw Spin","note":"A longer lookback combo.","slug":"lookback-plus-roll-plus-inverted-yaw-spin"}],"related":[{"name":"Inverted Lookback","note":"The inverted look.","slug":"inverted-lookback"},{"name":"Loop","note":"The loop it finishes with.","slug":"loop"}],"sources":["Mazta FPV tutorial"],"page":78,"pdfPage":80,"slug":"lookback-and-loop","inputs":[{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=0QAK68uip8E"}]},{"name":"Loop to Matty","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop that turns into a Matty at the top. Come in low underneath an object and pitch up as if starting a powerloop, climbing up behind it to a peak above the objects. Rather than carrying the loop all the way over, catch it at the top, where you are inverted and facing backwards, and Matty forward to upright and facing forwards. Hold the throttle and your line and drop back down through the gap between the objects, backwards, coming out above where you went in. Reading the peak and trading the loop for the Matty at the right moment is the whole trick.","mastery":["Loop up behind and Matty back through the gap.","Clean climb into a Matty timed at the peak.","Seamless loop-to-Matty, dead on line through the gap."],"steps":["Approach under an object, pitching drone up as if starting a powerloop","Facing backwards upside down above the objects, pitch back forward to upright facing forwards","Maintain throttle and alignment to pass through the gap backwards"],"prereqs":["A confident powerloop","A Matty you can start from inverted"],"practice":"Fly the climb-and-peak on its own until you can arrive at the top with the nose coming over and speed in hand, because the Matty has nothing to work with off a dying climb. Then trade the loop for the Matty at the peak and line up the gap for the drop back through. Keep it all on one line so it tracks straight from above.","mistakes":["Carrying the loop over instead of catching it at the peak","Mattying before you are level and inverted at the top","Missing the gap alignment on the way down","Losing the line so it no longer tracks straight"],"variations":[{"name":"Immelmatt","note":"An Immelmann into the Matty instead.","slug":"immelmatt"},{"name":"Matty Flip","note":"The Matty on its own.","slug":"matty-flip"}],"related":[{"name":"Loop","note":"The loop it starts with.","slug":"loop"},{"name":"Matty Flip","note":"The Matty it flows into.","slug":"matty-flip"}],"sources":["Pro Whooper"],"page":79,"pdfPage":81,"slug":"loop-to-matty","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-0.2]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/loop-to-matty/"}]},{"name":"Matty Twister","difficulty":"Intermediate","category":"Matty Flips","howto":"A Matty with a 360 roll folded in while pointing straight down at the object. Approach over the object and pitch the nose down, and when you are facing down at it, throw a full 360 roll (which reads as a yaw from that attitude). Resume the pitch to finish the Matty over the far edge and back under, recovering at the bottom moving back the way you came but facing backwards. Optionally yaw out to face forward again.","mastery":["Fold a 360 roll into a Matty, facing down.","Clean face-down 360 roll, smooth Matty out.","Seamless Matty twister, roll pinned, tidy recovery."],"steps":["Approach over an object and pitch the drone down","Facing down at the object, do a 360 roll","Resume pitching to complete the Matty roll","Recover at the bottom, moving back but facing backwards","Optionally yaw out"],"prereqs":["A clean Matty Flip","A confident 360 roll"],"practice":"Get the Matty solid, then add a pause facing straight down at the object to fit a 360 roll before you finish the flip. Keep the roll centered on the object and recover clean under it. Yaw out to finish if you like.","mistakes":["Not getting the nose fully down before the roll","An off-center roll that drifts off the object","A messy recovery under the object"],"variations":[{"name":"Matty Flip","note":"Without the twist.","slug":"matty-flip"},{"name":"Matty 360","note":"A full 360 yaw on the under instead.","slug":"matty-360"}],"related":[{"name":"Matty Flip","note":"The base trick.","slug":"matty-flip"},{"name":"Matty 360","note":"A full yaw 360 folded in.","slug":"matty-360"}],"sources":["Pro Whooper"],"page":80,"pdfPage":82,"slug":"matty-twister","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/matty-twister/"}]},{"name":"Outward Side Lock Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"An outward side-lock rewind flown on an angle. Approach the side of the object banked about 30 degrees to the horizon, then swing around it holding that angle so it stays framed. Keep swinging until the object slides out of view, lock the quad in place, and blip the throttle to begin the rewind, retracing the swing back the way you came while holding the same angle.","mastery":["Swing around an object on an angle and rewind.","Clean angled swing, locked, smooth rewind back.","Crisp outward side-lock rewind, angle held throughout."],"steps":["Approach the side of the object at a 30 degree angle","Swing around the object keeping the angle","As the object leaves view, lock and blip to rewind","Rewind back, holding the angle"],"prereqs":["Confident flight on a held bank angle","A feel for locking a subject and rewinding"],"practice":"Approach an object's side on a roughly 30 degree bank and swing around it holding the angle. When it leaves the frame, lock and blip back, retracing the swing on the same angle. Keep it smooth both ways.","mistakes":["Losing the angle through the swing","Not locking cleanly before the rewind","An uneven rewind that doesn't retrace the swing"],"variations":[{"name":"Side-Lock Rewind","note":"The inward version.","slug":"side-lock-rewind"},{"name":"Sideways Rewind","note":"Without locking a subject.","slug":"sideways-rewind"}],"related":[{"name":"Side-Lock Rewind","note":"The core side-lock rewind.","slug":"side-lock-rewind"},{"name":"Sideways Rewind","note":"A lateral rewind.","slug":"sideways-rewind"}],"sources":["Mazta FPV tutorial"],"page":81,"pdfPage":83,"slug":"outward-side-lock-rewind","inputs":[{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0.34,-0.94]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[-0.34,-0.94]],"R":[[-0.94,-0.34]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=VzwQobYtErk"}]},{"name":"Power Flip","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop with an extra in-place 360 loop thrown in at the top. Come in low and level with speed and pull into the loop, and when you reach the top inverted, snap a tight in-place 360 loop before continuing the main loop back down. Carry the throttle through and level out on the entry line. It is a powerloop with a flip folded into its apex.","mastery":["Powerloop with an in-place 360 at the top.","Clean powerloop, tidy 360 folded in at the apex.","Seamless power flip, both rotations crisp, level out."],"steps":["Approach low with speed; commit to the line","Loop around until upside down, and perform an in place 360 loop there, then continue the main loop back down","Carry throttle over the top, inverted","Relax pitch, catch level on the entry line"],"prereqs":["A solid Powerloop","A tight, quick flip"],"practice":"Get the powerloop dialed, then work the in-place 360 at the top: reach the apex inverted, snap the extra loop, and continue the powerloop down. Give yourself height over the obstacle.","mistakes":["Losing throttle at the top and dropping out","A sloppy 360 that breaks the main loop","Not catching level on the entry line"],"variations":[{"name":"Powerloop","note":"Without the in-place 360.","slug":"powerloop"},{"name":"Reversed Power Flip","note":"The other direction.","slug":"reversed-power-flip"}],"related":[{"name":"Powerloop","note":"The base loop.","slug":"powerloop"},{"name":"Double Dutch","note":"A powerloop with a reverse 360 roll instead.","slug":"double-dutch"}],"sources":["Pro Whooper"],"page":82,"pdfPage":84,"slug":"power-flip","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":true},{"L":[[0,0.4]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-flip/"}]},{"name":"Power Matty","difficulty":"Intermediate","category":"Matty Flips","howto":"A Matty with a forward loop folded in at the top. Fly over the object, and just before you drop into the matty, throw a forward loop. Then drop down behind the object and fly backward under it, feeding in throttle and pitching to level out as you pass beneath. The loop at the top is what sets it apart from a plain Matty.","mastery":["Forward-loop over the object, then Matty under.","Clean forward loop into a tidy Matty under-pass.","Crisp loop and Matty, aligned exit, smooth level-out."],"steps":["Fly over the object","Just before dropping into the matty, do a forward loop","Fly backward under, throttle up and level out"],"prereqs":["A confident Matty Flip","A clean forward loop"],"practice":"Find an object with clear air above and below. Fly over it, throw a forward loop just before you drop in, then drop down behind and fly backward under it, feeding in throttle to level out. Give yourself height.","mistakes":["A sloppy loop that doesn't line up the drop","Not enough height, so you drop too low","Losing the object out of frame"],"variations":[{"name":"Matty Flip","note":"The standard over-and-under, no loop.","slug":"matty-flip"},{"name":"Anti Matty","note":"A full backflip instead of a forward loop.","slug":"anti-matty"}],"related":[{"name":"Matty Flip","note":"The base over-and-under.","slug":"matty-flip"},{"name":"Anti Matty","note":"The backflip version.","slug":"anti-matty"}],"sources":["Pro Whooper"],"page":83,"pdfPage":85,"slug":"power-matty","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-matty/"}]},{"name":"Power Split","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop that finishes as a Split-S. Carry throttle up and over the obstacle as you would a powerloop, but at the top, instead of completing the loop, roll upright and pull a Split-S down the far side, exiting the opposite direction and lower. It swaps the loop's finish for a reversal.","mastery":["Loop up and split-S out the far side.","Smooth loop into a clean roll-and-split exit.","Seamless powerloop and Split-S as one flowing line."],"steps":["Approach under object, pitching drone up","Roll out at the top","Split-S down the far side"],"prereqs":["A confident powerloop","A clean Split-S"],"practice":"Have both the powerloop and the Split-S dialed, then blend them: loop up, and at the top roll out and pull the split down the far side. Give yourself height for the descent.","mistakes":["Rolling out too early, before the top","Not committing the throttle up the loop","Diving out of the split instead of leveling"],"variations":[{"name":"Powerloop","note":"The full loop without the split exit.","slug":"powerloop"},{"name":"Split S","note":"The reversal without the loop entry.","slug":"split-s"}],"related":[{"name":"Powerloop","note":"The loop it starts with.","slug":"powerloop"},{"name":"Split S","note":"The reversal it finishes with.","slug":"split-s"}],"sources":["Pro Whooper"],"page":84,"pdfPage":86,"slug":"power-split","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":true}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-split/"}]},{"name":"Power Swap","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop that swaps out into a backwards matty. Carry throttle up and over into the loop, and as you reach the top still facing up, roll 180 so your belly faces the sky. Let the momentum carry you around the other side of the roll and matty backwards under the object. It swaps the loop's exit for a rolled, backward under-pass.","mastery":["Loop up, roll belly-to-sky, matty out backwards.","Clean loop into a tidy top roll and backward under.","Seamless power swap, roll pinned, smooth matty under."],"steps":["Approach low with speed; commit to the line","Full back-pitch + throttle to climb into the loop","At the top still facing up, 180 roll to face the sky","Let momentum carry around the roll and matty backwards under"],"prereqs":["A confident powerloop","A clean 180 roll"],"practice":"Have the powerloop solid, then work the 180 roll at the top with your belly to the sky, letting momentum carry you around and back under the object. Give yourself height.","mistakes":["Rolling before you reach the top of the loop","Not committing the throttle up the loop","Losing the object as you come around backwards"],"variations":[{"name":"Powerloop","note":"Without the roll and swap.","slug":"powerloop"},{"name":"Power Switch","note":"A yaw switch at the top instead of a roll.","slug":"power-switch"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Matty Flip","note":"The under-pass it finishes with.","slug":"matty-flip"}],"sources":["Pro Whooper"],"page":85,"pdfPage":87,"slug":"power-swap","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":true,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-swap/"}]},{"name":"Reverse Knife Edge","difficulty":"Intermediate","category":"Gaps","howto":"A knife-edge taken backwards through a gap. Line up the narrow slot early and blip the throttle, then roll 90 onto the knife edge and pitch 180 so you slip through the gap backwards, narrow profile first. Float through and correct your orientation on the far side. It threads a tight slot backwards on the knife edge.","mastery":["Slip through a gap backwards on the knife edge.","Clean roll-and-pitch into a backward knife-edge gap.","Tight slot threaded backwards, knife-edge, dead on line."],"steps":["Line up the narrow gap early, blip throttle","90 roll and 180 pitch to head backwards through the gap on knife edge","Float through the gap and correct orientation"],"prereqs":["A solid knife-edge","Comfortable rolling and pitching to face backwards"],"practice":"Line up a narrow gap, then practise rolling onto the knife edge and pitching 180 to slip through backwards. Commit the rotation before the gap and correct on the far side.","mistakes":["Rotating in the gap instead of before it","Not enough bank to clear the sides","Losing orientation flying through backwards"],"variations":[{"name":"Knife Edge","note":"Banked the usual way.","slug":"knife-edge"},{"name":"Ninja Star","note":"A knife-edge gap in a combo.","slug":"ninja-star"}],"related":[{"name":"Knife Edge","note":"The other-way version.","slug":"knife-edge"},{"name":"Gaps","note":"Threading an opening flat.","slug":"gaps"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":86,"pdfPage":88,"slug":"reverse-knife-edge","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/reverse-knife-edge/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=BkdoJlJRVsw"}]},{"name":"Reverse Wall Ride","difficulty":"Intermediate","category":"Wall Tricks","howto":"A wall ride flown backward. Approach the wall from the side and roll onto it as for a wall ride, and once you are moving parallel to the wall, throw a 180 yaw (which reads as a flip on its side) to face backward. Center the sticks and float backward down the wall, then blip away to recover the line, still facing backward. Optionally yaw forward again to finish. Riding it backward is the whole point.","mastery":["Roll onto the wall and ride it backward.","Clean 180 into a steady backward wall ride.","Smooth reverse wall ride, dialed switch, tidy recovery."],"steps":["Approach wall from the side","Moving parallel to the wall, 180 yaw to face backwards","Facing backwards, center sticks to float through the wall ride","Blip away to recover the line, ending facing backwards","Optionally yaw forward facing again"],"prereqs":["A solid forward wall ride","A clean 180 yaw against the wall"],"practice":"Get the forward wall ride dialed, then practise the 180 to backward while riding, floating down the wall facing back before you blip away. Keep your gap steady once you are backward.","mistakes":["A slow 180 that drifts you off the wall","Losing your gap once backward","Not recovering the line cleanly off the wall"],"variations":[{"name":"Reverse Wall Kiss","note":"A backward tap instead of a full ride."},{"name":"Wall Ride","note":"The forward version.","slug":"wall-ride"}],"related":[{"name":"Wall Ride","note":"The forward version this builds on.","slug":"wall-ride"},{"name":"Snapback","note":"Another quick reversal.","slug":"snapback"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":87,"pdfPage":89,"slug":"reverse-wall-ride","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":null,"Lh":false,"Rh":false},{"L":[[-0.35,0.35]],"R":[[0.35,0.35]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/reverse-wall-ride/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=2koGdcQ1XOU"}]},{"name":"Reversed Power Flip","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop with a reversed flip folded in at the top. Approach under the object gaining throttle, and once you are under it with momentum, pitch up into the loop. Near the top, facing up, throw a forward flip, spun the opposite way to the loop, then complete it coming down the other side and pass back under the object.","mastery":["Powerloop with a reversed flip at the top.","Clean loop, tidy reversed flip at the apex.","Seamless reversed power flip, both rotations crisp."],"steps":["Approach under object gaining throttle; with momentum, pitch drone up","Facing up near the top of the loop, do a forward flip","Complete it coming down the other side and pass under the object"],"prereqs":["A solid powerloop","A clean flip both directions"],"practice":"Get the powerloop dialed, then add the reversed flip at the top: reach the apex facing up, throw the flip, and complete it coming down the far side. Give yourself height over the obstacle.","mistakes":["Flipping before you reach the top of the loop","Not committing the throttle up the loop","A sloppy flip that breaks the main loop"],"variations":[{"name":"Power Flip","note":"The flip spun the other way.","slug":"power-flip"},{"name":"Powerloop","note":"Without the flip at the top.","slug":"powerloop"}],"related":[{"name":"Power Flip","note":"The mirror version.","slug":"power-flip"},{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"}],"sources":["Pro Whooper"],"page":88,"pdfPage":90,"slug":"reversed-power-flip","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/reversed-power-flip/"}]},{"name":"Rubik's Cube","difficulty":"Intermediate","category":"Open Air","howto":"A multi-axis combo that turns the quad on every axis in turn, like twisting a Rubik's Cube: a flip on the pitch axis, a flat yaw, and a roll to finish. Flip, pin the yaw, and roll out. Chaining all three axes cleanly on one line is the puzzle.","mastery":["Flip, yaw, and roll in one line.","Clean three-axis combo, each turn crisp.","Seamless Rubik's Cube, every axis smooth and on line."],"steps":["Flip on the pitch axis","Pin a flat yaw","Roll out to finish"],"prereqs":["Clean flips, rolls, and yaw spins","A feel for chaining axes"],"practice":"Have each axis solid on its own, then chain them on one line: flip, yaw, roll, keeping the line straight through all three. Smooth the hand-offs between the turns.","mistakes":["Drifting off line between the turns","Rushing one axis into the next","An uneven turn on one of the axes"],"variations":[{"name":"Cubik's Rube","note":"The same axes in a different order.","slug":"cubik-s-rube"},{"name":"Rubik's Cube Pendulum","note":"A Rubik's Cube swung on a pendulum.","slug":"rubik-s-cube-pendulum"}],"related":[{"name":"Roll","note":"The roll axis.","slug":"roll"},{"name":"Loop","note":"The pitch axis.","slug":"loop"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":89,"pdfPage":91,"slug":"rubik-s-cube","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"originator":"Fireblast FPV (video example)","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/rubiks-cube/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=y5ZnxXhxNiM"}]},{"name":"Sideways Powerloop","difficulty":"Intermediate","category":"Powerloops","howto":"A powerloop flown yawed sideways, so the loop is driven by roll instead of pitch. Approach under the object with forward momentum and yaw so you are facing sideways, then once under it feed in throttle and roll to carry the loop up and over. Cut the throttle at the top while inverted, then catch it and continue back under the object. It is the powerloop rotated ninety degrees.","mastery":["Loop the bar sideways, driven by roll.","Round sideways loop with a clean catch.","Tight, committed sideways powerloop, dead on line."],"steps":["Approach under object with forward momentum and yaw","Once under the object, begin the powerloop with throttle and roll","Cut throttle at the top of the loop while inverted","Catch and continue back under the object"],"prereqs":["A confident powerloop","Comfortable flying yawed sideways"],"practice":"Have the powerloop dialed, then yaw sideways and drive the same loop with roll instead of pitch. Give yourself height and commit to the roll.","mistakes":["Not committing the roll through the loop","Clipping the bar mid-loop","Losing the sideways yaw through the loop"],"variations":[{"name":"Powerloop","note":"The pitch-axis version.","slug":"powerloop"},{"name":"Side Loop","note":"A sideways loop without an obstacle.","slug":"side-loop"}],"related":[{"name":"Powerloop","note":"The pitch-axis version.","slug":"powerloop"},{"name":"Side Loop","note":"A roll-axis loop.","slug":"side-loop"}],"sources":["Mazta FPV tutorial"],"page":90,"pdfPage":92,"slug":"sideways-powerloop","inputs":[{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=LcYJFd3gMEQ"}]},{"name":"Sideways Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"A rewind flown sideways, like a backwards lookback. Roll about thirty degrees to bank the line, then feed in throttle and coordinate the roll and pitch to carry the turn round to a point. From that point begin the rewind, bringing it back the way you came and ending facing backwards.","mastery":["Bank out, point the turn, and rewind back.","Smooth banked slide into a clean pointed rewind.","Buttery sideways rewind, ending dead backwards."],"steps":["Roll slightly, around 30 degrees","Throttle up and coordinate roll / pitch","Begin the rewind","End backwards facing"],"prereqs":["A smooth coordinated banked turn","A feel for rewinding a line"],"practice":"Start with a smooth banked turn, then tighten it to a point and rewind out of it, ending facing backwards. Keep the roll and pitch coordinated through the point.","mistakes":["A rounded turn with no point to rewind out of","Uncoordinated roll and pitch through the turn","Not ending cleanly backwards"],"variations":[{"name":"Stall Rewind","note":"A vertical rewind.","slug":"stall-rewind"},{"name":"Side-Lock Rewind","note":"A rewind past an object.","slug":"side-lock-rewind"}],"related":[{"name":"Stall Rewind","note":"The vertical version.","slug":"stall-rewind"},{"name":"Side-Lock Rewind","note":"A tracking rewind.","slug":"side-lock-rewind"}],"sources":["Mazta FPV tutorial"],"page":91,"pdfPage":93,"slug":"sideways-rewind","inputs":[{"L":null,"R":[[-0.5,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-0.7,-0.7]],"Lh":false,"Rh":false},{"L":[[0.2,-0.98]],"R":[[0.2,0.98]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=JRv6e2CGwMA"}]},{"name":"Slides / Grinds","difficulty":"Intermediate","category":"Wall Tricks","howto":"Sliding or grinding the quad along the top edge of a rail, ledge, or wall. Ease onto the edge, slide along it keeping light, steady contact, and peel off the end. It is proximity flying taken to the limit, riding a line instead of just passing near it.","mastery":["Slide the rail and peel off clean.","Steady grind along the edge, controlled peel.","Long, smooth grind held tight to the rail."],"steps":["Ease onto the rail","Slide along the top edge","Peel off the end"],"prereqs":["Confident proximity flying near a surface","A soft, steady touch"],"practice":"Find a clean, straight rail or ledge and practise easing on, holding a light slide, and peeling off. Keep the contact gentle so you do not snag. Scout the edge first.","mistakes":["Pressing too hard and snagging","Drifting off the edge","A rough peel-off that catches"],"variations":[{"name":"Wall Ride","note":"Riding a vertical face.","slug":"wall-ride"},{"name":"Perch","note":"Settling on top instead of sliding.","slug":"perch"}],"related":[{"name":"Wall Ride","note":"Riding a vertical face.","slug":"wall-ride"},{"name":"Perch","note":"Resting on top of an object.","slug":"perch"}],"sources":["Rotor Riot"],"page":92,"pdfPage":94,"slug":"slides-grinds","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"}]},{"name":"Split Stall Matty Rewind","difficulty":"Intermediate","category":"Split-S","howto":"A high line dropped through a Split-S straight into a matty. Approach high above the object, and just above it cut the throttle into a Split-S with a 180 roll. Blip the throttle into a forward flip that carries you round the matty curve, then float down and catch it with throttle to continue under the object flying backwards. The two rotations trace a reverse S on the way down.","mastery":["Split-S into a matty and out under the object.","Clean Split-S, tidy matty, smooth catch underneath.","Seamless split-matty drop, backwards under, dead on line."],"steps":["Approach high above the object","Just above the object, Split-S: cut throttle with a 180 roll","Just above it, blip throttle into a forward flip into a matty","Float down, catch with throttle, continue under the object backwards"],"prereqs":["A clean Split-S","A solid Matty and a confident catch"],"practice":"Have the Split-S and the Matty solid on their own, then chain them above the object: cut throttle into the split, blip into the flip, and catch it underneath flying backwards. Give yourself height above the object.","mistakes":["A rough hand-off between the split and the matty","Not blipping enough to carry the flip round","Clipping the object on the way under"],"variations":[{"name":"Stall Matty Rewind","note":"Without the split entry.","slug":"stall-matty-rewind"},{"name":"Split Yaw","note":"A split flown over and under with yaw.","slug":"split-yaw"}],"related":[{"name":"Matty Flip","note":"The over-and-under it is built on.","slug":"matty-flip"},{"name":"Stall Rewind","note":"The rewind it finishes with.","slug":"stall-rewind"}],"sources":["Pro Whooper"],"page":93,"pdfPage":95,"slug":"split-stall-matty-rewind","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-0.5]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/split-stall-matty-rewind/"}]},{"name":"Split Yaw","difficulty":"Intermediate","category":"Split-S","howto":"Fly forward towards an object and perform a Split S as you fly over it. While descending, incorporate a 180° yaw spin and conclude by smoothly transitioning into backward flight, passing beneath the object.","mastery":["Reverse and drop under the object flying backward.","Smooth split with the yaw blended into the descent.","Seamless roll, pull, and 180 yaw into a clean backward pass."],"steps":["Pass over the object","Once past the object, Split-S with a 180 roll to face down","Follow the roll quickly with a 180 yaw","Continue backwards under the object, toward the starting direction"],"prereqs":["A solid Split-S","A controllable flat yaw spin"],"practice":"Build it from a clean Split-S first, then layer the yaw in during the descent so the two blend into one motion. A bar or gap gives you the over-then-under line to aim for.","mistakes":["Yawing too early, before the half loop is established","The yaw and pull fighting, so the exit wobbles","Not enough altitude to finish the descent under the object"],"variations":[{"name":"Split Yaw Rewind","note":"Rewind back over the object out of the yaw."},{"name":"Double Split Yaw","note":"Carry a full 360 of yaw through the descent."}],"related":[{"name":"Split S","note":"The base reverse-and-descend.","slug":"split-s"},{"name":"Yaw Spin","note":"The flat spin folded into the descent.","slug":"yaw-spin"},{"name":"Half Matty","note":"Another half-rotation reversal.","slug":"half-matty"}],"sources":["Pro Whooper"],"page":94,"pdfPage":96,"slug":"split-yaw","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/split-yaw/"}]},{"name":"Split-S Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"A Split-S that only goes half way, then rewinds back out. Approach the object from above with some momentum, and as you pass it roll into a partial Split-S that curves down behind it. When you reach the object's own height, punch the throttle to rewind and pop back up, flying out the way you came. The line never drops below the object.","mastery":["Partial Split-S behind the object, then rewind out.","Clean roll into the drop, tidy rewind back up.","Precise partial Split-S, tight turn at height, smooth rewind."],"steps":["Approach the object from above with some momentum","Roll to perform a partial Split-S","At the object's mid-height, punch throttle and rewind out"],"prereqs":["A solid Split-S","A feel for the stall-and-rewind"],"practice":"Approach from above, roll into a partial Split-S behind the object, and punch the throttle to rewind before you drop below it. Keep the turn tight at the object's own height.","mistakes":["Dropping below the object instead of turning at its height","Blowing through the turn","A harsh punch that overshoots the rewind"],"variations":[{"name":"Split S","note":"Without the rewind.","slug":"split-s"},{"name":"Stall Rewind","note":"A vertical stall rewind.","slug":"stall-rewind"}],"related":[{"name":"Split S","note":"The reversal it starts with.","slug":"split-s"},{"name":"Stall Rewind","note":"A vertical rewind.","slug":"stall-rewind"}],"sources":["Mazta FPV tutorial"],"page":95,"pdfPage":97,"slug":"split-s-rewind","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=1K6DLayjxJ8"}]},{"name":"Split-S to Stall Track","difficulty":"Intermediate","category":"Split-S","howto":"A partial Split-S taken around an object and tracked back. Come in low with some momentum and climb before the object, rolling into a partial Split-S that carries you over the top and down the far side. At about the object's mid-height, punch the throttle to rewind out and track back close to the line you came in on, optionally yawing out at the end.","mastery":["Partial Split-S around the object, then track back.","Clean climb and roll, tidy turn behind the object.","Precise partial Split-S, tight turn, smooth track home."],"steps":["Approach the object with some momentum","Roll to perform a partial Split-S","At the object's mid-height, punch throttle and rewind out","Optionally add a yaw out at the end"],"prereqs":["A clean Split-S","A confident stall and rewind"],"practice":"Climb before the object and roll into the partial Split-S, then punch the throttle at its mid-height to turn around and track back close to your entry line. Add the yaw out once the rest is smooth.","mistakes":["Carrying too much speed to turn cleanly","Dropping the object out of frame","A harsh, uneven pull out of the Split-S"],"variations":[{"name":"Split-S","note":"Without the stall."},{"name":"Stall Rewind","note":"A stall taken into a rewind.","slug":"stall-rewind"}],"related":[{"name":"Split-S","note":"The base reversal."},{"name":"Stall Rewind","note":"A stall taken into a rewind.","slug":"stall-rewind"}],"sources":["Mazta FPV tutorial"],"page":96,"pdfPage":98,"slug":"split-s-to-stall-track","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=N1YRL3P7wVA"}]},{"name":"Splitback","difficulty":"Intermediate","category":"Split-S","howto":"A Split-S with a backflip folded in at the top. Half roll to inverted, then snap a backflip right there before pulling through the descending half loop as in a Split-S. Catch it at the bottom and continue out. The split reverses you and the flip adds the style.","mastery":["Split-S with a backflip folded in at the top.","Smooth split with a clean backflip once inverted.","Seamless backflip and Split-S as one flowing line."],"steps":["Half roll to inverted","Do a full backflip","Catch and continue out"],"prereqs":["A solid Split-S","A clean backflip"],"practice":"Build it from a clean Split-S, then add the backflip once you are inverted and before the descent. Keep the flip tight so it does not eat the altitude you need for the split.","mistakes":["Flipping before the half roll completes","A loose flip that drifts off the line","Losing altitude awareness through the combo"],"variations":[{"name":"Split S","note":"Without the backflip.","slug":"split-s"},{"name":"Splitback Rewind","note":"Rewind back out of it."}],"related":[{"name":"Split S","note":"The base reverse-and-descend.","slug":"split-s"},{"name":"Double Roll","note":"Shares the barrel-roll exit.","slug":"double-roll"}],"sources":["Pro Whooper"],"page":97,"pdfPage":99,"slug":"splitback","inputs":[{"L":null,"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":true},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/splitback/"}]},{"name":"Stall Half Matty Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"Fly toward an object and execute a 180° yaw spin as you pass it. After clearing the object, add a small amount of throttle and perform a Half Matty to rewind back past the object.","mastery":["Yaw past the object and Half Matty back over it.","Clean 180 yaw into a smooth Half Matty rewind.","Seamless yaw, Half Matty, and rewind past the object."],"steps":["Approach the object, 180 yaw before passing under","Behind the object, throttle up to its height while pitching down","Brief stall at the object's height, then a 180 roll","Continue down and back under the object backwards"],"prereqs":["A controllable 180 yaw","A solid Half Matty"],"practice":"Get the 180 yaw and the Half Matty dialed on their own, then chain them: yaw before you pass under, climb only to the object's own height behind it, and roll off the stall to drop back under backwards.","mistakes":["Yawing too slow, drifting past the object","Climbing past the object's height instead of stalling at it","Losing the object on the way back under"],"variations":[{"name":"Half Matty","note":"Without the leading 180 yaw.","slug":"half-matty"},{"name":"Stall Matty Rewind","note":"A full Matty rewind instead.","slug":"stall-matty-rewind"}],"related":[{"name":"Half Matty","note":"The rewind half of the move.","slug":"half-matty"},{"name":"Split Yaw","note":"Another yaw-and-reverse over an object.","slug":"split-yaw"}],"sources":["Pro Whooper"],"page":98,"pdfPage":100,"slug":"stall-half-matty-rewind","inputs":[{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-half-matty-rewind/"}]},{"name":"Stall Matty Rewind","difficulty":"Intermediate","category":"Rewinds","howto":"A Matty flown to a stall and rewound back. Pass under the object, then pitch back as if starting a powerloop so you sweep up the far side. Once you are facing up, throw a forward flip until you are inverted facing back toward the start, then ride it down and pass under the object backwards. Yaw back forwards to finish.","mastery":["Sweep up past the object and flip back under it.","Clean pitch-back into a smooth flip and rewind.","Precise stall, tidy forward flip, exact pass back under."],"steps":["Approach the object, passing under it","Past the object, pitch back as if doing a powerloop","Facing up, forward flip to inverted facing back toward the start","Pass under the object backwards","Yaw back forwards"],"prereqs":["A solid Matty Flip","A feel for the stall at the top"],"practice":"Get the sweep up the far side smooth first, then work in the forward flip at the top before you ride it back down. Keep the object framed through the flip and the pass back under.","mistakes":["Flipping before the stall settles","Losing the object on the way back under","Not clearing the object underneath"],"variations":[{"name":"Half Matty","note":"Without the stall pause.","slug":"half-matty"},{"name":"Stall Half Matty Rewind","note":"Add a 180 yaw on the pass.","slug":"stall-half-matty-rewind"}],"related":[{"name":"Half Matty","note":"The rewind half of the move.","slug":"half-matty"},{"name":"Stall Half Matty Rewind","note":"A yaw-and-Matty rewind.","slug":"stall-half-matty-rewind"}],"sources":["Pro Whooper"],"page":99,"pdfPage":101,"slug":"stall-matty-rewind","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-matty-rewind/"}]},{"name":"Tracking Front Flip","difficulty":"Intermediate","category":"Matty Flips","howto":"A front flip flown around an object while keeping it framed the whole way round. Approach on the throttle, pitching up as you climb, and once you are level with the object and facing it, pitch back and cut the throttle so you begin turning around it, tracking it as you go. Float around until you are upside down, then cross-coordinate a roll and yaw back to upright and continue under it toward where you started.","mastery":["Flip while keeping an object framed.","Clean front flip, subject held in view.","Tight tracking flip, object locked in frame throughout."],"steps":["Approach the object, throttling up and pitching up","Level with it, pitch back and cut throttle, turning around it","Float around until inverted, then cross-coordinate roll/yaw upright","Continue under the object back toward the start"],"prereqs":["A clean front flip","A feel for framing a subject"],"practice":"Climb to the object's height, then pitch back and let it carry you around it, keeping it framed. Work the roll-and-yaw back to upright once you come through inverted. Give the object room.","mistakes":["Losing the object as you come around","Drifting toward or away from the subject","An uncoordinated roll/yaw that leaves you off-axis"],"variations":[{"name":"Flip","note":"Without tracking a subject.","slug":"flip"},{"name":"Juicy Tracking-Lookback","note":"Tracking taken to a lookback.","slug":"juicy-tracking-lookback"}],"related":[{"name":"Flip","note":"The base rotation.","slug":"flip"},{"name":"Matty Flip","note":"A flip framed over an object.","slug":"matty-flip"}],"sources":["Mazta FPV tutorial"],"page":100,"pdfPage":102,"slug":"tracking-front-flip","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=th4Y8HVnG4Q"}]},{"name":"Trippy Spin","difficulty":"Intermediate","category":"Orbitals","howto":"Start by performing a Cradle. Once inverted with the object at the top of the screen, execute a coordinated roll and yaw to keep the object at the top of the screen as you orbit around it. From the right side of the object, roll right while yawing left (and vice versa from the left).","mastery":["Complete an inverted orbit keeping the object roughly framed.","Round orbit with the object held near the top of the frame.","Smooth, constant inverted orbit, object locked top-center throughout."],"steps":["Climb inverted into position beside the pole top","Roll and yaw opposite ways to orbit, object held up top","Unwind and descend away"],"prereqs":["Comfortable inverted, holding a hang","Coordinated roll-and-yaw (orbits)"],"practice":"Use an isolated pole or post with room around it. Get comfortable inverted first, then add the orbit slowly. Keeping the object pinned at the top of the frame is the whole game.","mistakes":["Roll and yaw out of sync, so the orbit wobbles","Losing the object out of frame","Dropping the inverted hang mid-orbit"],"variations":[{"name":"Double Trippy Spin","note":"Two inverted orbits before unwinding."},{"name":"Trippy Switch","note":"Reverse the spin direction mid-orbit.","slug":"trippy-switch"}],"related":[{"name":"Orbits","note":"The upright, ground-level version.","slug":"orbits"},{"name":"Yaw Spin","note":"Spinning in place rather than orbiting.","slug":"yaw-spin"},{"name":"Inverted Yaw Spin","note":"The inverted flat spin without the orbit.","slug":"inverted-yaw-spin"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":101,"pdfPage":103,"slug":"trippy-spin","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[-1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/trippy-spin/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=HbUVa1IUfFs"}]},{"name":"Trippy Switch","difficulty":"Intermediate","category":"Orbitals","howto":"A Trippy Spin that reverses direction mid-orbit. Get inverted and orbit the top of an object as in a Trippy Spin, then switch the spin the other way, unwinding back around before you descend away. Keeping the object framed through the reversal is the hard part.","mastery":["Orbit inverted, switch direction, and unwind.","Clean switch with the object held framed.","Smooth inverted orbit and reversal, object locked in view."],"steps":["Climb inverted into position beside the pole top","Roll and yaw opposite ways to orbit, object held up top","Switch spin directions","Unwind and descend away"],"prereqs":["A solid Trippy Spin","Reversing a coordinated roll-and-yaw cleanly"],"practice":"Have the Trippy Spin dialed first, then practise switching the spin direction smoothly without losing the object. It is a control test, so keep the reversal gentle and framed.","mistakes":["Losing the object at the switch","A jerky reversal that wobbles the orbit","Dropping the inverted hang mid-switch"],"variations":[{"name":"Trippy Spin","note":"Without the switch.","slug":"trippy-spin"},{"name":"Double Rolling Trippy Spin","note":"Add rolls to the orbit.","slug":"double-rolling-trippy-spin"}],"related":[{"name":"Trippy Spin","note":"The base inverted orbit.","slug":"trippy-spin"},{"name":"Orbits","note":"The upright, single-direction version.","slug":"orbits"}],"sources":["Pro Whooper"],"page":102,"pdfPage":104,"slug":"trippy-switch","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[-1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/trippy-switch/"}]},{"name":"True Barani","difficulty":"Intermediate","category":"Miscellaneous","howto":"A split-s with the second half of the rotation flown on the yaw axis instead of the pitch axis. Come in above an object and start what looks like a split-s, coordinating roll and pitch until you are pointed straight down. From there, rather than pulling the nose through, hang on the descent and yaw slowly around to face back up, then carry on underneath the object flying backwards. The slow, deliberate yaw out of the vertical is what makes it a barani and not a split-s.","mastery":["Stop a split-s nose-down and yaw out of it.","Smooth split-s entry into a controlled yaw around.","Slow, hanging barani flown right over the object."],"steps":["Approach above object, setting up for a split-s","Just past it, coordinate roll/pitch to face down","Right after facing down, hanging juicy yaw to face up","Continue path backwards under the object"],"prereqs":["A clean split-s","Comfortable holding a nose-down hang"],"practice":"Fly plain split-s's over an object until the entry is automatic, then start stopping the rotation at nose-down and holding it. Once you can hang there, add the yaw and slow it right down. The whole trick reads on how unhurried that yaw looks.","mistakes":["Rushing the yaw so it reads as a split-s","Starting the rotation before you are past the object","Dropping too much altitude in the hang"],"variations":[{"name":"Barani","note":"The looser, less deliberate version.","slug":"barani"},{"name":"Split S","note":"The same entry finished on pitch instead of yaw.","slug":"split-s"}],"related":[{"name":"Split S","note":"The entry it is built on.","slug":"split-s"},{"name":"Barani","note":"The same idea flown less deliberately.","slug":"barani"}],"sources":["Pro Whooper"],"page":103,"pdfPage":105,"slug":"true-barani","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[0,-1]],"R":[[-0.7,0.7]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/true-barani/"}]},{"name":"Vanny Roll","difficulty":"Intermediate","category":"Open Air","howto":"Approach an obstacle like a tree or pole and yaw-spin around it, tracking it through 180 degrees. Blip the throttle and cross past the obstacle with a coordinated 360 roll, keeping the line smooth, then blip once more and yaw out to fly away clean. It blends a tracking yaw, a rolling cross, and a yaw exit into one flowing pass.","mastery":["Track the obstacle 180 and cross with a full roll.","Smooth yaw-track, a clean crossing roll, and a tidy yaw out.","Seamless track, coordinated roll, and yaw exit as one flowing line."],"steps":["Approach the obstacle, yaw-spin tracking it 180","Throttle blip and cross with a coordinated 360 roll","Another throttle blip and yaw out"],"prereqs":["A controllable flat yaw spin and object tracking","A clean coordinated 360 roll"],"practice":"Pick an obstacle with room around it, a tree or a pole. Get the 180 yaw-track smooth first, then add the rolling cross and the yaw-out, blending the three into one continuous pass. Keep the throttle blips light.","mistakes":["Losing the obstacle out of frame during the yaw-track","A stiff or off-axis crossing roll","Heavy throttle blips that break the flow"],"variations":[{"name":"Double Vanny","note":"Two rolling crosses linked around the obstacle."},{"name":"Vanny Flick","note":"Blend a juicy flick into the crossing roll."}],"related":[{"name":"Yaw Spin","note":"The tracking yaw at the start.","slug":"yaw-spin"},{"name":"Roll","note":"The coordinated 360 across the middle.","slug":"roll"},{"name":"Orbits","note":"Another obstacle-tracking maneuver.","slug":"orbits"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":104,"pdfPage":106,"slug":"vanny-roll","inputs":[{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"originator":"Alex Vanover (Captain Vanover)","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/vanny-roll/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=PpTKsZgn6h8"}]},{"name":"Trippy Figure 8","difficulty":"Advanced","category":"Orbitals","howto":"A trippy spin carried across two objects. Set up as you would for a trippy spin on the first pole, inverted with the object held at the top of the frame, and orbit it. Where the two objects come closest, cross the waist and swap both sticks, so the orbit unwinds and rewinds the other way around the second pole. The ground track comes out as a figure 8, and the reversal at the crossing is what makes it one rather than two orbits flown back to back.","mastery":["Link an orbit of each object with a reversal between them.","Even loops either side, the reversal clean and the objects framed.","Continuous figure 8, both objects locked top-center throughout."],"steps":["Climb inverted up between the two objects","Trippy orbit the first, roll and yaw opposite ways","At the waist, swap both sticks to reverse the spin","Hold the reversed orbit round the second object","Unwind and fly out over the back"],"inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":[[-1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[-1,0]],"Lh":true,"Rh":true},{"L":[[0,1]],"R":null,"Lh":true,"Rh":false}],"prereqs":["A solid Trippy Spin either direction","Comfortable reversing a coordinated roll and yaw"],"practice":"Two poles or posts a few metres apart, with clear air around both. Fly a trippy spin on each object on its own first, in both directions, before joining them. The reversal at the waist is the hard part: get it happening at the same place every time, because that is what keeps the two loops even.","mistakes":["Reversing early or late, so the loops come out lopsided","Losing the second object while the spin is unwinding","Dropping the inverted hang through the reversal","Objects too far apart to cross the waist without a straight run"],"variations":[{"name":"Trippy Spin","note":"One object, no reversal.","slug":"trippy-spin"},{"name":"Trippy Switch","note":"The reversal on its own, around a single object.","slug":"trippy-switch"}],"related":[{"name":"Trippy Spin","note":"The orbit each half is built from.","slug":"trippy-spin"},{"name":"Trippy Switch","note":"Where the direction change comes from.","slug":"trippy-switch"},{"name":"Pole Dance","note":"Upright orbits of a single pole.","slug":"pole-dance"},{"name":"Orbits","note":"The upright, ground-level version.","slug":"orbits"}],"sources":[],"page":null,"pdfPage":null,"addedOnSite":true,"slug":"trippy-figure-8"},{"name":"540 Delayed Front Flip","difficulty":"Advanced","category":"Open Air","howto":"A one and a half rotation flip flown off a blip, with the yaw hanging on the end of it. Blip the throttle and roll into a tight arc, let it drop off the back and catch it facing backwards, then blip hard again straight up and pitch into the flip. Pump the throttle through the rotation, up as the sky comes into view and down as the ground does, and carry it all the way round to inverted. Hang there and yaw 180, then catch on a last blip and roll out. Flown properly it tracks one straight line the whole way.","mastery":["Get through a 540 and catch it.","Clean blip-and-catch into a paced 540.","Seamless 540 with a hanging yaw, dead on line."],"steps":["Start with a throttle blip and right roll","Catch at the bottom facing backwards with another blip, then pitch up for a backflip","Flip 540: throttle up as you see the sky, down when facing the ground, through to inverted","When upside down, do a 180 yaw spin","Catch with a throttle blip and roll out"],"prereqs":["A reliable throttle blip and catch","A committed backflip past inverted"],"practice":"Get the blip-and-catch on its own first, backwards and level, because everything after it depends on that catch. Then add the flip and work the throttle pumping until the rotation holds its height. The hanging yaw at the end comes last, once the 540 stops costing you altitude.","mistakes":["Missing the backwards catch and dropping out the bottom","Flat throttle through the flip, so it sinks","Stopping the rotation at 360 instead of carrying to inverted","Rushing the yaw instead of letting it hang"],"variations":[{"name":"540 Flip + Roll + Inverted Yaw Spin","note":"A longer 540 combo.","slug":"540-flip-plus-roll-plus-inverted-yaw-spin"},{"name":"Laser Flip","note":"The snapped flip on its own.","slug":"laser-flip"}],"related":[{"name":"Laser Flip","note":"A tight, snapped flip.","slug":"laser-flip"}],"sources":["Mazta FPV tutorial"],"page":105,"pdfPage":107,"slug":"540-delayed-front-flip","inputs":[{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,1],[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=OGJq7kl8WVs"}]},{"name":"540 Half Matty","difficulty":"Advanced","category":"Matty Flips","howto":"Execute a precise 540° roll (1.5 full rotations) and immediately follow it with the second half of a Matty flip.","mastery":["Get the 540 round and come out backwards.","Clean 1.5 rolls into a crisp flip upright.","Precise 540, tight flip, exact backward line through the gap."],"steps":["Approach gap with a 540 roll","Just after the 540 when upside down, 180 flip to upright facing backwards","Continue backwards through the gap, optionally yaw out"],"prereqs":["A precise, countable 540 roll","A clean Half Matty"],"practice":"Get the 540 stopping dead inverted on its own, out in the open with no gap to worry about, because the flip has nowhere to go if the roll is off. Then chain the flip on immediately and only add the gap once the pair runs together without a pause.","mistakes":["Over or under rotating the 540 so the flip starts off-axis","A gap between the roll and the flip","Coming out of the flip still drifting sideways"],"variations":[{"name":"540 Matty","note":"Add the full flip instead of the half."},{"name":"Half Matty","note":"Without the leading 540 roll.","slug":"half-matty"}],"related":[{"name":"Half Matty","note":"The half-roll reversal it ends with.","slug":"half-matty"},{"name":"Matty Flip","note":"The full Matty.","slug":"matty-flip"},{"name":"Double Roll","note":"Shares the multi-rotation roll.","slug":"double-roll"}],"sources":["Pro Whooper"],"page":106,"pdfPage":108,"slug":"540-half-matty","inputs":[{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/540-half-matty/"}]},{"name":"Double Side Roll + 180 Inverted Yaw Spin","difficulty":"Advanced","category":"Open Air","howto":"Two side rolls chained into a 180 inverted yaw spin, all on one line. Build forward momentum and yaw ninety degrees so you are travelling sideways, which is what puts the rolls on their side. Blip the throttle into the first roll and blip again into the second, then a third blip lifts you to a point where you pitch down to inverted. Yaw 180 while you are upside down and roll out. Even, matched rolls and a line that never wanders are what make it read.","mastery":["Two side rolls and an inverted 180.","Clean, even rolls flowed into a pinned inverted 180.","Seamless double side roll and inverted 180, dead on line."],"steps":["Gain forward momentum then do 90 degree yaw","Throttle blip and first roll, blip again and second roll","Throttle blip and pitch drone down inverted","Once inverted, 180 yaw","Roll out to finish"],"prereqs":["A clean side roll","A pinned inverted yaw"],"practice":"Get one side roll landing on heading before doubling it, because a first roll that finishes off-axis leaves nowhere to start the second. Then work the blip timing so the two rolls sit at the same height, and only add the inverted 180 once the pair runs without a correction between them.","mistakes":["Uneven rolls that wander off line","Skipping the blip so the second roll sinks","Rushing into the inverted 180","Losing orientation inverted"],"variations":[{"name":"Double Roll","note":"Without the inverted 180.","slug":"double-roll"},{"name":"Rapid Split-S + Inverted Yaw Spin Combo","note":"A Split-S version.","slug":"rapid-split-s-plus-inverted-yaw-spin-combo"}],"related":[{"name":"Double Roll","note":"The rolls it starts with.","slug":"double-roll"},{"name":"Inverted Yaw Spin","note":"The inverted pivot.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":107,"pdfPage":109,"slug":"double-side-roll-plus-180-inverted-yaw-spin","inputs":[{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Nc8VvKV7BSM"}]},{"name":"Flip Rewind to Inverted Yaw Spin","difficulty":"Advanced","category":"Rewinds","howto":"A flat bounce rewind with an inverted yaw spin folded in at the top. Punch a roll and let it dish down toward the deck, correct the roll just before the ground, then punch a forward loop back up and, once you come around to upside down, pin an inverted yaw spin. When you are ready, roll out to finish and fly away.","mastery":["Flip-rewind to inverted, spin, and roll out clean.","Smooth loop into a pinned inverted spin, tidy roll-out.","Crisp flip-rewind, dialed inverted 360, dead-level roll-out."],"steps":["Punch a roll","Correct it near the ground","Punch a forward loop","Once inverted, do a yaw spin","Now, roll out"],"prereqs":["A confident flat bounce rewind","A clean inverted yaw spin"],"practice":"Get the flat bounce rewind dialed first (roll to the deck, forward loop up), then add an inverted yaw spin at the top before you roll out. Keep it over one spot and give yourself room.","mistakes":["Rushing into the spin before you are inverted","Losing the spin off-axis","A messy roll-out after the spin"],"variations":[{"name":"Flat Bounce Rewind","note":"Without the inverted yaw spin.","slug":"flat-bounce-rewind"},{"name":"Inverted Yaw Spin","note":"The spin on its own.","slug":"inverted-yaw-spin"}],"related":[{"name":"Flat Bounce Rewind","note":"The rewind it is built on.","slug":"flat-bounce-rewind"},{"name":"Inverted Yaw Spin","note":"The spin pinned at the top.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":108,"pdfPage":110,"slug":"flip-rewind-to-inverted-yaw-spin","inputs":[{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=rsA_llKYtSE"}]},{"name":"Forani","difficulty":"Advanced","category":"Matty Flips","howto":"A forward barani: a front flip with a half twist folded into it, so you reverse direction without ever rolling. Approach the object and pitch forward through 180 until you are upside down and facing back the way you came. The moment you are there, yaw 180. Then pitch down, slowly, until you are upright, carrying on backwards through the gap as you do it. Doing the whole reversal on pitch and yaw is what separates it from a Half Matty.","mastery":["Flip, yaw, and pitch back upright without a stall.","Clean forward barani through a gap.","Seamless Forani, every rotation slow and deliberate."],"steps":["Approach object, forward 180 flip","As soon as upside down facing backwards, 180 yaw","Slowly pitch the drone down until upright while moving backwards through the gap"],"prereqs":["A controllable front flip you can stop inverted","A pinned 180 yaw"],"practice":"Work the half flip on its own until you can stop it dead inverted, out in the open with no gap involved, because the yaw has nothing to sit on if the flip overshoots. Then add the yaw, and only last the slow pitch back upright. The slower that final pitch looks, the better the trick reads.","mistakes":["Over-rotating the first flip past inverted","Yawing before you are properly upside down","Snapping the final pitch instead of drawing it out","Drifting off the line through the gap"],"variations":[{"name":"Half Matty","note":"The same reversal flown on a roll.","slug":"half-matty"},{"name":"Barani","note":"The backward version.","slug":"barani"}],"related":[{"name":"Half Matty","note":"The roll-based reversal.","slug":"half-matty"},{"name":"Barani","note":"The same idea the other way round.","slug":"barani"}],"sources":["Pro Whooper"],"page":109,"pdfPage":111,"slug":"forani","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/forani/"}]},{"name":"Half Mavvy","difficulty":"Advanced","category":"Maverick Loops","howto":"A Maverick loop taken only half way round, the reversal made with a roll instead of finishing the arc. Come in level underneath the object and pitch back as you pass beneath it, so you climb out the far side. Once you are round and pointing up, blip the throttle and roll 180, which leaves you inverted rather than carrying on over the top. From there pitch down and let the momentum you already have take you back under. Timing the roll to the moment you are facing up is the whole trick.","mastery":["Get round the far side and roll to inverted.","Clean climb into a pinned 180 roll.","Seamless Half Mavvy, roll timed to the top of the arc."],"steps":["Approach level under the object, pitching the drone back once passing under it","Once facing up on the other side of the object, throttle blip, then 180 roll","Once upside down, pitch drone down but continue momentum back under the gap"],"prereqs":["A confident Maverick loop","A pinned 180 roll"],"practice":"Fly the climb out on its own first and get used to arriving at the top with the nose up and something left in reserve, because a roll started from a dying climb will just drop you. Then add the blip and the roll together, and only worry about the exit line once inverted feels settled.","mistakes":["Rolling before you are properly facing up","No blip, so the roll costs all your height","Carrying on over the top instead of stopping at inverted","Losing the object on the way back under"],"variations":[{"name":"Maverick Loop","note":"The full loop, no roll.","slug":"maverick-loop"},{"name":"Mavvy Roll","note":"A Maverick loop with a roll folded in.","slug":"mavvy-roll"}],"related":[{"name":"Maverick Loop","note":"The full version.","slug":"maverick-loop"},{"name":"Reversed Power Flip","note":"The same arc, reversed at the top.","slug":"reversed-power-flip"}],"sources":["Pro Whooper"],"page":110,"pdfPage":112,"slug":"half-mavvy","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"originator":"Shauny D","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/half-mavvy/"}]},{"name":"Immelmatt","difficulty":"Advanced","category":"Powerloops","howto":"An Immelmann reversal flown around an object and finished like a Matty. Come in level underneath the object and pitch back as you pass beneath it, so you climb out the far side. Once you are round and pointing up, roll 180, which is the Immelmann half of it and leaves you inverted. From there pitch forward and let the momentum you already carry take you back under the object. Getting the roll to land exactly as the nose comes up is what keeps the two halves reading as one figure.","mastery":["Climb out the far side and roll to inverted.","Clean Immelmann roll flowed into the return.","Seamless Immelmatt, roll timed to the top of the climb."],"steps":["Approach level under the object, pitching the drone back once passing under it","Once facing up on the other side of the object, 180 roll","Once upside down, pitch drone down but continue momentum back under the gap"],"prereqs":["A clean Immelmann","A pinned 180 roll"],"practice":"Fly the climb out on its own until you reliably arrive at the top with the nose up and speed in hand, because a roll started off a dying climb just drops you. Then put the roll on the end of it, and only worry about the line back under once inverted feels settled.","mistakes":["Rolling before the nose is properly up","Losing height through the roll","Pitching forward too hard and killing the momentum","Losing the object on the way back under"],"variations":[{"name":"Immelmann","note":"The climbing reversal on its own.","slug":"immelmann"},{"name":"Half Mavvy","note":"The same arc with a blip into the roll.","slug":"half-mavvy"}],"related":[{"name":"Immelmann","note":"The reversal it is built on.","slug":"immelmann"},{"name":"Half Mavvy","note":"The same shape, blipped into the roll.","slug":"half-mavvy"}],"sources":["Pro Whooper"],"page":111,"pdfPage":113,"slug":"immelmatt","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/immelmatt/"}]},{"name":"Inverted Uh-uh","difficulty":"Advanced","category":"Open Air","howto":"The 'no-no' head shake flown at an inverted stall. Throttle punch up and invert, then at the top, while upside down, wag the yaw: 90 to the left, back 90 to the right, and 90 to the left again, like shaking your head no. Finish by rolling out of inverted and flying away. It is a cheeky shake held at the top of an inverted pop-up.","mastery":["Punch to inverted, wag the yaw no-no, and roll out.","Clean invert, even left-right-left yaw, tidy roll-out.","Crisp inverted stall with a sharp no-no shake and clean exit."],"steps":["Throttle punch and invert","When upside down, yaw left 90 degrees","Yaw back right 90 degrees","Yaw left 90 again, then roll out from inverted"],"prereqs":["A confident punch to inverted","Quick, controllable yaw"],"practice":"Get the punch-to-inverted stall dialed first, then add the yaw wag at the top, left-right-left, keeping it over one spot. Roll out cleanly to finish. Start high with plenty of room.","mistakes":["Drifting off the spot during the yaw wag","Uneven or lazy yaw shakes","A messy roll-out from inverted"],"variations":[{"name":"Inverted Yaw Spin","note":"A full inverted 360.","slug":"inverted-yaw-spin"},{"name":"Yaw Spin","note":"An upright flat spin.","slug":"yaw-spin"}],"related":[{"name":"Inverted Yaw Spin","note":"A full inverted spin.","slug":"inverted-yaw-spin"},{"name":"Yaw Spin","note":"An upright flat spin.","slug":"yaw-spin"}],"sources":["Pro Whooper"],"page":112,"pdfPage":114,"slug":"inverted-uh-uh","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/inverted-uh-uh/"}]},{"name":"Inverted Yaw Spin","difficulty":"Advanced","category":"Open Air","howto":"Perform a 180° Pitch/Roll to invert, swiftly follow with an inverted 360° Yaw spin, and conclude with a Flip/Roll in the same direction.","mastery":["Invert, spin 360 on yaw, and recover upright.","Hold the inverted hang and pin a clean flat spin before recovery.","Stable inverted hang, crisp 360 spin, smooth same-direction exit."],"steps":["Blip and flip to an inverted hover at the top of a climb","Hold the inverted hang and yaw a full 360","Flip back upright the same way and recover"],"prereqs":["A solid yaw spin upright","Confident flip to an inverted hover"],"practice":"This one wants altitude and commitment. Nail the flip-to-inverted and the upright yaw spin separately first, then combine them. The spin has to fire in the brief inverted float, so timing beats force.","mistakes":["Spinning before the hang settles, so it drifts","Missing the inverted timing and dropping out","Recovering the wrong direction, fighting the spin"],"variations":[{"name":"Inverted Yaw Spin Rewind","note":"Reverse back along the line out of the spin.","slug":"inverted-yaw-spin-rewind"},{"name":"Double Inverted Spin","note":"Two inverted rotations before recovery."}],"related":[{"name":"Yaw Spin","note":"The upright version this builds on.","slug":"yaw-spin"},{"name":"Trippy Spin","note":"An inverted spin orbiting an object.","slug":"trippy-spin"},{"name":"Juicy Flick","note":"Shares the invert-and-recover feel.","slug":"juicy-flick"}],"sources":["Pro Whooper","Rotor Riot","Mazta FPV tutorial"],"page":113,"pdfPage":115,"slug":"inverted-yaw-spin","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/inverted-yaw-spin/"},{"label":"Rotor Riot","url":"https://rotorriot.com/blogs/tutorials-guides/fpv-freestyle-tricktionary"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=WunRnnUI4Wc"}]},{"name":"Inverted Yaw Spin Rewind","difficulty":"Advanced","category":"Rewinds","howto":"An inverted yaw spin rewound back to upright. Throttle punch up and invert, then at the top, while upside down, yaw left 90 and back right 90 as your inverted spin. Finally, pitch back to bring the quad upright again as you come down and level out, completing the move. It pops up inverted for the spin, then unwinds back the way it came.","mastery":["Invert, spin left-right, and rewind back upright.","Clean invert, tidy yaw spin, smooth rewind to level.","Crisp inverted spin rewound dead-level on the exit."],"steps":["Throttle punch and invert","When upside down, yaw left 90 degrees","Yaw back right 90 degrees","Invert back to upright completing the move"],"prereqs":["A confident punch to inverted","A clean inverted yaw spin"],"practice":"Get the punch-to-inverted and the inverted yaw dialed first, then add the pitch back to upright as you come down, keeping it over one spot and leveling out clean. Start high with plenty of room.","mistakes":["Rushing the yaw before you are inverted","Not fully inverting back to upright","Leveling out off-heading"],"variations":[{"name":"Inverted Uh-uh","note":"A yaw wag at the top instead of the rewind.","slug":"inverted-uh-uh"},{"name":"Inverted Yaw Spin","note":"The spin without the rewind.","slug":"inverted-yaw-spin"}],"related":[{"name":"Inverted Yaw Spin","note":"The spin it builds on.","slug":"inverted-yaw-spin"},{"name":"Inverted Uh-uh","note":"The same inverted pop, with a yaw wag.","slug":"inverted-uh-uh"}],"sources":["Mazta FPV tutorial"],"page":114,"pdfPage":116,"slug":"inverted-yaw-spin-rewind","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=T7uEolLo_9c"}]},{"name":"Inverted Yaw Track Rewind","difficulty":"Advanced","category":"Rewinds","howto":"An Inverted Yaw Tracking pass, then rewound back the way you came. Roll to inverted as you approach and yaw all the way around the object, then invert back upright on the far side. To rewind, invert again and yaw back around the object the other way, inverting upright once more as you arrive back at the start. Keeping the object framed through both passes is the challenge.","mastery":["Yaw around an object inverted, then rewind it.","Clean inverted yaw-track flowed into a smooth rewind.","Crisp track and rewind, object framed throughout."],"steps":["Approach the object and roll inverted","Facing the object, yaw around it","Invert back upright","Begin the rewind, invert again in reverse","Rewind the yaw around the object","Invert back upright, back at the start"],"prereqs":["A confident Inverted Yaw Tracking pass","A feel for rewinding a line"],"practice":"Get the inverted yaw-track around an object dialed first, then practise reversing it: invert again and yaw back the other way, arriving upright where you started. Keep the object framed both ways and start slow.","mistakes":["Losing the object out of frame through either pass","Reversed yaw sending it the wrong way inverted","An uneven rewind that doesn't retrace the line"],"variations":[{"name":"Inverted Yaw Tracking","note":"Without the rewind.","slug":"inverted-yaw-tracking"},{"name":"Inverted Yaw Spin Rewind","note":"A full spin instead of a track.","slug":"inverted-yaw-spin-rewind"}],"related":[{"name":"Inverted Yaw Tracking","note":"The tracking pass.","slug":"inverted-yaw-tracking"},{"name":"Inverted Yaw Spin Rewind","note":"The spin-and-rewind.","slug":"inverted-yaw-spin-rewind"}],"sources":["Mazta FPV tutorial"],"page":115,"pdfPage":117,"slug":"inverted-yaw-track-rewind","inputs":[{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=er4Pm-nJK0E"}]},{"name":"Inverted Yaw Tracking","difficulty":"Advanced","category":"Open Air","howto":"Tracking an object while inverted, with a clean roll in and out. Roll to inverted as you approach, and once you are upside down facing the object, work the yaw to swing around it and hold it framed. Roll back upright on the way out, then blip the throttle to catch the ground before you settle. The reversed controls make the yaw-tracking the hard part.","mastery":["Track an object while flying inverted.","Smooth inverted pass, object held in view.","Object locked in frame through a full inverted pass."],"steps":["Approach the object and roll inverted","Facing the object, yaw around it","Invert back upright","Blip throttle to catch the ground"],"prereqs":["Confident sustained inverted flight","Tracking an object while yawing"],"practice":"Get comfortable holding inverted first, then add the yaw-tracking, keeping an object framed as you swing around it. Everything is reversed upside down, so start slow and wide.","mistakes":["Losing the object out of frame","Reversed yaw sending it the wrong way","Not catching the ground with a blip on the way out"],"variations":[{"name":"Orbits","note":"Tracking upright, in a circle.","slug":"orbits"},{"name":"Trippy Spin","note":"An inverted orbit around an object.","slug":"trippy-spin"}],"related":[{"name":"Trippy Spin","note":"An inverted orbit.","slug":"trippy-spin"},{"name":"Orbits","note":"Upright object tracking.","slug":"orbits"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":116,"pdfPage":118,"slug":"inverted-yaw-tracking","inputs":[{"L":[[0,1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/inverted-yaw-tracking/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=UpNEeSRyPbQ"}]},{"name":"Jackie Chan","difficulty":"Advanced","category":"Wall Tricks","howto":"A wall-runner: up the face of a wall, a bonk at the top, and a matty back the way you came. Pass underneath the wall low and, once you are out the far side, throttle up and pitch back so you climb its face. As the nose comes up, cut the throttle and keep pitching until you are looking at the ground, arriving into the wall for a light bonk rather than a hit. Blip the throttle to soften that contact, pitch down to reverse, and ride the matty back under the wall to where you started. The bonk should barely register; the climb and the reversal are what carry it.","mastery":["Get up the wall, touch it, and come back down.","Clean climb into a soft bonk and a tidy matty out.","Seamless Jackie Chan, tap barely felt, exit dead on line."],"steps":["Pass under the object, throttle up on the opposite side pitching the drone up","When facing up, throttle down, continue pitching up until facing the ground, with a wall tap","Blip throttle to soften the wall tap, then pitch the drone down to reverse into a matty","Catch and backwards towards the start"],"prereqs":["A confident powerloop","A soft, controlled wall bonk","A solid matty"],"practice":"Get the climb up the face on its own first, without touching anything, so you know how much throttle carries you to the top with the nose coming over. Add the bonk only once you can arrive there slowly, because the tap is meant to be a touch, not a stop. The blip and the reversal come last.","mistakes":["Arriving at the wall too fast and hitting it properly","No blip, so the tap kills all the momentum","Not pitching far enough to be looking at the ground","Drifting off line on the way back under"],"variations":[{"name":"Power Switch Tap","note":"The same idea on a horizontal object.","slug":"power-switch-tap"},{"name":"Wall Ride","note":"Running the face rather than bonking it.","slug":"wall-ride"}],"related":[{"name":"Power Switch Tap","note":"The horizontal-object version.","slug":"power-switch-tap"},{"name":"Matty Flip","note":"The reversal it finishes with.","slug":"matty-flip"}],"sources":["Mazta FPV tutorial"],"page":117,"pdfPage":119,"slug":"jackie-chan","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"originator":"Shauny D","links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=-1CdCEsg3kU"}]},{"name":"Juicy Flick Rewind","difficulty":"Advanced","category":"Rewinds","howto":"A Juicy Flick flown out and then rewound straight back along the same line. Blip the throttle and drop it while pitching the nose down to pop up to inverted, then feed in the slow, floaty roll that gives the Juicy Flick its look. Rather than rolling all the way out and flying on, blip again at the far end and rewind the whole thing, running the roll back the other way so you retrace your path to where you started. The rewind is the flick played in reverse, so the smoother the first half, the cleaner the return.","mastery":["Flick to inverted, roll, and rewind back.","Clean juicy flick with a slow roll into a smooth rewind.","Seamless flick-roll-rewind, floaty and dead on line."],"steps":["Blip the throttle then drop it while pitching drone down","Do the slow roll of the Juicy Flick","Quick throttle blip and rewind the Juicy Flick with reverse roll"],"prereqs":["A confident Juicy Flick","A clean blip-and-catch to reverse on"],"practice":"Get the Juicy Flick itself floaty and repeatable first, because the rewind is only as good as the flick you are reversing. Then work stopping it at the far end and running the roll back the other way, keeping the line the same out and back. Film it: the two halves should mirror.","mistakes":["A harsh flick that leaves nothing to rewind cleanly","Not blipping at the turnaround, so the rewind sinks","Rolling the rewind the same way instead of reversing it","Drifting off the line so out and back do not overlap"],"variations":[{"name":"Juicy Flick","note":"The flick without the rewind.","slug":"juicy-flick"},{"name":"Double Juicy","note":"Two flicks linked instead of reversed."}],"related":[{"name":"Juicy Flick","note":"The flick it rewinds.","slug":"juicy-flick"},{"name":"Juicy Eject","note":"The same floaty pop, ejected out.","slug":"juicy-eject"}],"sources":["Mazta FPV tutorial"],"page":118,"pdfPage":120,"slug":"juicy-flick-rewind","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[-0.98,-0.2]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=bwDXG8olfcM"}]},{"name":"Lookback + Roll + Inverted Yaw Spin","difficulty":"Advanced","category":"Open Air","howto":"A lookback, a roll, and an inverted yaw spin strung along one gently rising and falling line. Blip the throttle and pitch the nose down to flip to inverted, facing back the way you came, the lookback flown as a flip rather than a yaw. Level off on the horizon and roll a quick 360, then, still inverted and level, pin a full inverted yaw spin. Roll out to finish. It chains three distinct rotations, so smoothing the hand-offs between them is the whole game.","mastery":["Flip to inverted, roll, spin, and roll out.","Clean flip and 360 roll into a pinned inverted spin.","Seamless flip-roll-spin-out, floaty and dead on line."],"steps":["Throttle blip, then pitch the drone down to flip facing backwards upside down","Once aligned with the horizon and inverted, do a quick 360 roll","Once back aligned with the horizon and inverted, perform inverted yaw spin","Roll out"],"prereqs":["A flip to inverted you can stop on the horizon","A pinned inverted yaw spin"],"practice":"Get the flip stopping clean and level inverted first, because the roll and the spin both need a settled horizon to start from. Then add the 360 roll, and last the inverted spin, chaining them on one line and keeping it straight through all three. Build the pace up as the hand-offs smooth out.","mistakes":["Not levelling on the horizon before the roll","Drifting off line between elements","A jerky hand-off into the spin","Losing orientation on the inverted spin"],"variations":[{"name":"Lookback & Loop","note":"A lookback into a loop instead.","slug":"lookback-and-loop"},{"name":"Side Lookback + Inverted Yaw Spin","note":"A side-track version.","slug":"side-lookback-plus-inverted-yaw-spin"}],"related":[{"name":"Lookback & Loop","note":"A simpler lookback combo.","slug":"lookback-and-loop"},{"name":"Inverted Yaw Spin","note":"The spin it ends on.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":119,"pdfPage":121,"slug":"lookback-plus-roll-plus-inverted-yaw-spin","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=Hvy04PiWypw"}]},{"name":"Matty 360","difficulty":"Advanced","category":"Matty Flips","howto":"A Matty with a full yaw spin folded in. Approach passing over the object and throw a front flip at the far edge. As you come over the top facing up at the sky, work in a complete 360 yaw so you spin once, then, still facing up, carry on backwards under the object. Blending the spin in without losing the object is the challenge.","mastery":["Add a full yaw 360 to the Matty pass-under.","Clean Matty with a smooth 360 folded in.","Seamless Matty and a crisp 360, object framed throughout."],"steps":["Approach passing over object, then perform front flip","Once facing up to the sky, do a 360 yaw","Once facing back up to the sky, continue backwards under object"],"prereqs":["A clean Matty Flip","A controllable flat yaw 360"],"practice":"Have both the Matty and a flat 360 dialed first, then fold the spin into the under-pass. Keep the object framed as long as you can through the spin.","mistakes":["Rushing the 360 and losing the object","The spin dragging you off the return line","Under or over rotating the yaw"],"variations":[{"name":"Matty Flip","note":"Without the added 360.","slug":"matty-flip"},{"name":"Matty Twister","note":"A yaw twist during the flip instead.","slug":"matty-twister"}],"related":[{"name":"Matty Flip","note":"The base trick.","slug":"matty-flip"},{"name":"Yaw Spin","note":"The 360 folded in.","slug":"yaw-spin"},{"name":"Split Yaw","note":"Another Matty-family spin blend.","slug":"split-yaw"}],"sources":["Pro Whooper"],"page":120,"pdfPage":122,"slug":"matty-360","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/matty-360/"}]},{"name":"Matty Roll","difficulty":"Advanced","category":"Matty Flips","howto":"A Matty with a full roll folded in. Approach passing over the object and throw a front flip at the far edge. As you come over the top facing up at the sky, roll a full 360, then, still facing up, carry on backwards under the object. The roll adds style without changing the line.","mastery":["Add a roll to the Matty pass-under.","Clean Matty with a smooth roll folded in.","Seamless Matty and roll, object framed throughout."],"steps":["Approach passing over object, then perform front flip","Once facing up to the sky, do a 360 roll","Once facing back up to the sky, continue backwards under object"],"prereqs":["A clean Matty Flip","A controllable roll"],"practice":"Have the Matty dialed first, then add the roll on the under-pass. Keep the roll rate matched to your speed so it flows, and keep the object framed.","mistakes":["Rolling too fast, off the line","Losing the object through the roll","Clipping the object under"],"variations":[{"name":"Matty 360","note":"A yaw 360 instead of a roll.","slug":"matty-360"},{"name":"Matty Twister","note":"A yaw twist during the flip.","slug":"matty-twister"}],"related":[{"name":"Matty Flip","note":"The base trick.","slug":"matty-flip"},{"name":"Matty 360","note":"A yaw 360 folded in.","slug":"matty-360"}],"sources":["Pro Whooper"],"page":121,"pdfPage":123,"slug":"matty-roll","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/matty-roll/"}]},{"name":"Mavani","difficulty":"Advanced","category":"Maverick Loops","howto":"A powerloop with a 270 flip and a 180 inverted yaw folded in at the top. Come in under the object and pitch up as if starting a powerloop. When you are pointed straight up, throw a 270 forward flip so you end up inverted and facing backwards. There, at the peak, snap a 180 inverted yaw spin, then simply coast backwards to carry the loop the rest of the way round. Timing the flip and the yaw to the top of the loop is the whole trick.","mastery":["Fold a flip and a yaw into a powerloop.","Clean 270 flip into an inverted yaw at the top.","Seamless Mavani, flip and yaw timed to the peak."],"steps":["Approach under object, pitching drone up","When facing straight up, do a 270 forward flip","Once upside down facing backwards, do a 180 inverted yaw spin","Coast backwards to complete the loop"],"prereqs":["A confident powerloop","A pinned inverted yaw spin"],"practice":"Get the powerloop climb solid so you arrive at the top with height to spare, because the flip and yaw both need room at the peak. Then add the 270 flip to stop yourself inverted and backwards, and only last the inverted yaw. Build it up with plenty of altitude.","mistakes":["Over or under rotating the 270 so you are not level inverted","Rushing the yaw before the flip settles","Losing orientation through the rotations at the top","Not enough height to fit it all in"],"variations":[{"name":"Mavik's Loop","note":"The loop without the twist.","slug":"mavik-s-loop"},{"name":"Donkey Loop","note":"Another Maverick-loop variant.","slug":"donkey-loop"}],"related":[{"name":"Maverick Loop","note":"The base loop.","slug":"maverick-loop"},{"name":"Forani","note":"A barani on a Matty instead.","slug":"forani"}],"sources":["Pro Whooper"],"page":122,"pdfPage":124,"slug":"mavani","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/mavani/"}]},{"name":"Mavik's Loop","difficulty":"Advanced","category":"Maverick Loops","howto":"A powerloop with a quick pitch, roll and yaw stacked at the top. Come in under the object and pitch up as if starting a powerloop. Near the top of the loop, pitch the nose down so you end up inverted and facing backwards, then, in quick succession, snap a 180 roll to upright and a 180 yaw. With the three inputs done, simply coast the rest of the loop back under the object. Timing the pitch, roll and yaw tight to the peak is the whole trick.","mastery":["Get a pitch, roll and yaw in at the top of the loop.","Clean pitch-roll-yaw sequence timed to the peak.","Seamless Mavik's Loop, the three inputs crisp and quick."],"steps":["Approach under object pitching drone up","Near the top side of the loop, pitch drone down to face backwards upside down","In quick succession, perform a 180 roll to upright","Next quickly 180 yaw","Finally coast under the object"],"prereqs":["A confident powerloop","Quick, clean 180 roll and yaw"],"practice":"Get the powerloop climb solid so you arrive at the top with height to spare, because the three inputs all need room at the peak. Then work the pitch-to-inverted, and add the roll and yaw one at a time, keeping them quick and in order. Build it up with plenty of altitude.","mistakes":["Not enough height to fit the three inputs in","Letting the roll and yaw run together sloppily","Losing orientation through the sequence at the top","Drifting off the loop line"],"variations":[{"name":"Mavani","note":"A Maverick loop with a barani twist.","slug":"mavani"},{"name":"Donkey Loop","note":"Another Maverick-loop variant.","slug":"donkey-loop"}],"related":[{"name":"Mavani","note":"A twisting Maverick loop.","slug":"mavani"},{"name":"Powerloop","note":"A loop over an object instead.","slug":"powerloop"}],"sources":["Pro Whooper"],"page":123,"pdfPage":125,"slug":"mavik-s-loop","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/maviks-loop/"}]},{"name":"Ninja Star","difficulty":"Advanced","category":"Gaps","howto":"Spinning through a narrow gap on the knife-edge, like a thrown ninja star. Blip the throttle and roll ninety degrees on the approach so you meet the gap sideways, knife-edge, to fit the slot. Yaw a full 360 as you thread it, which on the knife-edge reads as a flip through the opening, then roll back out level on the far side. It combines the precision of a knife-edge gap with a spin, so it is as much timing as line.","mastery":["Spin through the narrow gap knife-edge.","Clean spin threaded through the opening.","Tight, fast spinning pass, dead through the slot."],"steps":["Throttle blip and approach gap with a 90 roll to face it sideways","360 yaw through the gap","Roll out on the other side of the gap"],"prereqs":["A solid knife-edge gap","A controllable spin"],"practice":"Get the knife-edge gap clean first, then add the spin, timing it so the narrow profile lines up with the slot as you pass. Start with a wider gap and tighten as your timing improves.","mistakes":["Mistiming the spin against the gap","Not enough bank to fit the slot","Clipping the sides on the way through"],"variations":[{"name":"Knife Edge","note":"A plain knife-edge gap.","slug":"knife-edge"},{"name":"Gaps","note":"A flat gap thread.","slug":"gaps"}],"related":[{"name":"Knife Edge","note":"A plain knife-edge gap.","slug":"knife-edge"},{"name":"Gaps","note":"Threading an opening flat.","slug":"gaps"}],"sources":["Pro Whooper"],"page":124,"pdfPage":126,"slug":"ninja-star","inputs":[{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/ninja-star/"}]},{"name":"Pole Dance","difficulty":"Advanced","category":"Orbitals","howto":"Orbiting an object twice while keeping it framed, the way a dancer circles a pole. Fly toward the side of the object, then pitch back and yaw around it, holding it in view as you swing round. Level back out on the far side, still watching it, then pitch back and yaw around a second time. Level out once more and let the drone drift back away. Keeping the object framed through both orbits, coordinating the pitch-back with the yaw, is the whole dance.","mastery":["Spiral around the pole and peel off cleanly.","Tight, even spiral holding the pole close.","Smooth, controlled spiral at close range, both directions."],"steps":["Fly toward side of the object","Pitch back an yaw around it, keeping object in view","Level back out, object in view","Pitch back and yaw around again keeping object in view","Level back out again object in view letting the drone back away"],"prereqs":["Confident close-proximity orbits","Coordinated pitch and yaw together"],"practice":"Pick a tall, clean pole with room around it. Start with a wide, gentle spiral and tighten the radius as your control improves. Both directions. Keeping the radius constant while climbing is the skill.","mistakes":["Losing the object out of frame through an orbit","Pitch and yaw out of sync, so the orbit wobbles","Clipping the object when you tighten in"],"variations":[{"name":"Trippy Spin","note":"An inverted orbit around the top.","slug":"trippy-spin"},{"name":"Whiplash","note":"A quick yaw whip around the pole.","slug":"whiplash"}],"related":[{"name":"Orbits","note":"The flat, single-height version.","slug":"orbits"},{"name":"Trippy Spin","note":"The inverted cousin.","slug":"trippy-spin"}],"sources":["Pro Whooper"],"page":125,"pdfPage":127,"slug":"pole-dance","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/pole-dance/"}]},{"name":"Power Drill","difficulty":"Advanced","category":"Powerloops","howto":"A dive down the face of a building or drop with full-rotation rolls all the way down, drilling like a bit. Approach the dive, then commit down the line rolling continuously, one full rotation after another, right to the bottom. Catch it there with a throttle blip to arrest the drop. It is a spectacular way to lose altitude, all controlled rotation.","mastery":["Corkscrew straight down and pull out.","Tight, even corkscrew descent, clean pull-out.","Fast, drilling descent held dead-vertical, tidy exit."],"steps":["Approach dive","Dive the path down with multiple full rotation rolls to the bottom of the dive","Catch at the bottom with a throttle blip"],"prereqs":["A confident roll and descent","Orientation through continuous rotation"],"practice":"Give yourself height and practise a tight, even corkscrew straight down, keeping it vertical and controlled, then pull out cleanly at the bottom. The continuous rotation is disorienting, so build up slowly.","mistakes":["The spiral drifting off vertical","Losing orientation in the rotation","Pulling out too late"],"variations":[{"name":"Barrel Roll","note":"A horizontal corkscrew.","slug":"barrel-roll"},{"name":"Sbang Tornado","note":"A flat-spin descent instead of a corkscrew.","slug":"sbang-tornado"}],"related":[{"name":"Barrel Roll","note":"A horizontal corkscrew.","slug":"barrel-roll"},{"name":"Powerloop","note":"Another power descent.","slug":"powerloop"}],"sources":["Mazta FPV tutorial"],"page":126,"pdfPage":128,"slug":"power-drill","inputs":[{"L":null,"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=ToWkJ2l36ag"}]},{"name":"Power Roll","difficulty":"Advanced","category":"Powerloops","howto":"A powerloop with a full roll folded in at the top, the roll-axis cousin of the powerloop family. Pass under the object, throttle up and pitch back to climb the loop. At the peak, where you are inverted, snap a 360 roll, then carry the loop the rest of the way round and catch it at the bottom, continuing under the object. Timing the roll to the inverted peak is what makes it read.","mastery":["Powerloop with a 360 roll at the inverted top.","Clean roll pinned at the peak of the loop.","Seamless power roll, the roll timed to inverted."],"steps":["Pass under the object, throttle up and begin pitching drone up","At the peak of the loop when inverted, 360 roll","Catch at the bottom of the loop continuing under"],"prereqs":["A confident powerloop","A quick, clean 360 roll"],"practice":"Get the powerloop climb solid so you arrive inverted at the top with height to spare, because the roll needs room at the peak. Then add the 360 roll right at inverted and carry the loop through. Build it up with plenty of altitude.","mistakes":["Rolling before you are level inverted at the top","A slow roll that costs the loop its shape","Losing orientation through the roll"],"variations":[{"name":"Mavvy Roll","note":"The same loop kept upright over the top.","slug":"mavvy-roll"},{"name":"Powerloop","note":"The loop without the roll.","slug":"powerloop"}],"related":[{"name":"Mavvy Roll","note":"The upright-over-the-top version.","slug":"mavvy-roll"},{"name":"Powerloop","note":"The base loop.","slug":"powerloop"}],"sources":["Pro Whooper"],"page":127,"pdfPage":129,"slug":"power-roll","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-roll/"}]},{"name":"Power Switch","difficulty":"Advanced","category":"Powerloops","howto":"A powerloop where the flip direction switches at the top. Come in under the object and pitch up to climb the loop. At the top, complete the flip to upright and hold a brief pause there, then blip the throttle and throw a forward flip the other way, switching direction. Ride the loop back down and carry on backwards under the object, on the same line you started on. The pause between the two flips is the signature.","mastery":["Loop up and switch the flip direction at the top.","Clean flip-to-upright, pause, then a forward flip.","Seamless power switch, both flips crisp at the peak."],"steps":["Approach under object, pitching drone up","At the top of the loop complete the flip to upright with a pause","Throttle blip and forward flip","Continue backwards under the object on the path you started on"],"prereqs":["A confident powerloop","Control to pause and reverse a flip"],"practice":"Get the powerloop climb solid so you arrive at the top with height to spare, then work stopping the flip upright and holding it before the second flip. The pause and the switch of direction are the hard part, so build it up with plenty of altitude.","mistakes":["No pause, so the two flips blur together","Not committing the throttle up the climb","Losing the line so the exit misses the start path"],"variations":[{"name":"Powerloop","note":"Without the switch.","slug":"powerloop"},{"name":"Power Swap","note":"A swap with a different exit.","slug":"power-swap"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Power Swap","note":"A related loop-and-swap.","slug":"power-swap"}],"sources":["Pro Whooper"],"page":128,"pdfPage":130,"slug":"power-switch","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-switch/"}]},{"name":"Power Switch Tap","difficulty":"Advanced","category":"Wall Tricks","howto":"Fly beneath an object and initiate a powerloop. At the peak of the loop, pitch back to look downward and tap the object with the bottom of your whoop. Without delay, perform a Matty flip to rewind back under the object.","mastery":["Powerloop, tap the top, and Matty out.","Clean powerloop with a soft tap into a tidy Matty rewind.","Seamless Power Switch Tap, object framed and barely touched."],"steps":["Pass under the object, throttle up on the opposite side pitching the drone up","When facing up, throttle down, continue pitching up until facing the ground, with a wall tap","Blip throttle to soften the wall tap, then pitch the drone down to reverse into a matty","Catch and backwards towards the start"],"prereqs":["A confident powerloop","A soft, precise tap and a solid Matty"],"practice":"Have the powerloop and the Matty solid, then work the tap at the peak: pitch back to look down and touch the object lightly before flipping back under. Keep the tap gentle and the object framed. Scout the object.","mistakes":["Tapping too hard and knocking off line","Delaying between the tap and the Matty","Losing the object over the top"],"variations":[{"name":"Ceiling Tap","note":"A tap on an overhead surface.","slug":"ceiling-tap"},{"name":"Wall Tap","note":"A tap on a vertical face.","slug":"wall-tap"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Matty Flip","note":"The rewind it finishes with.","slug":"matty-flip"}],"sources":["Pro Whooper"],"page":129,"pdfPage":131,"slug":"power-switch-tap","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"originator":"Shauny D (aka Jackie Chan)","links":[{"label":"Pro Whooper","url":"https://prowhooper.com/power-switch-tap/"}]},{"name":"Rapid Look Back + Slow Double Roll","difficulty":"Advanced","category":"Open Air","howto":"A study in contrast: a rapid, snapped lookback followed by a slow, deliberate double roll. Snap a rapid lookback, ease into a slow double roll, and catch level. The interplay between the sharp snap and the languid roll is the whole appeal.","mastery":["Snap a lookback, then a slow double roll.","Clean rapid lookback flowed into a smooth double roll.","Seamless snap-and-slow combo, the pace contrast crisp."],"steps":["Blip the throttle and snap a 180 forward flip, inverting while looking back","Double roll","Catch and level out"],"prereqs":["A snappy lookback","A controlled, even double roll"],"practice":"Snap the lookback sharp, then ease straight into a slow, even double roll, holding the line through both. Work the pace contrast so the snap and the slow roll each read clearly.","mistakes":["A soft lookback that does not snap","Rushing the double roll","Drifting off line between the two"],"variations":[{"name":"Look Back + Double Roll","note":"Capped with a flip.","slug":"look-back-plus-double-roll"},{"name":"Double Roll","note":"The rolls on their own.","slug":"double-roll"}],"related":[{"name":"Double Roll","note":"The rolls it uses.","slug":"double-roll"},{"name":"Lookback & Loop","note":"Another lookback combo.","slug":"lookback-and-loop"}],"sources":["Mazta FPV tutorial"],"page":130,"pdfPage":132,"slug":"rapid-look-back-plus-slow-double-roll","inputs":[{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=XtfDPieZJTI"}]},{"name":"Rapid Split-S + Inverted Yaw Spin Combo","difficulty":"Advanced","category":"Split-S","howto":"A fast Split-S dropped straight into an inverted yaw spin. Rapid Split-S over and down, level off inverted, and pin an inverted 360. The speed of the Split-S sets up the spin, so carrying it cleanly into the inverted pivot is the crux.","mastery":["Rapid Split-S into an inverted spin.","Clean fast Split-S flowed to a pinned inverted 360.","Seamless rapid Split-S and inverted spin, dead on line."],"steps":["Blip throttle and do a rapid Split-S","Level out upright, then blip throttle and pitch into inverted","Inverted 360 yaw","180 roll out to level"],"prereqs":["A fast, clean Split-S","A pinned inverted yaw spin"],"practice":"Have the Split-S and the inverted spin each solid, then chain them: come out of the fast Split-S level and inverted, and pin the spin. Keep the line straight through the transition.","mistakes":["Carrying the Split-S off line into the spin","Not leveling inverted before the spin","Losing orientation upside-down"],"variations":[{"name":"Split-S","note":"The reversal on its own."}],"related":[{"name":"Split-S","note":"The reversal it starts with."},{"name":"Inverted Yaw Spin","note":"The spin it ends on.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":131,"pdfPage":133,"slug":"rapid-split-s-plus-inverted-yaw-spin-combo","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=S7v9Pla4Lr8"}]},{"name":"Rubik's Cube Pendulum","difficulty":"Advanced","category":"Open Air","howto":"A Rubik's Cube flown on a pendulum: swing down into a pendulum arc and turn the quad's axes at the bottom before swinging back up. Swing down, turn the axes at the bottom, and swing back up and out. It marries a multi-axis combo to the momentum of a pendulum.","mastery":["Turn the axes while swinging on a pendulum.","Clean pendulum swing with the axes turned at the bottom.","Seamless Rubik's Cube Pendulum, every turn on the swing."],"steps":["Approach high, throttle blip and 180 back flip passing above the object","Cross coordinate a 360 roll, with a throttle blip in the middle of the roll","Half matty: once the roll is complete facing the sky, pitch the drone down and raise throttle to continue through the objects"],"prereqs":["A confident pendulum","A clean multi-axis combo"],"practice":"Have the pendulum and the Rubik's Cube each solid, then work the axis turns into the bottom of the swing where you have the most room. Keep the swing smooth and the turns crisp.","mistakes":["Rushing the turns and killing the swing","Losing the line at the bottom","An uneven, lopsided pendulum"],"variations":[{"name":"Rubik's Cube","note":"Without the pendulum.","slug":"rubik-s-cube"},{"name":"Pendulum","note":"The swing on its own.","slug":"pendulum"}],"related":[{"name":"Rubik's Cube","note":"The multi-axis combo.","slug":"rubik-s-cube"},{"name":"Pendulum","note":"The swing it rides.","slug":"pendulum"}],"sources":["Mazta FPV tutorial"],"page":132,"pdfPage":134,"slug":"rubik-s-cube-pendulum","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=4_-lTMsyUm4"}]},{"name":"Rufio","difficulty":"Advanced","category":"Open Air","howto":"A lively flourish: a pop up, a flip at the apex, and a roll on the way down. Pop it up, flip at the top, and roll away as you descend. It is a showy, expressive move, all about flow and attitude rather than any single hard element.","mastery":["Pop, flip, and roll away.","Clean pop into a flip and a rolling exit.","Seamless Rufio, lively and smooth, dead on line."],"steps":["Fly next to the object with a throttle punch","Cross coordinate roll while tracking the object","Blip the throttle and correct the roll","Track the object while continuing backwards"],"prereqs":["A clean flip and roll","A feel for a floaty pop"],"practice":"Pop up into a flip and flow a roll as you come down, keeping it loose and lively rather than mechanical. Work the timing so the three parts blend into one flourish.","mistakes":["A stiff, mechanical feel","Losing the line through the pop","Dropping too fast to flow the roll"],"variations":[{"name":"Juicy Flick","note":"A floaty pop to inverted.","slug":"juicy-flick"},{"name":"Rubik's Cube","note":"A tighter multi-axis combo.","slug":"rubik-s-cube"}],"related":[{"name":"Juicy Flick","note":"Another expressive pop.","slug":"juicy-flick"},{"name":"Loop","note":"The flip at its core.","slug":"loop"}],"sources":["Mazta FPV tutorial"],"page":133,"pdfPage":135,"slug":"rufio","inputs":[{"L":[[0,1]],"R":null,"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,0.2]],"Lh":false,"Rh":false},{"L":[[0.7,-0.7]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=-JyReQwHxrQ"}]},{"name":"Sbang Tornado","difficulty":"Advanced","category":"Open Air","howto":"A tornado: a flat yaw spin carried straight down into a fast, spinning descent. Set up over your spot, flat-spin straight down through a tight vertical column, and pull out to fly away at the bottom. The continuous flat rotation while dropping is what makes it a tornado, and what makes it disorienting.","mastery":["Flat-spin straight down and pull out.","Tight, even tornado descent with a clean exit.","Fast, dead-vertical tornado, tidy pull-out on line."],"steps":["Start low near the ground, throttle blip, then pitch forward until looking at the ground","Cross coordinate roll","Softly blip throttle as you see the sky, keeping the roll consistent","Repeat steps 2 and 3 for as many tornado rolls as you want","Level out to finish moving backwards"],"prereqs":["A solid flat yaw spin","Orientation through continuous rotation"],"practice":"Have the flat spin dialed, then add descent, keeping the column tight and vertical as you spin down, and pull out cleanly at the bottom. Give yourself height and build up slowly: the spinning drop is disorienting.","mistakes":["The column drifting off vertical","Losing orientation in the spin","Pulling out too late"],"variations":[{"name":"Power Drill","note":"A rolling corkscrew descent instead.","slug":"power-drill"}],"related":[{"name":"Power Drill","note":"A corkscrew descent.","slug":"power-drill"}],"sources":["Mazta FPV tutorial"],"page":134,"pdfPage":136,"slug":"sbang-tornado","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,0.2]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=BQauW42gMfE"}]},{"name":"Side Lookback + Inverted Yaw Spin","difficulty":"Advanced","category":"Open Air","howto":"An inverted sideways line dressed with a lookback and a full inverted yaw spin. Track sideways inverted, yaw back for a look, and pin an inverted 360. Holding a steady inverted side-track while swinging the view around is what makes it hard.","mastery":["Side-track inverted, look back, and spin.","Clean inverted side line into a lookback and 360.","Seamless side lookback and inverted spin, dead on line."],"steps":["Roll slightly left so the horizon sits at a small angle","Start a side lookback with a throttle blip and coordinated roll/pitch, horizon almost level leaning left","Yaw and roll for the lookback","Throttle blip and cross coordinate roll","Once inverted, yaw spin","Roll out to upright"],"prereqs":["Confident inverted side flight","A pinned inverted yaw spin"],"practice":"Get a steady inverted sideways line first, then add the lookback, and finally the full spin, keeping the line tracking through all three. Build the speed of the spin up as it smooths out.","mistakes":["The inverted side-track sagging","Drifting off line through the spin","Losing orientation inverted"],"variations":[{"name":"Inverted Lookback","note":"The look without the spin.","slug":"inverted-lookback"},{"name":"Inverted Yaw Spin","note":"The spin on its own.","slug":"inverted-yaw-spin"}],"related":[{"name":"Inverted Lookback","note":"The lookback.","slug":"inverted-lookback"},{"name":"Inverted Yaw Spin","note":"The spin.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":135,"pdfPage":137,"slug":"side-lookback-plus-inverted-yaw-spin","inputs":[{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[-0.7,-0.7]],"Lh":false,"Rh":false},{"L":[[0.5,-0.5]],"R":[[0.5,0.5]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=KEP9Ne2TuHM"}]},{"name":"SomerMatty","difficulty":"Advanced","category":"Matty Flips","howto":"A Matty with a somersault folded in above the bar. Rise over the object, somersault above the bar, and finish the Matty flip and pass back under. It stacks an extra flip on top of the Matty, so keeping the object framed through both rotations is the hard part.","mastery":["Fold a somersault into the Matty.","Clean somersault and Matty flowed together.","Seamless SomerMatty, both crisp, object framed throughout."],"steps":["Rise over the object","Forward flip above object","Matty flip and under"],"prereqs":["A solid Matty Flip","A clean flip on demand"],"practice":"Have the Matty dialed, then add the somersault above the bar, flowing it into the Matty flip. Keep the object framed through both rotations. Give it height and build up slowly.","mistakes":["Losing the object through the somersault","A rough hand-off between the two flips","Dropping onto the bar between rotations"],"variations":[{"name":"Matty Flip","note":"Without the somersault.","slug":"matty-flip"},{"name":"Double Flip","note":"Two flips without the object.","slug":"double-flip"}],"related":[{"name":"Matty Flip","note":"The base trick.","slug":"matty-flip"},{"name":"Loop to Matty","note":"A loop into the Matty instead.","slug":"loop-to-matty"}],"sources":["Mazta FPV tutorial"],"page":136,"pdfPage":138,"slug":"somermatty","inputs":[{"L":[[0,1]],"R":null,"Lh":true,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=ctaD7f9kYmE"}]},{"name":"Stall 540 Half Matty Rewind","difficulty":"Advanced","category":"Rewinds","howto":"A stall capped with a 540 spin, flowed through a half-Matty and rewound back under. Climb to a stall, spin a 540 and carry a half-Matty over, then rewind back under. It threads a spin, an over-and-under, and a rewind into one demanding line.","mastery":["Stall, spin a 540, half-Matty and rewind.","Clean 540 into a half-Matty and a smooth rewind.","Seamless stall-540-half-Matty-rewind, object framed throughout."],"steps":["Approach above the object with a 180 yaw spin passing the object","Once facing backwards, throttle blip and do a 540 roll","Once upside down, pitch down to upright and continue backwards under the object"],"prereqs":["A confident stall and 540 spin","A solid half-Matty and rewind"],"practice":"Have the 540, the half-Matty, and the rewind each solid, then chain them off a stall, keeping the object framed through the over-and-under. It is a long combo, so build it a piece at a time.","mistakes":["Rushing the 540 and drifting off line","A rough hand-off into the half-Matty","Losing the object through the rewind"],"variations":[{"name":"Stall Half Matty Rewind","note":"Without the 540 spin.","slug":"stall-half-matty-rewind"},{"name":"Five40 Half Matty","note":"The 540 half-Matty without the rewind."}],"related":[{"name":"Stall Half Matty Rewind","note":"The simpler version.","slug":"stall-half-matty-rewind"},{"name":"Stall Rewind","note":"The rewind it finishes with.","slug":"stall-rewind"}],"sources":["Pro Whooper"],"page":137,"pdfPage":139,"slug":"stall-540-half-matty-rewind","inputs":[{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stall-540-half-matty-rewind/"}]},{"name":"Stellar Eject Roll","difficulty":"Advanced","category":"Miscellaneous","howto":"A bigger, showier eject roll, tumbling through multiple rolls as you bail off the line. Cruise level, pick your out, then throw the quad into a string of rolls, ejecting away and down, and ride it out to a clean descent. It is the eject roll turned up to eleven.","mastery":["Tumble into rolls and eject away and down.","Multiple clean rolls into a controlled descent.","A big, stylish eject, rolls tumbling out and clear."],"steps":["Eject: punch up through a gap, pitch to face down","Facing down through the gap from above, pin a 360 roll","As you begin to fall, quickly pitch down","Once facing the sky, continue through the gap backwards and slowly level out"],"prereqs":["A confident eject roll","Comfortable tumbling through multiple rolls"],"practice":"Build up from a single eject roll, adding rolls as your control improves. Give yourself plenty of height, since it eats altitude fast, and keep the descent controlled.","mistakes":["Losing orientation in the tumble","Diving out of control","Running out of height"],"variations":[{"name":"Eject Roll","note":"The single-roll version.","slug":"eject-roll"},{"name":"Juicy Eject","note":"A floatier eject.","slug":"juicy-eject"}],"related":[{"name":"Eject Roll","note":"The basic version.","slug":"eject-roll"},{"name":"Roll","note":"The rotation it multiplies.","slug":"roll"}],"sources":["Pro Whooper"],"page":138,"pdfPage":140,"slug":"stellar-eject-roll","inputs":[{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/stellar-eject-roll/"}]},{"name":"540 Flip + Roll + Inverted Yaw Spin","difficulty":"Master","category":"Open Air","howto":"A big three-part combo: a 540 flip, a roll, and a full inverted yaw spin, strung along one line. Snap the 540 flip, roll on the line, and pin an inverted 360. It packs three distinct rotations into one pass, so smoothing the hand-offs is everything.","mastery":["540 flip, roll, and inverted spin in one line.","Clean 540 flip and roll into a pinned inverted 360.","Seamless 540-flip-roll-spin, every part crisp and on line."],"steps":["Blip throttle then drop throttle and snap a 540 flip","Once facing backwards, 360 roll, blipping throttle again when upright mid-roll","Once upside down, 180 yaw spin","Roll out to complete"],"prereqs":["Clean flips, rolls, and inverted spins","A feel for chaining rotations"],"practice":"Have each rotation solid on its own, then chain them along one line, keeping it straight through all three. Build the pace up only as the hand-offs clean up.","mistakes":["Drifting off line between rotations","A rushed hand-off into the spin","Losing orientation on the inverted 360"],"variations":[{"name":"540 Delayed Front Flip","note":"A 540 with a delayed flip.","slug":"540-delayed-front-flip"},{"name":"Lookback + Roll + Inverted Yaw Spin","note":"A lookback version.","slug":"lookback-plus-roll-plus-inverted-yaw-spin"}],"related":[{"name":"540 Delayed Front Flip","note":"Another 540 combo.","slug":"540-delayed-front-flip"},{"name":"Inverted Yaw Spin","note":"The spin it ends on.","slug":"inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":139,"pdfPage":141,"slug":"540-flip-plus-roll-plus-inverted-yaw-spin","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.2,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=l3Y8brXYYQw"}]},{"name":"Advanced Combo #3","difficulty":"Master","category":"Open Air","howto":"A flowing open-air showcase: a flip in, a rolling middle, and a yaw out to finish. Flip in, roll through the middle, and yaw out. It is a freestyle sampler, chaining pitch, roll, and yaw into one clean line.","mastery":["Flip, roll, and yaw out in one line.","Clean flip and rolling middle into a tidy yaw out.","Seamless advanced combo, every element crisp and on line."],"steps":["Slant sideways: blip throttle, pitch and roll left until the horizon is almost vertical (around 70 degrees)","Start a sideways rewind: yaw and roll right while pitching down","Blip throttle and roll","Once inverted, yaw spin"],"prereqs":["Clean flips, rolls, and yaw spins","A feel for stringing them together"],"practice":"Have each element solid, then chain them flip-roll-yaw on one line, keeping it straight and the hand-offs smooth. Vary the pace and make it your own.","mistakes":["Drifting off line between elements","A jerky hand-off between rotations","An uneven turn on one of the axes"],"variations":[{"name":"Rubik's Cube","note":"A tighter three-axis combo.","slug":"rubik-s-cube"},{"name":"540 Flip + Roll + Inverted Yaw Spin","note":"A bigger combo.","slug":"540-flip-plus-roll-plus-inverted-yaw-spin"}],"related":[{"name":"Rubik's Cube","note":"A three-axis cousin.","slug":"rubik-s-cube"},{"name":"Loop","note":"The flip at its core.","slug":"loop"}],"sources":["Mazta FPV tutorial"],"page":140,"pdfPage":142,"slug":"advanced-combo-3","inputs":[{"L":[[0,1]],"R":[[-0.5,-1]],"Lh":false,"Rh":false},{"L":[[0.5,-1]],"R":[[0.5,1]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":[[0.5,0]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=mjXxvsTXvBg"}]},{"name":"Barani","difficulty":"Master","category":"Powerloops","howto":"Fly beneath the object and perform half a Powerloop so the horizon sits in the top half of your field of view, execute a precise 180° inverted yaw spin, and conclude with a Matty Flip back under the object.","mastery":["Half-loop, 180 inverted yaw, and Matty out.","Clean half-powerloop and inverted 180 into a tidy Matty.","Seamless Barani, object framed through all three parts."],"steps":["Begin a powerloop under an object, pitching the drone up","Cut throttle as you invert, then 180 yaw","Half matty: follow the loop backwards, pitching the drone down as you complete the loop","Catch with a 180 yaw out"],"prereqs":["A confident powerloop","A pinned inverted yaw and a solid Matty"],"practice":"Have the half-powerloop, the inverted 180, and the Matty each solid, then chain them beneath the object, keeping the horizon and the object where you want them through each part. It takes height and commitment.","mistakes":["Rushing the inverted 180 off line","Losing the object between the parts","A rough hand-off into the Matty"],"variations":[{"name":"True Barani","note":"The open-air twisting version.","slug":"true-barani"},{"name":"Flipani","note":"A flip dressed with a barani.","slug":"flipani"}],"related":[{"name":"Powerloop","note":"The half-loop it starts with.","slug":"powerloop"},{"name":"Matty Flip","note":"The Matty it finishes with.","slug":"matty-flip"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":141,"pdfPage":143,"slug":"barani","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":[[0,0.2]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/barani/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=KiNsSFad3Rg"}]},{"name":"Donkey Loop","difficulty":"Master","category":"Maverick Loops","howto":"A Maverick loop finished with a sharp donkey-kick: a hard pitch flick on the way out. Drop into the Maverick loop beneath the bar, loop up and around, and snap a donkey-kick as you exit. The kick is what gives it the mule-like snap and the name.","mastery":["Maverick loop with a donkey-kick out.","Clean Maverick loop finished with a sharp kick.","Tight Donkey Loop, crisp kick, dead on line."],"steps":["Begin a powerloop: throttle up and pitch the drone up","Once facing up, 270 pitch the drone down to face backwards upside down","Once facing backwards, 360 inverted yaw spin","Once backwards again, begin pitch up to pass under the object completing the loop"],"prereqs":["A confident Maverick loop","A sharp, controlled pitch flick"],"practice":"Have the Maverick loop dialed, then add the kick on the exit: a hard, quick pitch flick as you come out. Keep it snappy and clear of the bar. Give yourself clearance and build up slowly.","mistakes":["A soft kick that does not read","Clipping the bar on the exit","Losing the line after the kick"],"variations":[{"name":"Mavik's Loop","note":"The loop without the kick.","slug":"mavik-s-loop"},{"name":"Mavani","note":"A Maverick loop with a twist instead.","slug":"mavani"}],"related":[{"name":"Mavik's Loop","note":"The base loop.","slug":"mavik-s-loop"},{"name":"Mavani","note":"A twisting Maverick loop.","slug":"mavani"}],"sources":["Pro Whooper","Mazta FPV tutorial"],"page":142,"pdfPage":144,"slug":"donkey-loop","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-0.5]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/donkey-loop/"},{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=NjjoxF9TO6c"}]},{"name":"Double Rolling Trippy Spin","difficulty":"Master","category":"Orbitals","howto":"A Trippy Spin with rolls folded into the inverted orbit. Get inverted and orbit the top of an object as in a Trippy Spin, but roll the quad twice as you go around, layering rolls onto the spin. Keeping the object framed through the rolling orbit is brutally hard.","mastery":["Add rolls to the inverted trippy orbit.","Clean rolling orbit, object held framed.","Seamless double-rolling trippy spin, object locked in view."],"steps":["Approach the side of the object, pitch up to begin rotation once you are facing up","Fold rolls into the spin","Pitch down drone to exit"],"prereqs":["A solid Trippy Spin","Rolling while orbiting inverted"],"practice":"Have the Trippy Spin dialed cold, then add the rolls a little at a time, keeping the object framed. It is one of the hardest orbital tricks, so expect it to take a while.","mistakes":["Losing the object through the rolls","The rolls wobbling the orbit","Dropping the inverted hang"],"variations":[{"name":"Trippy Spin","note":"Without the rolls.","slug":"trippy-spin"},{"name":"Trippy Switch","note":"A trippy spin that reverses.","slug":"trippy-switch"}],"related":[{"name":"Trippy Spin","note":"The base inverted orbit.","slug":"trippy-spin"},{"name":"Trippy Switch","note":"A reversing trippy spin.","slug":"trippy-switch"}],"sources":["Pro Whooper"],"page":143,"pdfPage":145,"slug":"double-rolling-trippy-spin","inputs":[{"L":null,"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/double-rolling-trippy-spin/"}]},{"name":"Eject Lookback Roll + Inverted Yaw Spin","difficulty":"Master","category":"Open Air","howto":"A hard eject to inverted flowed into a lookback roll and a full inverted yaw spin. Eject to inverted, lookback and roll, and pin an inverted 360. The eject launches the whole sequence, so committing to it sets up everything that follows.","mastery":["Eject, lookback-roll, and inverted spin.","Clean eject into a lookback roll and a pinned inverted 360.","Seamless eject-lookback-roll-spin, dead on line."],"steps":["Eject with a throttle punch","Forward flip","Once upside down, begin a cross coordinated 360 roll; throttle blip when the drone is upright","Continue rolling until upside down again, then begin the yaw spin","Roll out"],"prereqs":["A confident eject","A lookback roll and a pinned inverted spin"],"practice":"Have the eject, the lookback roll, and the inverted spin each solid, then chain them, committing to the eject and flowing straight into the roll and spin. Give it height and build up slowly.","mistakes":["A weak eject that stalls the combo","Losing the line through the roll","Losing orientation on the inverted spin"],"variations":[{"name":"Eject Roll","note":"Just the eject and roll.","slug":"eject-roll"},{"name":"Lookback + Roll + Inverted Yaw Spin","note":"Without the eject.","slug":"lookback-plus-roll-plus-inverted-yaw-spin"}],"related":[{"name":"Eject Roll","note":"The eject-and-roll.","slug":"eject-roll"},{"name":"Lookback + Roll + Inverted Yaw Spin","note":"The non-eject version.","slug":"lookback-plus-roll-plus-inverted-yaw-spin"}],"sources":["Mazta FPV tutorial"],"page":144,"pdfPage":146,"slug":"eject-lookback-roll-plus-inverted-yaw-spin","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":[[1,0]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=XcGlJZFV7_U"}]},{"name":"Flipani","difficulty":"Master","category":"Powerloops","howto":"A flip dressed with a barani, a twist folded in at the top of the loop. Pull into the flip, barani-twist at the top, and catch level as you fly out. It stacks a twist onto a clean loop, so coordinating the twist with the flip is the challenge.","mastery":["Add a barani twist to the flip.","Clean flip with a smooth twist at the top.","Seamless Flipani, flip and twist as one, dead on line."],"steps":["Begin a powerloop under an object, pitching the drone up","Cut throttle as you invert, then 180 yaw","Quickly follow with a 360 front flip","Half matty: follow the loop backwards, pitching the drone down as you complete the loop","Catch with a 180 yaw out"],"prereqs":["A clean flip","Comfortable twisting through a loop"],"practice":"Have the flip solid, then add the barani twist at the top, a little at a time. Keep the loop round and the line straight. Give it height and build up slowly.","mistakes":["Too much twist, throwing off the flip","Losing the line through the twist","An uneven loop out of the barani"],"variations":[{"name":"Rollani","note":"A barani off a roll instead of a flip.","slug":"rollani"},{"name":"Barani","note":"The powerloop-context barani.","slug":"barani"}],"related":[{"name":"Loop","note":"The flip it is built on.","slug":"loop"},{"name":"Rollani","note":"The roll sibling.","slug":"rollani"}],"sources":["Pro Whooper"],"page":145,"pdfPage":147,"slug":"flipani","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[0,0.2]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/flipani/"}]},{"name":"Inverted 360 Powerloop","difficulty":"Master","category":"Powerloops","howto":"A powerloop with a full flat 360 pinned at the inverted top. Carry throttle up and over the obstacle, and as you hang inverted at the peak, pin a complete 360 yaw before carrying the loop back down. Spinning while inverted at the top of a loop is as hard as it sounds.","mastery":["Add a full 360 yaw at the top of the powerloop.","Clean powerloop with a pinned 360 at the peak.","Seamless powerloop and inverted 360, dead on line."],"steps":["Approach under object, pitching drone up","At the peak of the loop, do a 360 yaw spin","Carry the loop back down"],"prereqs":["A confident powerloop","A pinned inverted yaw spin"],"practice":"Have the powerloop and the inverted spin dialed on their own, then combine them, pinning the 360 right at the top where you hang inverted. It takes height and commitment.","mistakes":["Rushing the 360 and drifting off the loop","Losing the inverted timing","Not committing the throttle"],"variations":[{"name":"Powerloop","note":"Without the spin.","slug":"powerloop"},{"name":"Inverted Yaw Spin","note":"The spin on its own.","slug":"inverted-yaw-spin"}],"related":[{"name":"Powerloop","note":"The loop it is built on.","slug":"powerloop"},{"name":"Inverted Yaw Spin","note":"The inverted spin.","slug":"inverted-yaw-spin"}],"sources":["Pro Whooper"],"page":146,"pdfPage":148,"slug":"inverted-360-powerloop","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":null,"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/inverted-360-powerloop/"}]},{"name":"Look Back + Double Roll","difficulty":"Master","category":"Open Air","howto":"The extended version: a rapid lookback, a slow double roll, and a flip to cap it. Snap a rapid lookback, flow a slow double roll, and cap it with a flip. The added flip turns the pace-contrast drill into a full showpiece.","mastery":["Lookback, slow double roll, capped with a flip.","Clean snap-and-slow combo finished with a tidy flip.","Seamless extended combo, every part crisp and on line."],"steps":["Throttle blip then lookback","When upside down looking backwards, cross coordinate a 540 roll","Once upright again still facing backwards, yaw out"],"prereqs":["A snappy lookback and even double roll","A clean flip"],"practice":"Have the rapid-lookback-slow-double-roll dialed, then add the flip on the end, flowing straight out of the roll into the loop. Keep the line true through all three.","mistakes":["A rough hand-off into the flip","Rushing the double roll","Losing the line through the combo"],"variations":[{"name":"Rapid Look Back + Slow Double Roll","note":"Without the flip.","slug":"rapid-look-back-plus-slow-double-roll"},{"name":"Advanced Combo #3","note":"Another open-air showcase.","slug":"advanced-combo-3"}],"related":[{"name":"Rapid Look Back + Slow Double Roll","note":"The shorter version.","slug":"rapid-look-back-plus-slow-double-roll"},{"name":"Loop","note":"The flip it ends on.","slug":"loop"}],"sources":["Mazta FPV tutorial"],"page":147,"pdfPage":149,"slug":"look-back-plus-double-roll","inputs":[{"L":[[0,-1]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[-0.7,-0.7]],"R":[[0.7,0.7]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":[[-1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=6NLNzgcgsns"}]},{"name":"Rollani","difficulty":"Master","category":"Powerloops","howto":"A roll leading into a barani, a twisting flip. Roll on the line, barani-twist through a flip, and catch level as you fly out. It flows a roll into a twisting loop, so the hand-off between the roll and the barani is what to smooth.","mastery":["Roll into a barani twisting flip.","Clean roll flowed into a smooth barani.","Seamless Rollani, roll and barani as one, dead on line."],"steps":["Begin a powerloop under an object, pitching the drone up","Cut throttle as you invert, then 180 yaw","Quickly follow with a 360 roll","Half matty: follow the loop backwards, pitching the drone down as you complete the loop","Catch with a 180 yaw out"],"prereqs":["A clean roll","A confident barani twist"],"practice":"Have the roll and the barani each solid, then flow one into the other, keeping the line straight through both. Give it height and build up slowly.","mistakes":["A jerky hand-off between roll and barani","Too much twist, throwing off the flip","Drifting off the line"],"variations":[{"name":"Flipani","note":"A barani off a flip instead of a roll.","slug":"flipani"},{"name":"Barani","note":"The powerloop-context barani.","slug":"barani"}],"related":[{"name":"Roll","note":"The roll it starts with.","slug":"roll"},{"name":"Flipani","note":"The flip sibling.","slug":"flipani"}],"sources":["Pro Whooper"],"page":148,"pdfPage":150,"slug":"rollani","inputs":[{"L":[[0,1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[-1,0]],"R":null,"Lh":false,"Rh":false},{"L":null,"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,0.2]],"R":[[0,1]],"Lh":false,"Rh":false},{"L":[[1,0]],"R":[[1,0]],"Lh":false,"Rh":false}],"links":[{"label":"Pro Whooper","url":"https://prowhooper.com/rollani/"}]},{"name":"Sbang Ultimate Combo","difficulty":"Master","category":"Open Air","howto":"The grand finale of the Sbang family: a tornado spun straight down, rolled out at the bottom, and flown away on a climbing escape. Drop into the tornado, spin straight down, and roll out and climb away. It packs a spinning descent and a rolling recovery into one showstopper.","mastery":["Tornado down and roll out to escape.","Clean spinning descent rolling into a smooth climb-out.","Seamless Sbang Ultimate, dead-vertical tornado, crisp escape."],"steps":["Begin a sideways skate, blip sticks in quickly, then out","Skate sideways into a rewind, with coordinated yaw/pitch/roll; horizon should be diagonal","Rewind: blip the throttle and rewind the coordinated yaw/pitch/roll, holding the diagonal horizon","Throttle blip into a 180 roll","Once inverted, pitch the drone up","Once level and upright, flat bounce rewind: blip throttle followed by pitch, then reverse pitch to level"],"prereqs":["A confident Sbang Tornado","A clean roll and a strong climb-out"],"practice":"Have the tornado and the roll-out each solid, then chain them: spin the descent tight and vertical, roll out cleanly at the bottom, and climb away. Give yourself plenty of height and build up slowly.","mistakes":["The tornado drifting off vertical","Losing orientation in the spinning descent","A ragged roll-out at the bottom"],"variations":[{"name":"Sbang Tornado","note":"The tornado without the roll-out.","slug":"sbang-tornado"},{"name":"Power Drill","note":"A rolling corkscrew descent.","slug":"power-drill"}],"related":[{"name":"Sbang Tornado","note":"The tornado it builds on.","slug":"sbang-tornado"},{"name":"Power Drill","note":"Another spinning descent.","slug":"power-drill"}],"sources":["Mazta FPV tutorial"],"page":149,"pdfPage":151,"slug":"sbang-ultimate-combo","inputs":[{"L":[[-0.5,0],[0.5,0]],"R":[[-0.5,0],[0.5,0]],"Lh":false,"Rh":false},{"L":[[0.5,-1]],"R":[[1,-0.5]],"Lh":false,"Rh":false},{"L":[[-0.5,-1]],"R":[[-0.5,0.5]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[-1,0]],"Lh":false,"Rh":false},{"L":[[0,-1]],"R":[[0,-1]],"Lh":false,"Rh":false},{"L":[[0,1]],"R":[[0,1]],"Lh":false,"Rh":false}],"links":[{"label":"Mazta FPV tutorial","url":"https://www.youtube.com/watch?v=CK4AQszHHfI"}]}];
const GLOSSARY = [{"term":"5-inch","def":"A common freestyle quad class with 5-inch props; more power and range than a whoop."},{"term":"Acro / Rate mode","def":"Manual flight mode with no self-leveling; the sticks command rotation rate. Required for nearly every freestyle trick."},{"term":"Arm","def":"Enabling the motors so the quad will spin up. You arm before takeoff (usually on a switch) and disarm to cut power."},{"term":"AUX / switch","def":"An auxiliary channel on the radio, used to arm, change modes, or trigger features mid-flight."},{"term":"Bando","def":"An abandoned building or structure that pilots treat as a freestyle playground. Short for 'abandoned'."},{"term":"Betaflight","def":"The most common open-source flight-control firmware, where rates, flight modes, and tuning are set up."},{"term":"Blip","def":"A brief tap of throttle, used to nudge altitude or kick a stalled quad back into motion."},{"term":"BNF / RTF","def":"Bind-N-Fly (needs your own radio) / Ready-To-Fly (includes everything)."},{"term":"Cinewhoop","def":"A small ducted quad built for smooth cinematic flying in tight spaces."},{"term":"CLM","def":"Camera-Locked Motion, keeping a subject fixed in frame throughout a trick, a scoring requirement in competition."},{"term":"Disarm","def":"Cutting motor power. A 'slide disarm' or 'crash and disarm' ends a line deliberately."},{"term":"Failsafe","def":"The programmed response when the quad loses its radio or video link, usually cutting the motors or holding position to prevent a flyaway."},{"term":"FPV","def":"First-Person View, flying via a live camera feed to goggles or a screen. Is not a crime."},{"term":"Freestyle","def":"Expressive, trick-oriented flying (as opposed to racing)."},{"term":"Horizon mode","def":"A self-leveling mode that still lets you flip and roll, then eases back toward level when you release the sticks. Angle mode is fully self-leveling; Acro has no leveling at all."},{"term":"Invert","def":"Flipping the quad upside-down; many tricks pass through or hold an inverted state."},{"term":"LiPo","def":"Lithium-polymer battery, the high-discharge packs that power most FPV quads. Store and charge them carefully."},{"term":"LOS","def":"Line-Of-Sight, keeping visual contact with the aircraft, often a legal requirement."},{"term":"Powerloop","def":"A loop up-and-over an obstacle using throttle through the top; also a whole trick family."},{"term":"Prop wash","def":"Turbulent air thrown off the quad's own props, felt as a jittery wobble when you descend through it or stop hard."},{"term":"Punch / punch-out","def":"A sharp burst of throttle for a fast vertical climb."},{"term":"Rates","def":"Radio settings that map stick travel to rotation speed. Lower rates = gentler, higher = snappier."},{"term":"Rewind","def":"Reversing a motion back along its entry path, often out of a stall."},{"term":"Stall","def":"Chopping throttle so the quad momentarily stops flying and hangs or drops before recovery."},{"term":"Throttle","def":"Motor power, the left stick's vertical axis in Mode 2."},{"term":"VTX","def":"Video transmitter, the part that beams the camera feed from the quad to your goggles."},{"term":"Whoop","def":"A micro ducted FPV drone (typically 65 to 85mm); safe, agile, great for learning."},{"term":"Yaw","def":"Rotation about the vertical axis, the drone turning left/right in place."}];
